/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240307-3","meetingId":"r06-c-budget","date":"2024年3月7日","dateIso":"2024-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年度品川区一般会計予算","agenda":"令和６年度品川区一般会計予算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"おはようあります。本日も１日、どうぞよろしくお願いいたします。私からは、２０９ページ、しながわシティランについてお伺いします。私も応援と視察を兼ねて、お隣は港区の、品川区ともつながっている国道の第一京浜まで伺いました。しながわシティランもちょうど１年後と近づいてまいりましたが、まずは予算についてお伺いします。７,９６８万１,０００円の内訳をお知らせください。","respondent":"三井スポーツ推進課長","answer":"しながわシティランの予算の主なものとしましては、実行委員会の負担金となっておりまして、そのうち主要なものとしては、大会運営費が約２,５００万円、警備費などの安全対策費用が約４,０００万円となっております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。そこでお伺いします。そこで、日々地域の安心・安全のために活動されている消防団の方に、警備等をご協力していただくことはいかがでしょうか。警備の方はプロだと存じますが、地域のお祭りやイベントでもご協力いただいている実績もあり、顔なじみの消防団の方が関わることによる安心感、また、運営も円滑に進むと考えますが、区のご見解をお知らせください。","respondent":"三井スポーツ推進課長","answer":"配置するスタッフの人数など、詳細はこれからになりますが、消防署にも今後協議を進めていく段階になっております。その際に、消防団の協力の依頼ができないかなど、そのようなことについてもご相談しながら検討してまいりたいと思います。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"ぜひ消防署、消防団の協力依頼を要望いたします。インターネットでの申込みですが、他自治体の大会では約６か月前頃には申込みが始まります。大会ホームページの公開も含めて、いつ頃を予定されているのかお知らせください。","respondent":"三井スポーツ推進課長","answer":"大会ホームページについては現在作成しているところですが、申込み開始時期は令和６年の９月を予定しております。","id":"exchange-003"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。今から楽しみにしております。大会要項についてお伺いいたします。参加資格ですが、障害がある方で単独走行が困難な場合は、伴走者を１名つけることができる（補助犬（盲導犬、聴導犬、介助犬）は不可）。高校生以上は公道を使用し、コース上における参加者の安全面が確保できないため、車椅子での参加は不可とする。このような参加資格に決定した経緯をお知らせください。","respondent":"三井スポーツ推進課長","answer":"参加資格は、他の大会を参考にしています。障害がある方の参加資格につきましては、今回コース上の設定状況も踏まえまして、障害者支援課とも相談しながら検討を行いまして、１２月の実行委員会で決定いたしました。","id":"exchange-004"},{"speaker":"えのした委員","kind":"確認","question":"各課と連携されていると確認が取れました。先日の区民委員会でもコース案がお示しされましたが、地図上では、前回との変更箇所で、約８km付近ですか、大井ふ頭中央海浜公園の陸上競技場、大井ホッケー競技場にコースが見直されております。こちらは、競技場の中、または競技場の外、外周を走ることになるのでしょうか。大田スタジアムと、品川区と同じく大井ホッケー競技場がコースになっておりました。","respondent":"三井スポーツ推進課長","answer":"委員のご提案のとおり、品川区はホッケータウンでもありますので、区の魅力の発信の１つとして、地域資源である大井ホッケー競技場を活用しまして、シビックプライドの醸成にもつなげていきたいと考えております。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問・要望","question":"競技場の中と確認が取れました。ランナーには大変喜ばれると思い、評価いたします。例えば電光掲示板などを利用した雰囲気を盛り上げる仕掛け、当日は競技場内やスタンドにも、応援する方が入れるような取組も要望します。今月、３月１７日に開催の品川区民マラソン大会、私も一般１０kmに申込みさせていただきました。公募の総数、また、選考方法をお知らせください。","respondent":"三井スポーツ推進課長","answer":"選考方法ですが、まずメンバーは、実行委員会の中から、会長である区長を含む５名を選定委員としまして、また、作品を審議するに当たっては、事前にデザインの有識者の方にアドバイザーとして複数作品を推薦いただき、推薦作品の中から選定委員会で協議しまして。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問・要望","question":"そしてこちらは、すぐにＳＮＳ等で情報発信、特にコースから離れている地域へのＰＲ活動、シビックプライドの醸成も踏まえた取組を要望いたします。コース案は、スタートがしながわ区民公園、ゴールは大井競馬場ですが、こちら両方の会場で開催されるのでしょうか。もしくは、どちらか一方の会場で開催されるのでしょうか。品川区民デフリンピック１００％周知啓発の取組など、区のご見解をお知らせください。","respondent":"三井スポーツ推進課長","answer":"デフリンピックの啓発というお話がありましたが、こちらは認知度向上に向けて、しながわシティランの会場内でも啓発ブースの出展ができないかなと、そのような様々な方法を考えてまいりたいと思います。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"ぜひオリパラレガシー、デフリンピック周知啓発、また、食事を楽しみながらの大会の開催、両会場の間には海岸通りがあって、車線も多く、交通量も多いですので、皆様の動線、また、安全性も踏まえての取組を要望いたします。続いて、１年前記念イベントについてお伺いします。今週末、３月１０日には、初心者向けのマラソン教室が、私の地元の荏原平塚学園で開催と、大変楽しみにしております。","respondent":"三井スポーツ推進課長","answer":"今週末に実施いたします、機運醸成として考えている１年前記念イベントの応募状況ですが、一般が５０名弱、ファミリーの部が約１７０名弱の応募となっております。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問・要望","question":"ファミリーの部約１７０名、応募多数とのことですので、ぜひ今後も幅広い年代、また、幅広い地域での開催を要望します。続いて、コース案以外の地域での取組についてお伺いいたします。区内に銭湯は２０軒以上ありますので、周知啓発を含め、浴場組合や各関係部署と連携した品川のまちの魅力の区内外への発信を含め、まちぐるみでの盛り上げが重要だと考えますが、区のご見解をお知らせください。","respondent":"三井スポーツ推進課長","answer":"実行委員会のメンバーには様々な方にご参加いただいておりますので、また、東京商工会議所品川支部の方からは、しながわシティランを活用して、関係団体と連携したデジタルスタンプラリーができないか等のご相談もいただいているところです。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民、ランナー、ボランティア、応援等、様々な形で多くの方に参加していただき、オール品川でみんなが輝く大会の開催を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、２０１ページの歩行喫煙防止推進経費、１７７ページの区施設営繕事務費についてお伺いしてまいります。初めに、歩行喫煙防止推進経費からお伺いしてまいります。品川区では、掲示物、路面標示や、シルバー人材センターと品川区生活安全サポート隊と連携したパトロールに、さらに力を入れて取り組まれていると思われます。","respondent":"河合生活安全担当課長","answer":"喫煙の関係は、苦情、要望等が多く寄せられますので、そういったものに対して即応、丁寧に対応することで、そこの環境を浄化する、よくするというところで力を入れてきております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"確認させていただきました。ですが、なかなか浸透が難しい課題だけに、区民へのさらなる周知啓発をお願いしたいと思います。全ての路上喫煙禁止・地域美化推進地区を回って見させていただきましたが、「路上喫煙禁止区域です」の表示や、「終日禁煙」の表示もある中で、路面標示では、たばこ禁止の図柄と一緒に、喫煙禁止の横に括弧書きで「過料１,０００円」と表示されているものも確認しました。","respondent":"河合生活安全担当課長","answer":"現場で苦情や要望があったときに、その場でも対応しておりますので、そういった状況は詳細には把握しておりませんけれども、貼付活動のほうは相談や要望のあったところを優先的に、また、まちの景観等も踏まえて、効果が上がるように貼付しています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私も、五反田、大井町、武蔵小山、青物横丁、大崎等で、全部で８か所確認させていただきました。これも要望があったところということで、やっていただいているということを確認させていただきました。先日も我が会派からこの点について質疑があり、関係機関と調整し、効果的なものになるように検討していくとありましたが、改めて区の見解をお聞きしたいと思います。","respondent":"河合生活安全担当課長","answer":"他法令に抵触する部分につきましては、所管の機関等、ご意見に対応するところは調整が必要ですので、そういったご意見は踏まえていきたいと考えております。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"実際に各路上喫煙禁止・地域美化推進地区を見ると、路面標示よりも横断幕が非常に目立って見えるので、所管ではない面などありますが、調整の課題もあると思いますけれども、ぜひ前向きに進めていただければと思います。そこで、たばこを吸う場所の整備、喫煙所の整備、拡充をどのように進めていくのか、区の見解をお聞きしたいと思います。","respondent":"河合生活安全担当課長","answer":"やはり区内の指定喫煙所も含めて、もっと増やしてほしいという声も実際あります。来年度に路上喫煙の実態調査等を行いますので、そういったものの結果を踏まえまして、指定喫煙所の整備、民間喫煙所への助成、そういったところを進めていきたいと考えております。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"同時に、令和４年の調査結果からは、区内の指定喫煙所がある駅でも、数多くの吸い殻が回収されていることが確認できています。統計では、たばこのポイ捨てが４６％減少しています。この取組を導入した渋谷区では、実証実験では、導入効果としてたばこのポイ捨てが約９割削減されたほか、ペットボトルや空き缶のごみも減少したとの結果が出ています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、１７５ページのＳＤＧｓ推進経費、１７７ページの情報システム運営費、２０３ページの都市型観光プラン推進事業、２１３ページのふるさと納税事業について伺います。ＳＤＧｓ推進経費に関連して伺います。当初予算案プレス発表資料に、ウェルビーイング・ＳＤＧｓ推進ファンドの創設とありますが、概要をお教えください。","respondent":"吉岡政策推進担当課長","answer":"そうした中、産学官が連携いたしまして、ウェルビーイング、ＳＤＧｓに資する地域課題の解決に向けた事業への助成を行うことで、多様な区民ニーズに対応し、区民のウェルビーイングの向上を図るという事業です。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"理解いたしました。ＳＤＧｓに関しての新しい取組を評価いたします。今回の企業支援を通じての効果検証をお願いしたいと思います。そして気が早いですが、この取組を今回だけでなく、ぜひ今後につなげていただきたいと考えます。投資や融資のファンドのように、持続可能な本格的なファンドを目指してはいかがでしょうか。区のお考えを伺います。","respondent":"吉岡政策推進担当課長","answer":"こうしたアセットマネジャーを立ててのファンド、また、区が来年度行おうとしている実行委員会形式、それぞれメリット、課題がありますので、来年度実施をしていく中で、しっかりと効果検証を行いつつ、ご意見をいただきました運営方法についても情報収集しながら。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。令和６年度の本ファンドの実施に併せ、その中で投資や融資の本格ファンドへの可能性を検討していただくことを要望いたします。区は、令和７年度末までに完全オンライン化を目標としていて、１,６６１の手続きに対して、令和５年度に５００件程度を実施できる見込みとお聞きしておりますが、令和６年度末までの達成目標は何件でしょうか。お教えください。","respondent":"河西情報戦略担当課長","answer":"行政手続きのオンライン化に関する目標についてお答えいたします。令和６年度の目標は９００手続きになります。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"令和６年度までの目標が９００手続きとすると、令和６年度の１年で４００件、令和７年度の１年で７６１件のオンライン化が必要となります。最終年度にしわ寄せとなっておりますが、最終年度への負担が大きいことが心配です。それぞれの手続きをオンラインサービスへ移行するには、具体的に誰がどのように対応するのでしょうか。お教えください。","respondent":"河西情報戦略担当課長","answer":"このシステムはオンライン決済にも対応し、簡単に手続きの受付フォームを作成できるシステムになります。手続きを所管する各課の皆さんに、研修やマニュアルを通して手続きの作成方法を習得いただき、情報推進課が支援しながら、手続きのオンライン化を進めております。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問","question":"手続き自体は各課が実施するということで理解いたしました。各課の業務負担を考えると、最終年度に集中すると厳しい可能性があるので、前倒しするように計画変更をしたほうがよいと思いますが、いかがでしょうか。１,６６１件の案件管理、台帳管理はできているのでしょうか。令和７年度までに手続きオンライン化の目標は達成できそうでしょうか。お教えください。","respondent":"河西情報戦略担当課長","answer":"委員のおっしゃるとおり、令和７年度末までに全ての手続きをオンライン化することを考えると、前倒しの検討が必要になると考えます。来年度、基本方針の改定を行う際に、現状を踏まえて見直しを検討いたします。次に、手続きの管理についてです。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"計画については、ぜひ実現可能なスケジュールに、見直しいただきたいと思います。そのようなものはやむを得ないとしても、それ以外のサービス、特に区民の皆様がよく利用するサービスについて、できる限りオンライン化ができるよう、しっかりと進めてほしいと考えます。次に、都市型観光プラン推進事業について伺います。都市型ツアーの取組についてはいかがでしょうか。お教えください。","respondent":"篠田文化観光課長","answer":"今年度の実施例で申し上げますと、例えば品川沖の台場を船で巡った後に、天王洲、大井ですね、ガイドからまち並みの変遷などを聞きながら、最後アートに触れるツアーや、あるいは品川用水と蛇窪神社を巡るツアー、そういったものを実施いたしまして。","id":"exchange-021"},{"speaker":"山本委員","kind":"提案","question":"品川区のよさに触れていただくツアーと感じますが、都市型ツアーについてご提案があります。とても面白いです。このような、区民の皆様が企画から参加する参加型ツアーをつくることがよいのではないでしょうか。区民の皆様も、区外の皆様も参加できます。実際の企画はしながわ観光協会が進めることとなると思いますが、ぜひとも後押しをしていただけないでしょうか。区のお考えを伺います。","respondent":"篠田文化観光課長","answer":"新しいツアーのご提案です。区民の方が企画して参加するような形のツアーというものは、新しい視点なのかなと受け止めました。ただ、委員からもご指摘がございましたとおり、実施、運営するに当たってはしながわ観光協会が様々関わってくるのだろうと思います。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。ぜひとも前向きに連携、そしてご検討をお願いいたします。最後にふるさと納税について伺います。先日の委員会でも、様々な意見が出されました。まだまだアイデアはあるでしょう。そこで、先ほどお話ししたように、より多くのことを考えて実現するために、アイデアを地元企業の方々や区民の皆様に募集するということがよいのではないでしょうか。区のご意見を伺います。","respondent":"提坂税務課長","answer":"令和６年度からは、クラウドファンディング型ふるさと納税の拡充に加えまして、区の魅力を発信できる体験ツアーやスポーツ体験など、様々な体験型・参加型の返礼品をさらに拡充してまいりますけれども、加えて、ふるさと納税返礼品サイトを運営している事業者には。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"既にいろいろと進めていらっしゃるということで理解はしておりますが、ぜひオープンに、地元企業の方々にもお声がけしていただいたり、区民の方にもお声がけしていただいて、広がりをつくっていただきたいと思います。応募するインセンティブを高めるため、企業や採用された方には特典を用意することを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、非核平和都市品川宣言事業、１８５ページ、私立学校関係費に関連して、品川翔英の人権侵害の問題、時間がないと思うのですが、時間があればイルミネーション設置、２０３ページなどを伺います。いずれも業務委託ということですが、伺いますけれども、現在のところこの訪問を想定している平和関連施設とは、どの辺りを考えていらっしゃるのか伺いたいと思います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言４０周年記念事業につきまして、訪問先、事業等につきましては、今現在検討しています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討していると。伺いますけれども、今回のバスツアーの訪問先に加えることを検討することも含め、区内には戦争の語り部や研究者の方もたくさんいらっしゃいますので、そうした方々のお知恵も借りて、この４０周年というものをきっかけに、区内の戦争史跡にスポットを当てるための何らかの取組を求めたいのですが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言４０周年の記念に当たりまして、ご提案いただきました。事項別のほう、都内平和バスツアー（仮称）という形で書かせていただきましたが、どのような形で区民の方に、こういった非核平和都市４０周年を伝えていけばいいのか、様々考えていきたいと思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"今回バスツアーをやりますけれども、これを４０周年で１回やって終わりというようにはしないほうがいいと思うのです。バスツアーをするかどうかは置いておいて、これからやはり身近な戦争史跡にスポットを当てるということは、ぜひ取り組んでいただければと思っています。そこで伺いますけれども、区がこの宣言を行ったと。そのような認識は区におありでしょうか。伺いたいと思います。","respondent":"勝亦総務課長","answer":"品川区といたしましては、非核平和都市品川宣言、こちらの宣言に基づいて、区民の方に平和、文化、そういったものをお伝えしていくことが務めだと考えています。それが、今委員がおっしゃった世論の形成につながったかどうかということは、判断できない部分です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ判断するところ、そのような認識を持ってほしいのです。世界の核兵器廃絶運動に貢献してきた、このすばらしい非核平和都市品川宣言だと確信を持っていただきたい。そして持った上で、この宣言をしている自治体の長として、ぜひ区長には、４０周年を迎えるこの年、区内外に核兵器禁止条約への支持を表明していただきたいと思うのですけれども、ぜひご答弁いただけたら幸いです。","respondent":"勝亦総務課長","answer":"そういった恒久平和に対する思い、こちらのほうは強く、区民の方に広く伝えていくものであると考えています。ただ、今おっしゃった条約等に関しましては、外交に関する部分ですので、国等の判断、責任なのかなと考えています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"この場では、すぐ区長からのご発言はいただけませんでしたが、共産党としてはこのような認識を持っていますので、ぜひ受け止めていただけたらと思っています。「核兵器の廃絶と恒久平和の実現を世界の自治体に呼びかけ、その輪を広げるために努力する」と書いております。ぜひこの日本非核宣言自治体協議会へ参加するよう求めたいのですけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"今、そういった自治体の輪に入るというお話をいただきました。品川区といたしましては、現在平和首長会議というものに加盟してございまして、こちらが、今国内では１,７００以上の自治体が加盟している、広い取組になってあります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"評価しているのですが、さらにこちらの協議会というものは、結構運動を進めていこうというようなところで、かなり、もう一歩踏み込んでいるところもありますので、ぜひ平和首長会議とともにこちらにも加入を検討していただくよう求めまして、次の質問に移ります。治外法権でもあるというのでしょうか。人権が及ばない公共空間が区内に存在するということについてどう考えるのでしょうか、伺いたい。","respondent":"勝亦総務課長","answer":"品川区として、これが人権侵害に当たるか否かという部分については、判断しかねる部分が、できない部分がありますので、そこについては今、治外法権等にはお答えしかねる部分があります。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ宣言をしている区がそのようなことを言えないのか、本当に尊重しているのでしょうかと疑いたくなってしまいます。ところが、先ほどの重大発言は、この品川区も宣言に載せておりますが、憲法も関係ないと言っているわけです。このような宣言に照らしても、どう見てもおかしいのではないかということで、もう１回、これは人権侵害でしょうとズバっと言っていただきたいのですが、よろしくお願いします。","respondent":"勝亦総務課長","answer":"具体的に品川翔英というようにお名前が出てまいりました。私立学校につきましては、私立学校法に基づきまして、私立高校につきましては東京都のほうに権限がありますので、まず一義的に、学校内の問題は学校内、東京都の管轄下になるかと考えております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと私はあまりにも縦割りだし、人権尊重をうたっている区とは思えない。そして、区内で起こっているわけです。実際に通っているお子さんが苦しんでいるわけです。ですから、大人の責任としても、ちょっとどうなのかと。そのような姿を見て、子どもたちが人権を尊重しますか。そして健全に育ちますか。私は、私たち全体がこれは自分の問題と受け止めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願います。私からは１８７ページ、広報経費、ホームページ、都市ブランディング推進について、１８８ページ、人権・ジェンダー平等推進費、ジェンダー平等推進条例についてお伺いいたします。そして、品川区のホームページを見ますと、要はいつ品川区のＸ（旧Ｔｗｉｔｔｅｒ）は更新されるのでしょうか。","respondent":"横田情報推進課長、辻広報広聴課長","answer":"利用者目線の画面構成ということで、利用頻度の高い機能のみをトップページに表示したシンプルな画面デザインにするですとか、高齢者、障害者を含むより多くの利用者が使えるためのアクセシビリティ基準。引き続きＸ社のほうにも問合せをしながら、Ｉｎｓｔａｇｒａｍも含めて、どういった形でホームページのトップページに載せていくことが適切かというものは考えていきたいと考えています。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願いします。一方、今までのシティプロモーション、「わ！都市ブランディングの説明に当たって、シティプロモーションという言葉を使ってもいいのかなという考えもあるのですけれども、それよりもシティプロモーションという言葉自体もあまり使わず、ブランディングという言葉に統一、一本化していくのか、その辺りをお伺いいたします。","respondent":"辻広報広聴課長","answer":"そのような意味では、今後都市ブランディングにかじを切ってやっていきたいなと考えています。それからもう一つ、シティプロモーション担当というところですが、今回組織改正がありますけれども、その中で、今度は都市ブランディング担当という名前に変更になります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。どのように可視化ということをやっていくのか、お知らせください。","respondent":"辻広報広聴課長","answer":"今委員がおっしゃったような品川区のいいところ、そういったものをいろいろな方のアンケート、ワークショップを通じて、それを可視化するということが１つと、先ほども申し上げましたとおり、将来に向かってどのような品川にしたいのかということを。","id":"exchange-035"},{"speaker":"筒井委員","kind":"提案","question":"ぜひよろしくお願いします。しかし、今回単なる啓発にとどまらず、条例というものの制定を提案されました。区民や外部に与える影響は大きくなるのかなと考えております。これから庁舎内有料広告もあります。ですから、これからやはり、この条例が制定されたとしても、区民、事業者などに対して丁寧な説明と、また、運用も丁寧にしていっていただきたいのですけれども、その点いかがお考えでしょうか。","respondent":"加島人権啓発課長","answer":"こちらにつきましては、区のほうで目指す社会を実現するために、区民、事業者等のお力を借りなければというところで定めたものです。決して強制にならぬよう、区のほうで啓発に力を入れてまいります。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"先に人事管理費から１点、職員へのインフルエンザワクチン接種費用助成について伺いたいと思います。この助成の利用率もお聞かせください。こちらは５月ですか、リニューアルを予定しておりまして、区民委員会でもご説明いただいているのですが、リニューアルすることでマルチデバイス対応、あと利用の多いものを集めて、直感的で分かりやすいトップページになるということをご説明いただきました。","respondent":"崎村人事課長、横田情報推進課長","answer":"効果といたしましては、職員の健康管理、健康増進を図るといったところで、大変効果があるものというように認識しております。新施設予約システムにつきましては、これらを解消すべく、１画面目で日時、場所、時間を全て選択できるようになり、より使いやすいシステムとなる予定です。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"インフルエンザワクチンのほうは１,０００円から２,０００円にアップしたということで、職員からの受けたいという声が多かったのではないかと思います。引き続きよろしくお願いいたします。次に、この予約システムの利用登録について伺います。利用登録についても、システム上で登録できるようにするか、電子申請を利用することによって利用者の利便性が上がると思いますが、今後の方向性を教えてください。","respondent":"横田情報推進課長","answer":"団体登録のお問合せです。これまでは施設に出向いていただきまして、団体登録をする必要がございました。新施設予約システムにつきましては、システム公開に合わせまして、品川区電子申請サービスで団体登録ができるように検討しております。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問・要望","question":"オンライン上で登録から予約までが完了すると、品川区が取り組むＤＸやＩＣＴ化が進んでいると、より実感される方も多いのではないかと思います。施設の所管とも連携していただいて、より一層の利便性向上と事務負担の軽減をよろしくお願いいたします。そういった利用の場合は団体という形ではないと思いますので、個人でも利用しやすいような登録もぜひ進めていただきたいのですが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"集会所の利用に関してお答えいたします。集会所、地域住民の集会ということですので、いわゆるお一人での、個人での利用というものはできません。ただ、複数の方でご利用いただく場合には、団体登録ということでお願いしています。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"そうですね。個人で使うことはあまりないと思うのですけれども、利用登録でも、少人数から利用登録ができたらいいなということで質問させていただきました。こちらもよろしくお願いいたします。次に、区民相談室について伺いたいと思います。相談体制や利用状況について実績を教えてください。専門相談のほうの利用状況もお願いいたします。","respondent":"辻広報広聴課長","answer":"実績ですが、令和４年度ですと、区民相談が年間で２,１２８件、法律相談が１,０３７件、それから税金相談が１８８件、そういった状況になっております。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"先日も委員会では、孤独・孤立対策についての質疑もあったと思いますが、区民相談室も１つの相談の入り口になると考えております。そのような中で、高齢の方やお体が不自由な方は、お住まいの近くの地域センターへ出張というような形で区民相談ができると、すごく寄り添った区民サービスになると思うのですが、この地域センターへの出張という形で相談することについてはいかがでしょうか。","respondent":"辻広報広聴課長","answer":"相談される方は、やはり６０代以上のご高齢の方、７０代がメインというようになっております。地域センターでの開催ということですが、必要性や有効性など、そういったことも考えながら、区民のそういった声もいただいて、また今後考えていきたいと思います。","id":"exchange-041"},{"speaker":"せらく委員","kind":"確認","question":"８割が電話ということなのですね。分かりました。地域の皆様の声にしっかり耳を傾けていただければと思います。相談の種類によって難しいものもあるかと思いますが、事業評価のほうを確認いたしますと、オンラインの研究を進める方向であるということが記載されていました。ご検討の状況や、相談の受付からの流れについて、決まっていることがあれば教えてください。","respondent":"辻広報広聴課長","answer":"オンラインでの相談についてです。ちょうどコロナ禍のときに、オンラインで相談ができないかということのお声もいただきまして、様々検討、研究、他区の状況なども調べさせていただいているところです。","id":"exchange-042"},{"speaker":"せお委員","kind":"質問","question":"私からは１９３ページ、働き方改革推進事業、２０１ページ、生活安全推進事業についてお伺いします。働き方改革のところです。ですから、職員の皆さんの働く環境というものはすごく大切にしていて、サポートしていきたいなと思っています。思いだけは理解できます。そして、今まで取り組んできているカスハラ対策はありますでしょうか。さらには、来年度予算には対策の一端が含まれているでしょうか。","respondent":"勝亦総務課長、田口人材育成担当課長、佐藤経理課長","answer":"そういった中で、まず区の対策、対応といたしまして、まず夏に、そういったクレーム、カスタマーハラスメントに近いクレームがあるかどうか。弁護士の法的な知識による講義に加えまして、ロールプレイを行うことによってハードクレームの疑似体験を行いまして。維持用消耗品等の中で、電話録音機について来年度４０台分を計上しておりまして、電話での苦情、クレームへの対応としての活用を考えております。","id":"exchange-043"},{"speaker":"せお委員","kind":"提案","question":"様々取り組んでいただいていることが分かりました。やはり電話が多いと思いますので、あとは提案するとカメラなども、それは常に監視するなどではなくて、保険としてとか、あとは先ほどちらっとおっしゃっていましたが、やはりいろいろな自治体でポスターを窓口に貼っているところも多いと思って、ぜひポスターも取り組んでいただきたいなと。今回、１点だけお話しさせてください。","respondent":"宮澤地域活動課長","answer":"来年度予算ですと、２０３ページの上段にあります、社会を明るくする運動経費の中に、再犯防止に関する経費というものが含まれております。犯罪、非行、または再犯に陥らないようにというところで、各種団体の皆様と一緒に取り組む、この運動の中に経費を入れております。","id":"exchange-044"},{"speaker":"せお委員","kind":"質問・要望","question":"社会を明るくする運動のところも、少し残念ながら、昨年の当初予算より減っているという状況で、ちょっとこの見え方としては、私が見ると、計画をつくっておしまいに見えてしまいます。再犯防止に関しては、やはり国が取り組まないとという部分は、同じ会派のえのした委員とも、刑務所などを訪れると、やはり課題がどうしても国のほうが表れてくるなということは感じています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に職員研修費についてお伺いいたします。参加者は当事者、受益者、協力者、地域の方々、資金提供者、実施組織、事業スタッフ、行政、評価専門家などです。一部の事業からこうした参加型評価を取り入れることで、地域の多様な経験と知見を持つ関係者との対話によって、区民とともに社会的価値をつくり、新たな公共マーケットを創出いただきたいと要望いたしますが、区のお考えをお聞かせください。","respondent":"田口人材育成担当課長、吉岡政策推進担当課長","answer":"今委員がおっしゃったように、多様な区民などのというところもありますが、まず今回の、来年度に実施するものにつきましては、多様なアクターの意見を集約するというところにスキルが必要ですので。区のほうで今年度実施いたしました行政評価のうち、政策評価におきましては、区民や有識者等から成る外部評価委員会を設置いたしまして、区の政策の防災、環境・ＳＤＧｓ、こちらの２分野において、評価、提言をいただいたところです。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に文化コミュニティ施設経費についてお伺いいたします。昨年９月の一般質問において、文化に対する評価は、集客の数など目に見えるものだけではなく、受け手の心にどう響いたかなど、形に表れない効果も含め判断することが必要だと考えているとのご答弁がありました。すみません。３点目もいきます。昨年１２月に、映画『記憶２ 少年たちの追憶と贖罪』の中村すえこ監督にお話を伺いました。","respondent":"篠田文化観光課長、宮澤地域活動課長","answer":"ただ、品川におきましては、先ほどご答弁申し上げたとおり、様々な幅広い支援に取り組んでいるということもありますので、今後、さらなる展開を図っていくに当たって参考にさせていただきたいと考えているところです。再犯防止推進計画、策定しました。庁内連携を進めながら、また、各種団体と連携しながら、安心・安全な地域社会を目指して取組を進めてまいります。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問","question":"最初に、区施設営繕事務費でありますが、昨年の１０月の決算特別委員会で、授乳室について区民の声をお伝えさせていただきましたので、今回、新年度予算の中にどのように反映されたのか、お伺いいたします。","respondent":"小林施設整備課長","answer":"委員ご案内のとおり、授乳室のさらなる安全性の向上というところを目的としまして、来年度につきましては、授乳室がある施設、全体で３１施設ありますが、そのうちの、防犯ブザーであったり、呼出しボタンであったり、そういったところが未設置の施設に対しまして。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。この授乳室の安全対策、しっかり予算に反映されていることが確認されました。多くの施設があると思うのですが、どの施設につけられるのか、２か年計画ということですけれども、施設名をお知らせいただきたいと思います。","respondent":"小林施設整備課長","answer":"２６施設全てというお話かと思いますので、ちょっと読み上げますと、なぎさ会館、東品川文化センター等々を含めまして、図書館では複数施設で予定されるなど、様々広く、多くの施設で整備のほうをしていく予定です。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年お声をいただいた方は、本当に不安で防犯ブザーを持って利用していたという、そのようなお声でありましたので、これから全て、３２か所ですか、既についているところもあるということもありますので、３２か所が整備されるということで、安心に思います。既に児童センターは整備がされているということで、ここは確認させていただきたいと思います。児童センターの件、ご答弁をお願いしたいと思います。","respondent":"小林施設整備課長","answer":"今後児童センター等で、授乳室等を設置する施設につきましても、逐次設置のほうは進めてまいりたいと考えているところです。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"授乳室がこのように整備されますので、施設の中における授乳室の場所が、分かりやすい、そのような表示も、また工夫をいただきたいと思いますので、よろしくお願いいたします。続きまして、八潮地区まちづくり事業についてお伺いいたします。本年度は５７５万円余ということで、昨年度より大幅増の予算がつけられておりますので、この事業内容をお聞きしたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"内容といたしましては、今年度、昨年度と行っております八潮みらい懇談会の事務経費、それから、ほかの自治体の団地等の視察、それから地元の町会との交流会といった、現地見学、交流会の移動経費といったところで、合わせまして２５万円ほど、それから来年度に関しましては。","id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"このまちづくりの業者委託、こちらのほうにかなり予算がついたというように確認させていただきました。そしてもう１点、ガイドラインの件がありましたので、このガイドラインは所管が違うのですが、まちづくりの検討の中でのガイドラインとの関連を少しお伺いしたいと思うのですが、どのようにそれが関連づけられて、活用されていくのかというところをお知らせいただきたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"そういったご意見をガイドラインの中で取りまとめしていただいておりますので、そういったご意見も、今後委託していく中では、業者とも連携、情報共有しながら、進めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、おくやみコーナーにつきまして確認します。約３０分ぐらいでありました。昨年の第３回定例会の中で、おくやみコーナーの質問をさせていただいた中で、冊子についても取り上げまして、品川区の「ご遺族の方へ」という現存の冊子から、新たなものを作っていただけるという、そのようなご答弁がありましたので、現在検討されている状況をお知らせいただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"おくやみコーナーのハンドブックですけれども、今までですが、大分小さなハンドブックでしたので、これからは少し大きくしまして、見やすい内容にしようと思っています。それから、当然大きくなりますので、いろいろな情報も加味していきたいと考えております。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして先ほど、１点お伝えし忘れましたが、区のホームページで、おくやみコーナーについてご案内していただいておりますけれども、できれば案内チラシをつくっていただいて、ダウンロードできるような、そのようにしていただけると、ご案内するときにそのページをダウンロードして、このようなものがあるのですということをお伝えしやすいと考えていますので、ぜひそのような工夫もお願いしたいと思いますが。","respondent":"吉野戸籍住民課長","answer":"今の委員のご指摘のとおり、分かりやすいものをつくっていきたいと考えております。ホームページのほうも修正したいと考えております。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして最後に選挙関連につきまして、投票支援についてお伺いいたします。今多くの自治体で、投票所入場券を発送するときに併せて、その中に自分が何の支援が必要なのかということを書けるような用紙を封筒の中に入れてほしいということを要望させていただいたのですが、今、選挙管理委員会の中で投票支援について検討されていることをお知らせいただきたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘の投票支援カードについて、現在、今年７月の都知事選挙に向けて、検討しています。入場整理券に同封して郵送ですが、検討の中で大きな課題として、個人情報保護の関係で、その支援カードが必要な方の情報を選挙管理委員会で把握できないという部分があります。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"本当に全員にそのようなものが、誰でもでありますので、封筒で送っていただきたいなという思いがありますけれども、様々課題があるということであれば、確実にその支援が必要な人が、煩わしくなく投票できますように、そのような体制をしっかり整えていただきたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は２０７ページ、歴史館運営費、イベントやＰＲ活動全般について、２０９ページ、地域スポーツ等推進経費についてお伺いします。は歴史館運営費についてお聞きします。品川歴史館が工事を終えて、４月にリニューアルオープンしますが、広報の方法やリニューアルオープンのイベント内容はどのようなものでしょうか。現在の予定をお聞かせください。","respondent":"篠田文化観光課長","answer":"当日は、リニューアルオープンとしての式典を実施するということで、そのほか、様々イベント等もやりたいとは思っていたのですけれども、やはり改めて再開に当たって、地に足をつけた運営をしていくことがまず大事だろうということで、順次運営を進めながら。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"確認","question":"運営を進めながらというお言葉を確認いたしました。このリニューアルを機に、今まで行ったことがなかった区民の方にも、ぜひ足を運んでほしいと思っています。品川区には伝統工芸保存会の職人たちがいらっしゃいます。」となっておりますので、この品川歴史館を拠点に、歴史・文化を主軸にした人の流れを、この品川区中につくっていけるといいなと思っていますが、いかがでしょうか。見解をお聞かせください。","respondent":"篠田文化観光課長","answer":"歴史館の場合、展示スペースとしては限られているものですから、なかなか細かいところまで行き届かないところはあろうかと思いますので、今後様々な企画を実施していく中で、そういった視点も含めたものが取り入れられるかどうか、検討してまいりたいと考えています。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ぜひ検討していっていただきたいと思います。続いて、区のＰＲ活動全般についてお聞きいたします。多くのフリーランスの方々は、収入も不安定です。先日の一般質問でも、石田しんご議員が、人への投資、人を育てるといった提言をしています。品川区民４０万人の力は無限大です。仕事もお金も品川区内で循環させることが、持続可能な地域の発展につながると考えますが、いかがでしょうか、見解をお伺いします。","respondent":"辻広報広聴課長","answer":"各所管がいろいろな形で、プロポーザルという形で、いろいろな事業を公募するということもあります。そういった中で、区内ゆかりのアーティストというものもありますので、そういった方をうまく起用できるように、私どものほうは情報提供等はしていきたいなと考えています。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"最後に、地域スポーツ等推進経費についてお伺いします。昨年の決算特別委員会に続いて、ラジオ体操の団体支援について再度質問します。地域の方が誰でも気軽に参加でき、毎朝そこにあるコミュニティ機能の継続と、区民の方の健康維持のために、地域スポーツの枠組みでラジオ体操の団体の方を支援していくことはいかがでしょうか。見解をお聞きします。","respondent":"三井スポーツ推進課長","answer":"スポーツ推進課では、しながわ体操をやっておりまして、一応そちらについては普及の出前を、１回当たり参加者約２０人というような形で、そのような体操の普及啓発等をしています。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問・要望","question":"しながわ体操があるということですが、地域のラジオ体操のほうも、ぜひ機会があれば検討していっていただきたいと思います。こちらは要望です。今後、品川の文化も健康も、行政として進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、２０３ページのハタチの龍馬ＰＲ事業、また２０５ページ、しながわ観光大使関連事業、時間が余りましたら、１８５ページの外国人学校児童生徒等保護者補助金についてお伺いします。そのような中で、まず冒頭お聞きしますが、品川の名産、品川といえば何があるのでしょうか。お答えください。","respondent":"篠田文化観光課長","answer":"名産といいますと、なかなか今、お土産的に使える名産というものが、例えば以前でいえば、品川海苔のようなものがありましたけれども、実際に取れるかというと、なかなか取れなかったりということがあったりするものですから、現実に今あるものとしての名産というものが。","id":"exchange-062"},{"speaker":"こしば委員","kind":"質問","question":"なかなか一言では言い表せないのかなと思います。そのような中では、私はやはり冒頭、ページのほうも言いましたけれども、観光大使であるシナモロールが１つの名産ではないかと考えます。こういったデザインの活用によって、特にマンホールデザインもそうでしょう、また投票済証もそうだと思いますが、どのような効果があったのか教えてください。","respondent":"篠田文化観光課長","answer":"こちらは、しながわ観光大使として、平成２９年からお願いをしているということで、今委員からもご紹介があったとおり、サンリオで一番人気のキャラクターですので、イベント等でシナモロールが参加するということが周知されますと、必ずマニアの方というか。","id":"exchange-063"},{"speaker":"こしば委員","kind":"質問","question":"大変ありがたいという言葉、伺いましたけれども、たくさん人が来るということは、それは大変すばらしいことだと思うのですが、この観光大使の活用によって、今度は区民が得られる利益、幸せ、ウェルビーイングという言葉でもありますけれども、それはどのように捉えているのか教えてください。","respondent":"篠田文化観光課長","answer":"これは逆に言うと、ほかの地域から見ても、シナモロールがあって品川区はいいですねと言われることが非常に多いですから、そういった意味では、非常に効果が高いと感じているところです。","id":"exchange-064"},{"speaker":"こしば委員","kind":"質問","question":"なるほどなと思いながら、このシナモロールに関連したお土産を探してみたのですけれども、実は店頭には置かれていなく、奥にいた事務をされております方にお声がけをして、そこで初めて、このシナモロールがデザインされたお土産を購入することができたわけですが、ここでもやはり、ぜひ店頭に並べていただくような、もう少し、何か。","respondent":"篠田文化観光課長","answer":"私どもも、できるだけそういった形で取組を進めていきたいと思いつつも、観光協会、場所が非常に狭いものですから、なかなか並べて展示するスペースがないというところがあります。その辺は今後工夫をしながら、訴求力の強い形での販売方法を考えてまいりたいと考えています。","id":"exchange-065"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ展開いただければと思います。ただ、やはり一方で、観光大使ですので、時には大々的に宣伝として活用していただきたいと考えていますが、例えば区内で来場者が１万人を超えるイベントに、これまでも活用してきた経緯もあるかと思いますけれども、そういった大きなイベントでの活用も含めて検討をお願いしたいと思いますが、お考えを教えてください。","respondent":"篠田文化観光課長","answer":"実際に、先ほども申し上げたとおり、非常にシナモロールは人気が高くて、イベント等の売上げにも非常に絶大な効果があることから、私どもをはじめとして、各所管において実施するイベント等でも活用できるように、それぞれの部署において予算化をしていますので。","id":"exchange-066"},{"speaker":"こしば委員","kind":"質問","question":"続きまして、この２１世紀に誕生しましたシナモロールとは違いまして、坂本龍馬をモデルにしたハタチの龍馬についてお聞きします。こういった砲台の移動も含めて、また龍馬像、そしてハタチの龍馬、これをぜひコラボして、既にＹｏｕＴｕｂｅ等でもやっていると思いますけれども、さらなる宣伝の展開をお願いしたいと思いますが、お考えがありましたら教えてください。","respondent":"篠田文化観光課長","answer":"今の砲台の話でも、現地のほうでは新しい観光案内の看板等も作成していたりしますので、そういった点と連動させながら、観光への効果の高い展開をしてまいりたいと考えています。","id":"exchange-067"},{"speaker":"中塚委員","kind":"提案","question":"１８５ページのいじめ防止対策推進事業について、今定例会に提案されておりますいじめ防止条例の一部改正について、総務委員会に続いて質疑をしたいと思います。私はいじめられている子どもがどのような心境かと、総務委員会で指摘をしました。ちくるなと脅されている本人に、条例で相談を義務づけると、子どもがどのような思いをするのか、なぜ子どものつらい気持ちが分からないのか、伺いたいと思います。","respondent":"勝亦総務課長","answer":"そういった中で、いじめを受けた場合には、保護者、区立学校等、区または関係機関等に相談するように努めるものとするというように、これはいじめを受けた本人も、いじめに気づいた周囲も傍観することなく、いじめを放置することなく、早期発見。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、本人に義務づけをすると、子どもがどのような思いをするのか、子どもがつらいという気持ちが分かりますかと伺いました。","respondent":"勝亦総務課長","answer":"そういった中では、今委員がおっしゃったように、それを訴えることがつらいと感じる方、もしくは、いただいたお声の中では、学校にお伝えしにくいものが、区長部局、今回相談窓口があって訴えるところがあってよかった、そのようなお声もいただいているところです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"いじめられている子どもは、そのような自分がみじめで、恥ずかしくて、格好悪くて、誰にも相談できないと孤立しているのです。親には心配かけたくないと言えずに、どんどん孤立するのです。いじめがひどければひどいほど、誰にも知られたくないと思うのです。相談は子どもの義務です。この条例の規定がどれだけ子どもを傷つけるか、なぜこうした子どものつらい気持ちが分からないのか、改めて伺います。","respondent":"勝亦総務課長","answer":"相談できる環境を整える、そういった意味でも、今回区長部局のほうで窓口を設置いたしまして、ホームページや電話、はがき等でご相談ができるように、広く相談のできる機会を設けているものです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"提案","question":"なぜそこが悪いのか、なぜいじめられている人に義務を課すのか、私には分かりません。いじめられている本人を追い込むような条例改正は行うべきではないと思います。提案者は森澤区長です。総務委員会は賛成多数で通過いたしましたが、子どもを追い詰めるようなことが、森澤区長のやりたいことなのでしょうか。違うのであれば、今からでも条例を一旦取り下げてほしいと思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"努めるものとするという表現につきましては、もちろん努力、努めていただくということで、この条例改正の趣旨、そういったものの周知啓発を徹底していくという意味での、努めるものとするというようにお考えいただければと思います。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"努めるものと本人にいじめの報告、相談を義務づけている、これが子どもをよりつらい立場に追い込むと私は思います。子どもから積極的に相談してほしいと思うのであれば、まずは信頼できる大人や学校であるよう私たちこそ努力すべきことであり、いじめられている本人に相談を義務づけることでは決してありません。改めて、条例は一旦取り下げるべきだと思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"決してそれを言わなかったあなたが悪いというスタンスに立っての条例改正ではございません。いじめを受けたら、迷わず身近な人に相談をしてくださいという条例、そういった社会全体でいじめに取り組んでいくのだという、この趣旨を周知徹底していく考え方です。","id":"exchange-072"},{"speaker":"中塚委員","kind":"意見","question":"相談しなかったあなたが悪いというわけではないとおっしゃいますが、条例上は、相談することに努めると書いてあり、これが努力義務だと総務課長も何度も認めております。いじめられている本人が悪いのではないのです。相談できないほどつらい立場に置かれている、その事実に私たちはどう向き合うのかが問われているのだと思います。子どもを責め立てるような条例は間違っていると、改めて述べたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、１８９ページ、ジェンダー平等推進事業について、また２１５ページ、戸籍法改正対応経費についてご質問いたします。最初に重要なことは、相談をしたときにＬＧＢＴＱ当事者の気持ちが分かる人が対応することが重要であると考えますが、その点について区はどのようにお考えなのか、また、本区のＬＧＢＴＱ専門相談、このにじいろ相談というものはどのような内容を検討しているのかお知らせください。","respondent":"加島人権啓発課長","answer":"それからにじいろ相談の体制ですけれども、こちら、これまで男女共同参画センターのカウンセリング相談のほうで、セクシャリティに関するお悩みを受けるというようにしてきたのですが、こちらにつきまして、これに加え、令和６年７月から月２回の頻度で、当事者。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"は当事者の方々、よく気持ちが分かる方々に対応していただけるということで、まず安心いたしました。この事業についても相談だけではなくて、そこで得た情報、また詳しい方、なるべく頼んでいるということで、その方々にぜひ品川区で行っている交流スペースみんなのひろばや、講座についてのアドバイスもいただけるような取組につなげていただきたいと思うのですが、いかがでしょうか。","respondent":"加島人権啓発課長","answer":"孤独感が強い場合には、今委員からもご案内がございましたように、交流スペースみんなのひろば、または講座であったりですとか、日常生活上に困難を抱えていらっしゃるような場合には、東京都パートナーシップ宣誓制度の活用のご案内など、こういったものを通じて。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私は、先に言わせていただきますが、今回行おうとしている電話相談、または面談というものも、一緒に進めていければいいなという趣旨での質問になりますけれども、ぜひこの専門家による相談のところで、ＬＩＮＥ、またＳＮＳなどでの相談というところも併せてできればいいなと思うのですが、いかがでしょうか。","respondent":"加島人権啓発課長","answer":"来年度予算において、にじいろ相談以外にＳＮＳ相談の開始を新規で予定しております。こちらにつきましては、今の通常のカウンセリング相談と同じく、セクシャリティを含め、幅広い人生のお悩みに対応していくための相談となっております。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問","question":"やはり当事者の方々に聞いていても、専門の方、自分たちの気持ちが分かる人に相談したい、また、電話やＬＩＮＥなど選べるほうがいいというようなお声もいただいております。１点、その点について何かご答弁があればお願いします。","respondent":"加島人権啓発課長","answer":"ご提案ございましたＳＮＳでのにじいろ相談、ＬＧＢＴＱ専門相談というところですけれども、まず来年度開始いたしますにじいろ相談、ＳＮＳ相談の相談内容、実績を見て、必要性を見極めてまいりたいと考えておりますが。","id":"exchange-077"},{"speaker":"ひがし委員","kind":"意見","question":"ぜひ前向きに取り組んでいただければと思います。厳密に言うと、同性婚というところが実現していない現在では家族ではないのかなと思って諦めてしまったということでしたが、その区民の方々から、せっかく品川区でこのような条例ができるのであるから、病院などでもしっかりと周知をしてほしいというようなお話をいただいております。","respondent":"加島人権啓発課長","answer":"区としてというところですけれども、医師会等を通じて、医療機関に改めて条例制定を機に、東京都パートナーシップ宣誓制度の趣旨についても伝えていくほか、事業者につきましても、ＣＳＲ推進協議会や官公署連絡会、関係の団体などがありますので。","id":"exchange-078"},{"speaker":"ひがし委員","kind":"質問","question":"ぜひこの機会に、品川区でも周知を進めていただければなと思います。次に、戸籍法改正対応経費についてお伺いします。それは、キラキラネームなどの判読も容易になるというような、またデジタル化の促進が狙いというように書いてありましたが、今回品川区では、１,５００万円余が予算化されていますけれども、この経費、どのように使われるのか、まずはお聞かせください。","respondent":"吉野戸籍住民課長","answer":"来年度の予算ですけれども、今委員がお話しされていた、本籍の方へ振り仮名を確認するための通知を発送するものになります。","id":"exchange-079"},{"speaker":"ひがし委員","kind":"質問","question":"一応国の想定では、個人ではなくて一緒に住んでいるところにはまとめて送られるというように、今のご答弁は把握したのですけれども、例えば個人で送ってほしいというような意見を聞いたときに、例えばですが、ＤＶなどで支援が必要な方であったり、あらゆる理由でそこの住所ではなくて個人宛てに送ってほしいなどというとき、例を出してみると、先ほど言ったキラキラネーム。","respondent":"吉野戸籍住民課長","answer":"ただ、今お伝えしたものは品川区民の方のみになってしまいますので、それ以外の方、本籍人の中には区外の方もいらっしゃいますので、そういった方たちに、また、今の配慮が必要な方たちなども含めてですけれども、事前にやはり周知、こういった通知を送りますということで。","id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問","question":"個別の対応も検討いただけるということで、ぜひこの周知というところを早い時期にしていただくべきかなと思います。なかなかこう、ホームページなどがいつも言われるのですが、なかなか見ないかなと。これからはニュース等でも、この戸籍法改正についての話はあると思うのですが、品川区としても早い段階から周知というところを進めていただければと思いますが、いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"そうですね。やはり見ていただかなければ何もなりませんので、早めの周知をしたいと考えています。これに関しまして、ＤＶの支援措置に関しましてはとても注意を払って、細心の注意を払って対応しなければいけないと考えていますので、丁寧な対応を心がけたいと思います。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"意見","question":"ほかの方の配慮もしてくださると思ってはいるのですけれども、ＤＶだけではなくて、お名前を変えたという方、先ほど言っていたトランスジェンダーの方々も変えた人がいて、家族に届いてしまうとというところで考えると、幅広い方々にきちんと分かるような対応を取っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"よろしくお願いします。予算書には表記がないのですが、しながわ見守りホットラインの話です。ここについて現状の、しながわ見守りホットラインとしての予算上の表記はないのですが、電話番号、これは０３からなので、区の電話関係かなというところで、庁舎管理費に関連して伺いたいと思いますが、この辺の検討状況を教えてください。","respondent":"加島人権啓発課長","answer":"見守りホットライン、こちらのダイヤルについてですけれども、委員からもご案内ございましたとおり、４本あります。こちらにつきましては、令和６年１０月の区立児童相談所の開設に合わせまして、フリーダイヤル化していく予定です。","id":"exchange-083"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしても今日は、ＤＶについては総務費が所管でありますけれども、それぞれの施策について、その他関連して伺いたいことは別の款で伺いますが、とにかく勇気を持って通報してくれたその方が、またその当事者をしっかりと守れる迅速な体制、その窓口といいましょうか、最初の入り口かと思いますので、本当に６年かかりましたけれども。","respondent":"勝亦総務課長","answer":"今おっしゃった未来アクションフェスに関しましては、ちょっと直接の関わりがなく、平和首長会議のほうとのやり取りの中では、未来アクションフェスについてはお話を伺っていないところです。","id":"exchange-084"},{"speaker":"つる委員","kind":"提案","question":"ですから、２４日の開催の内容ですとか、そういったことを、区としても平和首長会議を通じて、このような内容だったというようなことも情報提供をいただきながら、品川区の非核平和事業について必要であること、参考となることがあれば、ぜひそこから参考としていただいて、品川区の平和施策につなげていただきたい、このように思います。平和に関しては、前回、２年前ですか、予算特別委員会で求めました。","respondent":"河合生活安全担当課長","answer":"やはり区民からの要望や治安情勢から含めて、単年ということではなく、効果を見定めて継続的にできればとは考えております。","id":"exchange-085"},{"speaker":"つる委員","kind":"質問・要望","question":"そして犯罪のない、子どもたちが守られる品川区をぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、１８９ページのＤＶと、２０９ページのしながわシティラン、行ければ１８５ページのいじめ防止対策でお願いします。その際に、加害者の更生というか、改善プログラムを実施してはどうかというお話をしました。体制確保や予算面で課題があるということでお話は終わったのですけれども、来年度の予定としてはいかがでしょうか。お答えください。","respondent":"加島人権啓発課長","answer":"加害者の更生に向けまして、ある程度伴走して継続的な支援を行っていく必要があるかと考えますが、現状、被害者支援を中心として担ってまいりました区のほうには、加害者支援のための知識、ノウハウというものが蓄積されてございません。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。７人に１人は何度も暴力を受けているという調査があります。今はそういった加害者更生の知識があまりないということですけれども、例えば多くのところでそういった加害者更生プログラムを行っているような団体が存在するとは思うのですが、そういったところが見つかれば、このような加害者関係の更生プログラムを実施していただけるというようなことでよろしいでしょうか。","respondent":"加島人権啓発課長","answer":"令和６年１０月に区立児童相談所が開設されまして、そういったところを中心に、子どもの親という視点から、委員ご指摘の加害者へのアプローチなどの働きかけも可能となると考えますので、配偶者暴力相談支援センターとしましては。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私自身もそういった団体の研修を受けていて、そのようなところでも、延べ人数３,６００人ほど加害者のプログラムを行ったりなどしている実績があるところもありますので、去年の決算特別委員会で重要性は認識しているというようにご答弁いただいたので、そちらの体制確保、予算面で課題があるというようにもおっしゃられていたので、ぜひそういったところ、数々ありますので。","respondent":"加島人権啓発課長","answer":"加害者支援の重要性につきましては、確かに認識しております。ただ、現在の体制上難しいということ、課題についても申し上げました。ただ、委員からご案内がありました東京都の実施体制などにつきまして、こちらは所管のほうで調査研究してまいりたいと思います。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ前向きにお願いします。では、次に行きます。しながわシティランです。前提としてですけれども、大々的なシティプロモーションといいますか、スポーツイベントとして、ランニングというか、ジョギングを選んだ理由というものをぜひお聞かせいただきたいのですが、いかがでしょうか。","respondent":"三井スポーツ推進課長","answer":"今回のしながわシティランですが、基本的に今まで区民スポーツ大会の区民マラソンとしてやっておりまして、そちらをリニューアルして、大々的に品川区全体で盛り上げていけないかというようなことと、それでシビックプライドの醸成ができないかということで、しながわシティラン。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今のコースの中でどれだけ特別感を出せるかということで、例えばしながわ宿場まつりのように、おいらんとか、江戸まちのコスプレをした人が応援してくれるとか、ゴール地点にサンリオのキャラクターが一斉にそろって、みんなでお出迎えしてくれるとか、あともしくは、それこそ品川にゆかりのあるような著名人が一緒にランナーとして参加してくれるとか、そういったような。","respondent":"三井スポーツ推進課長","answer":"今回いろいろ交通規制の関係もありまして、このようなコースになっておりますが、ここでも旧東海道や天王洲付近、また緑道、京浜運河沿いということで、あとは先ほどもお話ししたレガシー、大井ホッケー競技場の中も走るということで。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"意見","question":"その宿場町の、おいらんの流れでいくと、それこそ、この前えのした委員が区長にランナーで参加してほしいとおっしゃっていましたけれども、参加は無理かもしれないですが、それこそ町娘として参加して手を振るというような、そのようなものもいいと思います。ぜひご検討をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"西村委員","kind":"提案","question":"１８７ページ、都市ブランディング推進経費、１８９ページ、ＳＮＳ情報収集分析経費、ジェンダー平等推進事業、時間が許せば１８７ページ、ＬＩＮＥ公式アカウント運用と進めてまいります。「わ！我が会派からも新しいものをと提案し、終了予定と伺ってまいりましたが、月曜日、ＳＮＳに流れてきて、正直驚きました。終了に至る経緯と、また、事項別説明資料にロゴマークの策定として３８５万円とあります。","respondent":"辻広報広聴課長","answer":"これから来年度に入りまして、区民とともにワークショップ等を行いまして、新たなロゴですとか、マークをつくるですとか、そういったことを進めていくというような計画になっています。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"子どもの給食時にも子どもたちにも親しまれまして、ＳＮＳにも惜しまれる声がありますが、新しい品川をつくっていくということで、都市ブランディング、ぜひとも力を入れていただきたいと思っているのですけれども、この今のタイミングですと、チラシやパンフレットにマークを入れて印刷してしまっているという企業や団体がありましたら、丁寧にご対応と配慮をお願いしたいなと思っていますので。","respondent":"辻広報広聴課長","answer":"やはり対象が誰なのかですとか、目的ですとか、そういったことに合わせてＸを使う、ＬＩＮＥを使う、Ｉｎｓｔａｇｒａｍを使う、ホームページに出すだとか、もちろんそれだけではなくて広報紙を使うということで、様々な点を勘案しながら。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"本当に我々からも周知ということはよく申し上げるのですが、本当に難しい時代になっていると思います。そのような意味においても、戦略的な広報、これからますます期待をしたいと考えています。例えば、昨年の南大井の解体工事現場について、大分早い段階で、まず松本議員が気づかれまして、せりざわ議員が即座に問合せをしたら、区役所は事態の認識をして既に動いておられたというように伺っております。","respondent":"辻広報広聴課長","answer":"ただ、自分たちでやっていくだけでは限度があるといいますか、このＸのビッグデータの中からどのようにしてそういったものを、今起きていることを即座にキャッチするかということはやはり素人であって、プロの方に頼んだほうがいいということで。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"次に都市ブランディングですけれども、どのような品川の未来をつくっていくのか伺ってまいりたいと思います。２０１８年になりますが、いろいろなキャッチフレーズが品川区を強烈にアピールするとして展開された取組があると思います。」とか、「東京に疲れました。品川ブランドの可視化に向けて、目的、ゴールは何なのか、品川区はブランディングすることで、何が起こったら成功と考えるのか伺います。","respondent":"辻広報広聴課長","answer":"今年度、既に区民向け、それから職員向けにアンケートを実施したり、あとは区内で活躍する方々に直接ヒアリング等を行っております。その中で、今の魅力というものは、利便性がよいだとか、商店街があるとか、歴史があるとかですけれども、そういった意見は出てまいりました。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。最後に、ジェンダー平等推進事業に関してですが、条例制定に伴うトイレの考え方について伺います。区有施設、公衆トイレ、学校など、様々、トイレを所管する課がありますので、組織横断的に考えていくと人権啓発課が中心になると思いますが、その辺りはどのようにお考えか、現状の庁内の取組と併せて伺います。","respondent":"加島人権啓発課長","answer":"事例を共有いたしましたが、民間のとおり、こういった公共施設のトイレを整備していくという趣旨ではなく、区有施設につきましては、様々な方がお使いになる施設ですので、それぞれの施設の用途、目的に応じて考えていくことが重要だというように、認識を共通にしたところです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひとも人権啓発課がリーダーシップを取っていただきながら進めていただきたいと思うのですが、この不特定多数の方が使う施設や、今後の区有施設におけるお手洗いをどのように考えるか、方向性を伺いたいと思います。男女共用トイレをつくる予定のある施設はあるのか、上位計画はあるのか、伺います。","respondent":"小林施設整備課長","answer":"区としましては一律に整備をしていくという考え方ではございませんが、その施設の利用に応じて、様々検討を深めていきたいと考えているところです。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"実際に視察に行かせていただいた品川歴史館には、男性トイレにもおむつ替えスペースがありまして、それは区民の方々からも求められてきたことですので、ぜひ進めていただきたいと思います。設置自体の是非というよりは、設置の趣旨確認や、当事者のニーズを事前に聞いているかどうか、場所の妥当性をどう考えていくのか、その辺りが重要であろうと思いますが、お考えをお聞かせください。","respondent":"小林施設整備課長","answer":"施設を利用される方々の状況に応じてトイレの検討が必要かと思いますので、様々な事例を収集していきながら、よりよいトイレづくりに活かしていきたいと考えているところです。","id":"exchange-099"},{"speaker":"西村委員","kind":"意見","question":"今、このトイレの問題は議論の過渡期でもあると思っておりまして、一方でジェンダーは人権問題でもありますので、その調整の過程に知恵が必要だと思っています。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１９３ページの庁舎跡地等活用検討委託について質問します。５,３２４万円がここに計上されていますけれども、事項別明細書には、計画策定費として４,１００万円が計上されています。現在、庁舎跡地等活用検討委員会が行われていますが、検討委員会と計画策定との関わりを伺います。土地評価のところは、しながわ中央公園も含めて行うのかどうか伺います。","respondent":"泉広町事業調整担当課長","answer":"土地の評価の範囲ですけれども、こちらは、今行ってあります検討委員会の中で把握している区民ニーズを踏まえながら、範囲は定めてまいりたいということで考えてありますが、この９２４万円の根拠といたしましては、公園を除く現庁舎跡地。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"この土地鑑定評価のところでは公園は除くということで、そうすると、しながわ中央公園はこの民間活用の対象にはなってこないのか。民間に貸し出すということにはならないということでいいのか、確認させていただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"この対象範囲につきましては、現在庁舎跡地等活用検討委員会で区民ニーズの把握をしていますけれども、そちらの区民ニーズ、また、民間事業者の行ってあります対話型市場調査、そういったところの結果を踏まえながら、範囲を定めるということで考えてあります。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"検討委員会を含めてということですけれども、でも土地鑑定評価は今のところ公園は含まれていないということですので、ぜひ、この間も言ってきておりますが、このしながわ中央公園を残していただきたい、なくさないようにしていただきたいと思います。改めて伺いたいと思います。それに対して、区は、ここで施設を絞り込んでいくことは考えていないと。区民参加の点で、検討委員会の目的を伺います。","respondent":"泉広町事業調整担当課長","answer":"１点目、しながわ中央公園の取扱いですけれども、こちらは区民ニーズを今把握していますので、区民ニーズのかなえられるまちというところの最適なところを目指して、引き続き検討を進めてまいりたいと思います。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"結局のところ、この検討委員会は何をするところなのか、マッチングするということはどのようなことなのか、伺います。","respondent":"泉広町事業調整担当課長","answer":"検討委員会ですけれども、こちらは今も検討委員会の中で様々出たご意見を少しずつ収れんさせながら、活用のテーマ、また、活用に当たって重視する視点、そういったところを取りまとめているところです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"提案","question":"少し先に進めたいと思うのですが、この区民参加で検討していくためには、情報公開が前提です。企業からの提案では、不動産事業者が一番多かったと。ほかにも建設事業者など１６者から応募があったと。居住や商業、業務、高齢者福祉、子育て支援などの施設提案があったとの説明です。具体的な中身は分からないというところで、この具体的な提案内容はどのようなものがあったのか伺います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の結果の公表ですけれども、こちらの民間事業者の提案をそのまま公表いたしますと、提案者の事業計画、事業手法などが流出してしまうということで、参加意欲を低減させるというところがありますので。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"公開はしないということですか。区民が分からないまま、進められていくということになりかねません。この中身はいつ公開するのか、ずっと公開しないのか伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の結果をいつ公表するのかですけれども、こちらは今の段階では、いつ頃その詳細を、民間事業者の提案を公表するかといったところの考えはございませんが、国の手引などによりますと、こういった提案には、その事業者のノウハウ、また。","id":"exchange-106"},{"speaker":"のだて委員","kind":"提案","question":"公開せずに区民参加で検討されると言えるでしょうか。私は言えないのではないかと思います。この提案どおりに進められてしまうのではないかという危惧も抱きます。こうした下でＰＦＩを導入していくとなれば、企業の利益のために公有地が使われてしまうのではないかと思いますが、いかがでしょうか。民間にこの現庁舎跡地を売り渡すこともあるのか、売却すべきではないと思いますが、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"官民連携手法に関するお問合せですけれども、こちらはまず、ＰＦＩを前提として検討を進めているものではございませんで、広く官民連携手法を検討しているものでございまして、こういった行政と民間が連携するというところでは、民間のノウハウ。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民要望をかなえるように使っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"石田（し）委員","kind":"質問","question":"質問に入ります。初めに１８７ページ、先日も少しお話をしましたが、ＬＩＮＥ公式アカウント運用についてお伺いします。これはデジタル人材に限らず、私の一般質問においても、４月に今度策定する人材育成・確保基本方針ですか、この中に様々な職員の行動指針というものも入ってくると思うのですけれども、ここについて１つ、今までも民間企業の皆さん、様々な交流を区行政もされてきたと思います。","respondent":"佐藤経理課長、辻広報広聴課長、崎村人事課長","answer":"私のほうから、契約の相手方に情報漏えいがあった場合の区の対応についてお答えいたします。ですから、今回の情報漏えいには、直接は関係ないという認識です。今情報戦略担当課長も民間から来ていただいておりますように、任期付の職員という形で。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、区役所の中でも、若い人たちがどんどん仕事を辞めて違うところに移ってしまうという、非常に厳しい状況下に置かれている状況の中でも、私はこういったことをやることによって、若い人にもそういったいろいろなチャンスというか、いろいろな働き方というものを示すこともできると思うので、ぜひその辺を区として、ちょっと私もまだ具体的に全部調べているわけではないのであれですが、できることがあれば。","respondent":"崎村人事課長","answer":"やはり行政ニーズが複雑化・多様化する中で、この民間の考え方というものも行政の仕事に取り入れていくということは非常に重要だと考えておりますので、積極的に考えていきたいと考えております。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろんアトレに協力してもらうときがあったりなかったりということで、一減などがあったりするのですけれども、ここはぜひ、区有施設もそうですが、様々、もちろん民間企業の協力を求めていってもらいたいということもありますけれども、この区有施設の在り方、様々今検討していると思うので、そういったときには、そういった期日前投票所をできるよという視点もぜひ取り入れていただきながら。","respondent":"鈴木選挙管理委員会事務局長","answer":"期日前投票所につきましては、ご存じのように１３地域センター、それとアトレに協力いただいておりますが、衆議院選挙の場合に急な選挙があると、どうしても施設の確保が難しいという面があります。","id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１８７ページの区政資料等発行経費、それから１７９ページのしながわＷｉ－Ｆｉスポット事業と、同じくシステム標準化経費、この点について伺っていきたいと思います。","respondent":"辻広報広聴課長","answer":"こちらを参考につくっていただくということと、個別にチラシを作るときにはデザインアドバイスをしたり、全庁的に年に１回はカラーユニバーサルデザインの講習を行っているところです。","id":"exchange-112"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。これについて、来年度、広報広聴課は戦略広報課という形で衣替えというか、名前が変わりますけれども、そういった部分で、この区庁舎全体に対して、そういった指導徹底というのですか、印刷物等の在り方というのですか、こういったことについてより一層の関わりというか、そういったものもお願いしたいなと思うのですが、その点についていかがでしょうか。","respondent":"辻広報広聴課長","answer":"来年度は伝わる広報の方法ということで、全庁的にまた研修を別の形で開くような予定もしておりますので、その中で、各所管のものをもう少しレベルアップといいますか、見直していきたいなと考えています。","id":"exchange-113"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。このシステム標準化経費ということで。この標準化対象のシステムというものは、全庁的に国保とか、介護とか、全ていろいろなところにシステムがありまして、それが標準化の対象となっているので、全体としてシステム標準化の経費、ここの総務費に載っているもの以外にもあるのではないかと思いますけれども、全体としてはどの程度になるのか教えていただきたいと思います。","respondent":"横田情報推進課長","answer":"令和６年度予算のお問合せです。全体で約２５億６,７００万円を計上しております。内訳ですが、イニシャル経費で大体１９億７,２００万円、ランニング経費で５億９,５００万円となっております。","id":"exchange-114"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。かなり大きな金額が、今後必要となってくるということですけれども、まず、こういった標準化は国が主導で進めてきているわけでありますが、これに対して、これを進めることにおいて、区民、また区に対するメリット、これは一体どのようなものがあるのか、今の区としての見解をお知らせください。","respondent":"横田情報推進課長","answer":"２点目ですが、これまでカスタマイズなどにより、システムで処理するデータの持ち方やファイルレイアウトが自治体ごとに異なっておりましたけれども、この辺りも統一化されますので、システム公開時に円滑なデータ移行ができるようになりまして。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"今回、このベンダーロックインの解消というものが進むだろうと言われておりますけれども、そういったところで、役所側とベンダー側の、いわゆる今までのような関係というのですか、かなり職員もベンダーのいろいろな知見とか、ノウハウとか、長年のお付き合いというところでの関係と、この標準化されたことによって、移行後の職員とベンダーとの関係、こういったところにどのような変化が起こってくる、また。","respondent":"横田情報推進課長","answer":"ただ、今回のシステム標準化に関しましては、ＳａａＳ型といいますか、アプリの、いわゆるゲームのようなもので、サービス利用型ということになりますので、システムベンダーとは減額交渉がなかなか難しくなるということが考えられます。","id":"exchange-116"},{"speaker":"塚本委員","kind":"質問・要望","question":"その点を含めて、また区としてコスト削減、こういったことについてどういった点が努力できるのか。品川区として、ガバメントクラウド事業者とその利用料の金額交渉等が、直接はできないと思いますけれども、どういった形でその利用料等を適正化していく手段があるのか、こういったことも含めてお聞かせいただきたいと思います。","respondent":"横田情報推進課長","answer":"ですから減額交渉は基本できないということになるのですが、区ができることといたしましては、サーバーやネットワークの最適化の交渉をシステムベンダーと対等にできるようにスキルアップを図ることや、国にクラウド利用料が割安になるように長期継続契約はできないかなど。","id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"当初、国は３割のコスト減が、このシステム標準化によって各自治体になされるのだというようなこともうたっていたのですが、このランニングコスト、標準化後の件については、なかなか区の裁量が利かなくなってくる部分があるというようなことが、今質疑の中で見えてきたのですが、ぜひここについては、せっかく標準化するので、そこで区が何か。","respondent":"横田情報推進課長","answer":"Ｗｉ－Ｆｉについてのお問合せです。次年度から、１接続当たり６０分の制限をなくしましたＷｉ－Ｆｉにつきまして、室内施設に設置していく予定です。地域センターや文化センター、中小企業センター、ゆうゆうプラザなど、２５室内施設を予定しております。","id":"exchange-118"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひやっていただきたいということで、進めていただきたいのですが、時間が６０分を超えるということは大変に大きな前進で、あと一応通信速度も恐らく、新しくなるので遅くなるということはないと考えていますが、今後とも区民サービス向上のために、ぜひこのＷｉ－Ｆｉの改善、進めていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"１８６ページの戦略広報費全般に関して、関連しまして２１３ページ、ふるさと納税事業、時間があれば２０９ページ、デフスポーツに関連して伺います。情報発信としては、ある意味横並びの情報発信というのでしょうか、それを戦略広報課ということで、今度は情報発信、情報そのものの内容を戦略的に活かしていくという思いの表れとして、このような組織改編があったのかなと受け止めております。","respondent":"辻広報広聴課長","answer":"そのめり張り、誰がつけるかということですが、４月から区長室に移るということで、もちろんトップマネジメントの中の１つとしてやるということが１つ、もう一つは、企画のほうとは部署は変わってしまいますけれども、それはこれまでと同様に。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、そのような視点からのめり張りをつける、決して抑制するわけではないけれども、その正しい情報を伝えることによって、相手からの理解をもらって、それをふるさと納税を回避してというような方向に、今回の戦略広報課としての役割、これは１例だと思いますが、そのような視点からの取組も私はぜひやっていただきたいと思いますが、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"確かに私どもの中には、ふるさと納税で失った税収額というものが、私たちの中では分かっていても、やはり区民の方には届いていないかなという一面はあると思います。そういったところは税務課等と連携しながら、広く伝わるような仕掛けをしていきたいなと思います。","id":"exchange-121"},{"speaker":"田中委員","kind":"意見","question":"すみません。ちょっとまだ言いたいのですが、「わ！しながわ」がなくなります。それで今日来るときに、もう中小企業センターのところも消えているのです。私は、「わ！しながわ」をやめるのであるけれども、もう時間ないのでやめます。すみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-122"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは１８３ページ、新年賀詞交歓会経費、２０５ページ、しながわ観光大使関連事業、時間があれば１８５ページのマウントしながわ活用事業についてお伺いしたいと思います。新年賀詞交歓会経費からお伺いしたいと思います。今年でコロナ明け、食事なしの新方式にして、森澤区長体制の中で２回目の新年賀詞交歓会が行われたと思います。","respondent":"勝亦総務課長","answer":"今年度の課題といたしまして、従来どおりの時間で設定しておりましたが、新しく飲食なしという形で実施させていただきました。その中でお茶は提供させていただきましたが、ゆっくりお話ができる場面、できない場面、それぞれ受け止め方が皆さんあったのかなと考えています。","id":"exchange-123"},{"speaker":"せりざわ委員","kind":"確認","question":"残念ながら今回変わらずに、また、状況の確認があまりできなかったみたいなお話ですが、入り口にいて、私はそんなことあるのかなと思っています。これはぜひ強く、次回以降お気をつけいただければと思います。観光大使のお話をちょっと確認したいと思います。そもそも観光大使のこのシナモロールとよく混同されるシナモンとの違いというのを、品川区としてどう認識されているのか、まず、お聞かせください。","respondent":"篠田文化観光課長","answer":"サンリオのキャラクターは、もちろんあちらが考えてつくられているところでありますが、私どもに関しては、平成２９年から、こちらから観光大使としての役割をお願いしながら、例えば着ているシャツに「しながわ」と入っているなど。","id":"exchange-124"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"シナモロールというのは世界観ですと。なので、そうするとシナモロールという全体が観光大使なのであれば、まず１点は、シナモン以外のキャラクターも品川区で使えるのではないかと思っていますから、それが今、残念ながらシナモンがほとんど、ほとんどというか多分独占状態でやっていると思いますが、それをぜひ活用していただきたいなと思います。最後、ご見解をお聞かせください。","respondent":"篠田文化観光課長","answer":"シナモンの活用につきましては、様々な制約がある中で、きちんと区の発信として十分活用できるよう取り組んでまいります。","id":"exchange-125"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２１１ページのアイルしながわと２０３ページ、観光関係の話をお願いしたいと思っています。例えば８時まで品川駅の周辺のホテルにいらっしゃって、６時、８時で食事をする。バスで８時半に競馬場へ来てもらう。だけれども、期間的にはあと４年ぐらいあるのであれば、来年の４月１日、今だったら再来年度と言うのでしょうか。ぜひそこら辺のところの考え方を教えていただきたい。","respondent":"三井スポーツ推進課長","answer":"委員ご提案の内容につきましては、今後、どのような方策があるのか探ってまいりたいと考えています。","id":"exchange-126"},{"speaker":"石田（秀）委員","kind":"提案","question":"すぐというわけではなくて、１年ぐらいかけていただいても構いません。職員提案をぜひやってほしいということで９件できました。これをモデル化して、その評価をどうするかという話はこれから考えていくというお話もありましたが、総額１,０００万円ぐらいかもしれませんが、これで９事業やっていけるということは非常にいいことだと思いますので、これをどんどん推し進めていただきたいと思っています。","respondent":"久保田企画部長","answer":"今いろいろなご意見をいただきました。職員提案制度を今年始めて、行政評価もやっているといったところです。今年始めた取組ですので、今後の展開については、より効率的・効果的にできるように検討していきたいと考えております。","id":"exchange-127"},{"speaker":"松永委員","kind":"質問・要望","question":"よろしくお願いします。最初に、先ほどもおぎの委員から品川歴史館のリニューアルについて質疑がありましたが、品川歴史館は１９８５年に開館して、今年で３９年になります。こうしたことも踏まえて、今後イベントについても検討されていくということでしたが、その際に近隣町会も含めた合同のイベントをぜひ検討していただきたいと思いますが、再度のご確認でお願いいたします。","respondent":"篠田文化観光課長","answer":"地元からのご要望も大変強くいただいているところではありますので、今後、何らかの形でイベントに取り組めるかどうか、検討してまいりたいと考えております。","id":"exchange-128"},{"speaker":"松永委員","kind":"質問","question":"ぜひ引き続きよろしくお願いいたします。次に、１７９ページの庁舎管理費について伺います。初めに、総合庁舎３階にあります噴水について伺います。いつからか水が出なくなってしまい、節水のため止められているのか故障しているのか分かりませんが、現状についてお知らせください。いつからそのままになってしまったのか、併せて伺います。","respondent":"佐藤経理課長","answer":"３階の噴水の件です。現在、水が出ておりませんが、こちらは２０１１年の東日本大震災の際に噴水のところで水漏れがあったということで、一旦停止いたしました。その後、国全体として節電・節水の必要があったということもありまして、以降使っていないという状況です。","id":"exchange-129"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ水辺のまち品川をアピールするためにも復活させていただきたいと思います。これは要望で終わらせていただきます。次に、１９７ページの町会・自治会新規事業定着化補助金についてです。そこで初めに、加入しやすくするため、町会・自治会へ新規事業を行う際の補助金を出していると思いますが、この事業を定着させるという制度を制定されたと思いますが、ここ３年間の実績についてお知らせください。","respondent":"宮澤地域活動課長","answer":"新規事業定着化補助金の実績です。令和５年１月末で４４件の申請がございました。令和４年は２４件、令和３年は７件です。","id":"exchange-130"},{"speaker":"松永委員","kind":"確認","question":"来年度予算を確認させていただきましたが、１年目から３年目までのところでは、３５町会掛ける１０万円。４年目から５年目までのところでは、３０町会掛ける８万円となっております。しかし、今年度は両方とも２万円高く計上されていたのですが、来年度予算を見ますと２万円低くなっております。こちらも、できましたら実績等も含めて、２万円減額された理由をお知らせください。","respondent":"宮澤地域活動課長","answer":"来年度は通常どおりの上限額１０万円になります。児童参加地域事業補助金の実績ですが、令和５年度、今年度につきましては、１月末現在で１４７件の申請、令和４年度は４７件、令和３年度は１３件です。","id":"exchange-131"},{"speaker":"松永委員","kind":"提案","question":"住民の方から理解が得られないと。そこで提案ですが、標準的な表示が難しいのであれば、個々の町会・自治会のホームページに町会や自治会費の金額を載せるなどして、住民の方に分かりやすくすればいいのではないかと思いますが、いかがでしょうか。なぜ品川区だけこんなに掲載されているのか分かりませんが、そのことも踏まえて、今後どういった対応をされるのか、教えてください。","respondent":"宮澤地域活動課長","answer":"そういったところ、ホームページに金額を載せるなど透明性のある形にするというのは良い手法かと思います。そういったところ、町会・自治会、地域センターを含めて支援しておりますので、情報共有できるようなことがあればしていきたいと考えております。","id":"exchange-132"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひご検討いただければと思います。近年ＤＸ化が進んでおり、ほかの自治体ではＰａｙＰａｙやＬＩＮＥＰａｙ、クレジットカードなどを活用して集金している町会があるようです。ぜひこうしたことも踏まえて、品川区でも行っていただければと思います。そこで補助です。そうしたところにもぜひ補助金を出していただきたい。もし活用できるのであれば、その内容を教えていただきたいのですが、改めて伺います。","respondent":"宮澤地域活動課長","answer":"今年度、町会・自治会の課題解決ということで、コンサルを活用した支援もしております。その中で、町会もやはりそういう活用ができないかというところで、コンサルを含めて検討しているというところは伺っております。","id":"exchange-133"},{"speaker":"松永委員","kind":"質問・要望","question":"こうしたところについての補助というものもできるのでしょうか。併せて伺います。そうしたところで、鉄道について伺いたいと思います。こうした鉄道や景色を撮っている方からも人気スポットとなっており、ぜひＪＲに要望していただきたいのですが、ちょっと小さい形でもいいのですが、例えば羽田空港のような展望デッキというようなところをつくっていただけないかなと思います。最後に伺います。","respondent":"宮澤地域活動課長、篠田文化観光課長","answer":"ＩＣＴ活用促進補助金というのがありますが、こちらは機器の購入等の補助金になりますので、ランニング経費に関しては対象外となっておりますが、町会・自治会には毎年、環境整備等助成金という形で補助金をお渡ししているので。ご指摘の点につきましては、なかなか区だけでできるものではございませんので、関係部署と連携しながら、可能性やどういった取組ができるのかということについては、今後研究したいと考えております。","id":"exchange-134"},{"speaker":"西本委員","kind":"提案","question":"都市ブランディング推進経費と職員提案制度採択事業についてお聞きします。都市ブランディングです。この前身なのでしょうか。「わ！しながわ」の評価はどうだったでしょうかということで、９割の方が住み続けたいと言っているので、評価があったというのですが、本当ですか。しながわ」をやられて、今回やめられるわけですから、その評価というのをどういうふうに考えられているかということが１つです。","respondent":"辻広報広聴課長","answer":"今まであるものに関しては、ＳＤＧｓの観点からも、それは使っても構わないという認識です。ですから、４月から、今ある区のそういったものも全て新しくするということではございません。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"これは周知が大変だと思います。いろいろなところで使われているので、その周知方法をどうされるのかなと。そして都市ブランディングです。進め方もいろいろあると思いますが、これに対して、区の職員の方々は、どういうイメージを持っているのでしょうか。都市ブランディングというのは、いろいろな都市でやられていますが、どういうイメージを持っていますか。お聞きしたいと思います。","respondent":"辻広報広聴課長","answer":"今現実としてある品川の価値だけでなく、これからのものを、価値を創造していこうと考えております。職員にも既に都市ブランディングに関する研修も行っておりまして、一定の理解を得たと認識しております。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"都市ブランディングですが、まず、やはりトップが、区長がどういうふうに品川区を捉えているかということに限るのではないですか。でも、区長として、トップリーダーとして、どういう品川区にしていく。先ほど２０年先のことを考えてと言っておりました。できれば区長に答えてもらいたいのですが、区長が考える品川区のブランディングとは何ですかということです。いかがでしょう。","respondent":"森澤区長","answer":"来年度、都市ブランディングを進めていくに当たっては、ご指摘いただいたように、やはりリーダーとしてのそういった考え方も必要だと思いますので、様々今調査もしております。そういった意見も参考にしながら、区民の皆さんとともに考えていきたいと考えています。","id":"exchange-137"},{"speaker":"西本委員","kind":"提案","question":"イメージ。どういうイメージでこの品川をつくっていきます、つくっていきたいのですという強い思いがなかったら、ついていかないと思うのです。だから、それは一緒につくり上げていただきたいなと思っています。ウェルビーイング。では、それをするために品川区は何をするのですかということが大切なのです。そして、職員提案制度についてですが、担当がなぜ秘書担当なのでしょうか。お願いします。","respondent":"岡秘書担当課長","answer":"今回、職員提案制度の目的としまして、区長が区民目線で職務に当たっている職員の意見を聞くということや、区長の前で職員の考えている提案をプレゼンするというところもありまして、秘書担当が担当しております。","id":"exchange-138"},{"speaker":"西本委員","kind":"質問","question":"これ、内容はいいと思っていますよ、内容については。なぜならば、本来は、その部署、所管が若手の人たちの意見を吸い上げるという形で積み上げていかなければいけないわけです。お金つけます。プレゼンしてください。そうしたら、部課長はどう思いますか。トップダウンで下ろされてきて、では、責任の所在はどこにあるのでしょうか。全部、区長が責任を取ってくれるということですか。いかがですか。","respondent":"岡秘書担当課長","answer":"課や部をまたいで提案があったことにより、所管する課や部では気づかなかったこと、新しい視点といったところで、新たな事業を考えることができると考えております。区としましても必要な事業だと考えておりますので、今後も取り組んでまいりたいと考えています。","id":"exchange-139"},{"speaker":"西本委員","kind":"質問","question":"ですから、若手の方々の意見をもらうのは当然いいと思います。ただ、それをトップダウンで下ろすのがおかしくないですかということです。部と所管があります。なぜ上からぼんと落とすのですか。組織というのであれば、しっかりその組織の中で若手の人たちが意見を言いやすいように、いろいろな企画ができるようにしていくというのが組織としてあるべき姿ではないのかなと思いますが、いかがでしょうか。","respondent":"堀越総務部長","answer":"従来からのいろいろな予算の提案といったことへの波及効果等も考えられると思いますので、しっかりと若手の職員や所管外の職員のアイデアも入れながら、様々事業展開をしていくという考えで行ってありますので、これは今、委員がおっしゃっていることと。","id":"exchange-140"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ見直しを図っていただきたいと強く申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"若林委員","kind":"確認","question":"それからこの補助金２００万円の使い道を確認します。ポイ捨て吸い殻本数をカウントする際に、まさに今数えた落ちている吸い殻の扱いをどうするのかも確認します。これまでの様々な課長等との議論の中で、場所の確認や声がけをしているというふうに日常的な活動の様子を伺っていますが、誰がそういう場所の確認や声がけを行っているのかというご様子をお聞きして、今年度２０２３年度ですかね。","respondent":"勝亦総務課長、河合生活安全担当課長","answer":"そういった中で、品川区内の薬剤師会にご協力いただきまして、避暑シェルターを拡大できないかとご相談いたしまして、連携しながら実施していく予定となっています。実績につきましては、本年度１件、ゆうぽうとのところにできる喫煙所につきましては、新規設置の助成をできる予定となっております。","id":"exchange-142"},{"speaker":"若林委員","kind":"質問・要望","question":"実態調査については、もう２０２２年度に１回やって、既に先ほどの５地区と２０駅の傾向の数字が出ている。ホームページにも出ているわけです。区民アンケートもそうでした。喫煙所を新たに増やすのかなど具体的な目標を持った中で調査をやっていただきたいと強く要望します。最後の助成ですが、民間の１か所がもう既に見えているというご答弁だったのでしょうか。確認させてください。","respondent":"河合生活安全担当課長","answer":"根拠として整理して、検討していきたいと考えております。民間喫煙所の助成につきましては、現在申請を受けまして、今点検中ということで、必要な書類を出していただいているところで、明確に今年度執行できるという形になっております。","id":"exchange-143"},{"speaker":"若林委員","kind":"意見","question":"具体的に、どこ、何地区とか何駅ということがこの場で言えるのであれば、どうぞおっしゃってください。","respondent":"河合生活安全担当課長","answer":"五反田地区のゆうぽうとの１階にできる喫煙所ですが、こちらは調整しながら、申請に向けていろいろ指導して、今回受理するところです。","id":"exchange-144"},{"speaker":"若林委員","kind":"意見","question":"なるほど、そういうことですね。港区のお話もしようと思ったのですが、まさに港区の方式が、私ももっと港区の調査をしたいと思いますが、港区がなぜあれだけの成果を上げているかということが、今の課長のご答弁の中にヒントがあると思いますので、また、来年度しっかりと一緒に前に進めていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-145"},{"speaker":"澤田委員","kind":"質問","question":"２１５ページ、マイナンバーカード普及促進について質問いたします。内訳に、申請補助事業１,０４７万７,０００円とありますが、こちらの事業内容を教えてください。","respondent":"吉野戸籍住民課長","answer":"１つ目は、高齢者等の福祉施設で、福祉施設長が施設入所者に代わってマイナンバーカードの申請と受取を行った場合に補助金を施設側に支給するものです。２つ目が、これまで行ってきました出張申請サポートです。令和６年度の出張申請サポートは３０回を予定しております。","id":"exchange-146"},{"speaker":"澤田委員","kind":"質問","question":"今お話しいただいた新しく補助対象となった高齢者施設への事業を進めていくに当たり、期待や課題、また、以前から行っているマイナンバーカードの出張申請サポートを次年度は３０回行うということですが、今までの実績や成果などを改めて教えてください。お願いします。","respondent":"吉野戸籍住民課長","answer":"出張申請サポートですが、令和５年度はマルチタスク車両を利用して申請補助をしまして、１２回実施しました。５０人の方から申請をいただきました。武蔵小山商店街などへ出張した申請サポートは計４０回実施しまして、１０１人の方から申請していただきました。","id":"exchange-147"},{"speaker":"澤田委員","kind":"提案","question":"他自治体では、選挙の投票入場受付や避難所の入退所受付などにマイナンバーカードを利用していたり、また、実施はまだされておりませんというか、しているところはないかもしれませんが、例えば先日ゆきた委員が提案されていたオアシスルームでの本人確認としての利用は、すまいるスクールでも同じように本人確認として活用できるかと思います。","respondent":"横田情報推進課長","answer":"マイナンバーカードの所有率が、委員ご指摘のとおり７０％を超えてきましたので、今後、区といたしましては、積極的にマイナンバーカードの利活用を進めていく予定でございまして、次年度、幾つか計画しております。１点目がデジタル通知です。","id":"exchange-148"},{"speaker":"澤田委員","kind":"質問・要望","question":"そのような機会に子どもに関連する可能性の高い窓口にポスターを掲示したり、ポップなど目につきやすい形の案内を置くなどして周知することで、子どもの申請のきっかけになるのではないでしょうか。マイナンバーカードの取得率のさらなる向上を目指し、利活用の拡充を進めるとともに、周知を強化していただきたいと思いますが、区としてのお考えをお聞かせください。","respondent":"吉野戸籍住民課長","answer":"あらゆる手段を使いまして、周知を進めたいと思います。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。１７５ページの計画策定経費の行政評価、２１９ページ、選挙費の若年層への啓発事業についてお尋ねします。先に選挙のほうです。品川区も１８歳では４０％ですが、１９歳から低下し、２０代ではもう２０％代前半と、各年代の中で特に低いと。これに対する選挙管理委員会の対応はどのような状況でしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会としましても、若い方の投票率が低いことは大きな課題であると認識しております。有権者の皆さん全体への啓発とは別に、１０代と２０代を対象とした若年層の方への啓発に力を入れております。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々取り組んでいると。明るい選挙推進協議会には、小中学校などで模擬選挙なども行っていただいております。その明るい選挙推進協議会の活動に関係するのですが、昨年１２月、町会の掲示板に若者選挙啓発参加者募集というポスターが貼られていました。これも先ほどの若者啓発の一つなのでしょうか。その活動の目的や、具体的にどのようなことをなさっているか、その様子などをお尋ねします。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘の若い方の選挙啓発参加者募集ですが、これは明るい選挙推進協議会の中に若者選挙啓発部という組織がありまして、その方たちが中心に自主的に取り組んでいただいているもので、区の選挙管理委員会としても支援しているものです。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"意見","question":"なかなか目立たないこの活動ですが、若者ご本人たちが活動していくということで、非常に意味のあることだと思います。そうすると、今お話のあった啓発活動でどのような成果があったのか。そこに選挙管理委員会がどのように関わっているのかということをお尋ねします。","respondent":"鈴木選挙管理委員会事務局長","answer":"令和５年度のSa-１kowの活動としては、参加される若い方の選挙啓発に関する意見交換、それから新有権者の方に選挙のたびに投票立会人をお願いしていますが、その方たちへの意識アンケート、それから区議会議員選挙においては街頭啓発もやっていただく。","id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な選挙啓発が必要だと思いますが、その中の一つで、この若者中心に進めているということです。今すぐに５％、１０％が一気に上がるわけではないですが、地道に活動されることはとても大切だと思います。若者啓発参加者の募集は、引き続いて今後どのような形で進められていくのでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"新年度からは、その２回目の募集で加わっていただいた方も含めまして、これまでやっている啓発に加え、どんな内容が若い方に関心を持っていただけるか、どんな手法が伝わりやすいかという若い方の新しい意見もいただきながら、活動を続けていく予定で考えております。","id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ、今後の活動も積極的に行っていただきたいと思います。これは要望です。では、１７５ページの行政評価です。品川区においては、かつて平成２４年度まで様々な経緯があり、実施していました。今年、令和５年度の評価シートが先日ホームページにもアップされました。令和５年度を振り返って、課題はどのようなところにあるのでしょうか。お願いします。","respondent":"吉岡政策推進担当課長","answer":"今年度行った事務事業評価の課題です。課題は大きく２つあります。１つは職員の負担軽減があります。今回、初めて行った事務事業評価ですので、今後も効果的・効率的に行政評価を行う上では、職員の負担軽減をうまく図りながら実施していくことが必要だと考えております。","id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"職員の負担と成果指標という、その指標についての課題があるということです。そのまとめでは、行政評価を否定しているものではない。もちろん総務省や京都府の研究調査はご存じだとは思いますが、品川区においては、４年度の試行および５年度の本格実施を踏まえて、職員の負担がどの程度のものか、先ほど負担が課題と伺いましたが、もう少し具体的に分かればお願いします。","respondent":"吉岡政策推進担当課長","answer":"今回、全事業の評価を行いましたが、これも全事業が必要かというところも含めまして、引き続き検討を重ねていきたいと考えております。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"検討されるということです。そして、区民の目線からすると、ホームページにアップされた内容が、Ｄ評価を探すには６６５シートから探さなければいけない。それからすごく小さな字なので、それを複数ページに分割するなどの改善も求められると思います。令和５年度は計画策定経費の小事業として行政評価があるので、この行政評価の行政評価を令和６年度は行うことになるのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"令和５年度の事務事業を評価するといった形になりますので、当然ながら行政評価も行政評価の対象になります。区民の皆さんに分かりやすくというところは、まさにそのとおりでございまして、どのように示したらいいかというところは、引き続き検討していきたいと思います。","id":"exchange-156"},{"speaker":"松本委員","kind":"質問・要望","question":"よろしくお願いします。私からは１８５ページ、外国人学校児童生徒等保護者補助金、１９１ページ、職員研修費について伺います。最初に、外国人学校児童生徒等保護者補助金ですが、こちらはおとといですかね。日本の国籍を有しない者というふうに補助の要件の一つのところに挙げられておりますので、これは国籍を一つの要件にしていると理解してよろしいでしょうか。","respondent":"勝亦総務課長","answer":"外国人学校児童生徒等保護者補助金の交付要綱で定めております対象者は、保護者となっています。おっしゃったように、住民基本台帳には記録されているけれども、日本国籍を有しない者という方を対象としております。","id":"exchange-157"},{"speaker":"松本委員","kind":"質問","question":"国籍を要件としているということです。その上で、全ての外国人、外国籍をお持ちの方たちを対象にしているわけではなくて、これはなかなか不思議な規定になっていて、特定の国に先祖を持たれる方という形ではなくて、学校名で指定されています。東京朝鮮学園、東京韓国学園、東京中華学校に授業料を払う方というふうになっているかと思います。この３つがあえて挙げられている趣旨についてお伺いします。","respondent":"勝亦総務課長","answer":"こちらの制度ですが、たしか昭和５５年に支援していただきたいという請願が出たという記録を拝見しております。そういった中で、議会で全会一致でこちらを採択して、制度として立ち上げたという経緯です。","id":"exchange-158"},{"speaker":"松本委員","kind":"質問","question":"私ども議会がご意見を区に対して申し上げることは多々ありますが、議会で全会一致で通ったからといって、全ての政策・施策を受け入れていただけるわけではないと理解しております。今、区議会が請願を受けてという話がありましたが、区として、この補助金というのはどういう趣旨がある、目的があるとお考えか、伺います。","respondent":"勝亦総務課長","answer":"要綱の中で学校の指定をしていますけれど、こういった外国人の学校に在籍する児童・生徒をお持ちの保護者の方に対して、授業料の一部を補助させていただきまして、保護者の方の教育費の負担軽減を図ることを目的としております。","id":"exchange-159"},{"speaker":"松本委員","kind":"質問","question":"外国人の方とおっしゃられたのですが、ただ、特定の学校の名前を指定されているということなので、こうした学校に通われる方で先祖の方たちに一定の属性がある方たちが、これは経済的な支援なので、経済的に苦しんでらっしゃるということを区としては考えて、支援されているということでよろしいでしょうか。","respondent":"勝亦総務課長","answer":"国籍をもって全てという言い方は適切ではないかもしれませんが、これまでの歴史的経過の中で、現状の３つの種類の学校になっていると認識しています。","id":"exchange-160"},{"speaker":"松本委員","kind":"確認","question":"歴史的な経緯というのはいろいろあることと思いますが、確認しておきたいのですが、これは特定の民族学校を支援するという趣旨なのでしょうか。それとも、特定の属性をお持ちの保護者の方たちを支援する制度なのでしょうか。どちらでしょうか。","respondent":"勝亦総務課長","answer":"こちらの制度の対象につきましては、まず、対象の学校を東京朝鮮学園、東京韓国学園それから東京中華学校としています。一方、対象者につきましては、先ほど申し上げましたとおり日本国籍を有しない者という形で、特定の国籍を求めているものではございません。","id":"exchange-161"},{"speaker":"松本委員","kind":"質問","question":"そうなってくると、例えばこちらの学校に通われようとする保護者であれば、戦時中とか関係なく、それこそ数年前に例えば戦争とは全く関係なく来日された方々であったとしても、これらの学校に通われる方に対しては、経済的な支援が行われているという理解でよろしいでしょうか。","respondent":"勝亦総務課長","answer":"先ほどの要件に当てはまる方については支援するということになってあります。","id":"exchange-162"},{"speaker":"松本委員","kind":"質問","question":"そうすると、制度趣旨がよく分からなくなってくるのです。ですが、今お伺いすると、特にそういうこととは関係なく来日された方たちに対して、かつ、この３つの学校設置者について認めていくというのは、これはどのように正当化されるのか不思議なのですが、お伺いいたします。","respondent":"勝亦総務課長","answer":"一定程度こういった補助金をお渡しする中で、昭和５５年に制度を定めさせていただきまして、それまでの歴史的経緯の中からこのような形でやらせていただきまして、そういった中で一定程度のルールは必要かなというところで現在の形を維持しているものです。","id":"exchange-163"},{"speaker":"松本委員","kind":"質問","question":"この３つの学校に絞っている理由というのが、絞る必要があるということですが、もう一つ、それでは歴史的な経緯というのはどういう意味なのか、お伺いいたします。","respondent":"勝亦総務課長","answer":"昭和５５年に東京朝鮮学園に助成金等の交付をしていただきたいというお話をいただきました。歴史的経緯という部分につきましては、今、委員もおっしゃいましたように戦争の部分もあろうかと思いますけれど、そこの解釈については様々あろうかと考えています。","id":"exchange-164"},{"speaker":"松本委員","kind":"質問・要望","question":"ほかの質問がもうできなくなってしまいましたが、今お伺いしたところで、今の時代にあっては、なかなかこの支援の根拠というのは見いだしにくいのではないかと思います。今伺っていても、それが果たして肯定できるのか分からない。それが最終的には、よく分からない抽象的な差別的な言動にもつながる可能性があるので、これは差別の是正を求める側も考えていかないといけないのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"藤原委員","kind":"質問","question":"私は、まず１８９ページ、広報。お風呂の中で聞かれるのです。私よりも高齢の方に。広報広聴課長、例えば施政方針等においても、いっぱい片仮名が出てくるではないですか。分かる方もいると思いますが、その辺についてお伺いしたいのは、結局ウェルビーイングというのは、具体的にどういうことを言っているのか。その説明の中で、反対の意味で、よくマジョリティとマイノリティとかあるではないですか。","respondent":"辻広報広聴課長","answer":"それがウェルビーイングかなと考えています。誰もが生きがいを持って、自分らしく暮らしていけるということがウェルビーイングかなと思っています。その逆ですが、いろいろな説があるかと思いますが、選択することができない状態が、逆の意味かなと思っています。","id":"exchange-166"},{"speaker":"藤原委員","kind":"提案","question":"よく分かりました。そういう意味において、これから私らしい質問をします。１８３ページ、自治功労者等表彰についてお伺いします。なぜかというと、職員の提案は区長に通るのでしょ。では、どうすればいいかなと思ったときに、これから職員提案制度プラス小さい会派提案制度というのもつくっていただきたいと思うのですが、無所属も含めてそういうのをしていただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤企画課長、岡秘書担当課長","answer":"会派と議員の皆様の要望の政策反映ですが、区といたしましては非常に重要なことと考えております。今まで自治功労者等表彰をやっておりまして、今年は職員提案制度をやりました。来年度は組織改正もあるのでどういうふうになるか分かりませんが、職員提案制度は続けてまいりたいと考えています。","id":"exchange-167"},{"speaker":"藤原委員","kind":"提案","question":"新規の職員提案が入ってくると思いますが、しっかり区長、副区長を支えて、明るい区長室にしていただきたいという思いで、今、質問させていただきました。次は、２１９ページの都議会議員選挙、補選について伺いたいと思います。私、これは毎回言っていますが、国会議員、都議会議員、区議会議員というのがいて、国会議員だから上だ、都議会議員だから区議会議員よりも上だということはないですよね。","respondent":"鈴木選挙管理委員会事務局長","answer":"国会議員、都議会議員、区議会議員の違いといいますか、上下というご質問です。それぞれ選挙区なり有権者なりの範囲も違いますし、それぞれに与えられた重い責任を全うしていただいていると考えております。","id":"exchange-168"},{"speaker":"藤原委員","kind":"質問・要望","question":"都議会議員は２倍です。だから、やはりそこを時宜にかなった施策をしていただきたいと思うのです。でも、選挙管理委員がいらっしゃるではないですか。でも、それだけつながりがあるのだから、選挙管理委員はお給料もある程度出ているのだから、一緒に総務省へ行ってもらえばいいではないですか。私は、そこまでやはりしていただきたいと思っているのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"その場での現金やクレジットカードでの決済の場合は、事業者が掛け売りの請求ができないので使えないというのが現状です。それらを含めまして、国への要請・要望についてのご指摘です。","id":"exchange-169"},{"speaker":"藤原委員","kind":"確認","question":"もう一つ上げてください。選挙人名簿が見られるということです。個人情報がこれだけ言われている中で、選挙に出る方は選挙人名簿を見られるのです。違います。ここをどう保障していくか。それと、今やはり重大な話になっている個人情報をどう守っていくか。もう一点、確認だけです。選挙管理委員の報酬を下げますよということは、審議会で話せばできるのですよねということだけ教えてください。","respondent":"鈴木選挙管理委員会事務局長、勝亦総務課長","answer":"選挙人名簿の閲覧についてです。これもご指摘のように、国の制度、法律で定められているものであります。区の裁量で拒んだり、違う方法を取るということができないという制約はあります。選挙管理委員の報酬の関係です。選挙管理委員の報酬につきましては、その職責にふさわしい額を区議会の議決により条例で定めております。","id":"exchange-170"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はあまり勧めておりませんが、来年度から間違いなく役職定年の制度は入れるのですねという確認です。それと、私は今まで職員の給料に対して、同一労働同一賃金ということを言ってきましたが、役職が落ちてしまうのであれば、大体その額になっていくということの確認をさせていただきたい。それと働き方改革で、人材育成担当課長がやられていると思いますが、３６０度人事みたいことをやるではないですか。","respondent":"崎村人事課長、田口人材育成担当課長","answer":"役職定年制度につきましては、定年年齢が今年度から６１歳に引き上がりまして、条例改正を令和４年度に行いましたが、今年度末で６０歳を迎える管理職については、令和６年４月１日に役職定年を迎えるということで。そのようなフィードバックをし合うというオープンな文化を庁内に定着させたいと考えて実施しております。","id":"exchange-171"},{"speaker":"藤原委員","kind":"質問・要望","question":"３６０度ですが、いろいろな役職の人が評価するわけですよね。確認ですが、それで仲が悪くならないですよね。それが心配なのです。役職の方を職員が評価する。それが１点です。それと、人事課長。まだ目安箱というのはやっているのですか。その辺についてはっきり説明していただきたいのと、今日は新庁舎担当の課長が来ていますが、全然質問が来ないではないですか。それについて、どう思いますか。","respondent":"田口人材育成担当課長、崎村人事課長、山下新庁舎整備課長","answer":"今回実施しているものはあくまでもポジティブなフィードバックに限ったところですので、何とかができていないというような指摘についてはしない。昨年の７月から、区長が就任以来、職員の声を聞きますということで区長室のドアもオープンになって、お声を聞くというスタンスで臨まれているところです。今回予算として実施設計の部分を上げておりますので、着実に整備を進めてまいりたいと考えています。","id":"exchange-172"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、１９１ページ、会計年度任用職員の待遇改善を求めて質問したいと思います。保健師の増員を求めて質問したいと思います。その点についても伺います。これはちょっと教えていただきたいのですが、総務省から自治体に対して、総人件費削減とか定員管理計画をつくるようにと求められているのかなと思いますが、品川区として、定員管理計画というのはつくられているのか。","respondent":"崎村人事課長","answer":"１人当たりどのぐらいというのは、なかなか算出は難しいのですが、今回予算書でもお示しさせていただいていますが、手当の関係で５億円ほどを見込んでおります。最後に定員管理計画についてのお尋ねです。区では定員管理計画というのは定めておりません。","id":"exchange-173"},{"speaker":"鈴木委員","kind":"質問・要望","question":"会計年度任用職員が１,３８２人で、そのうち女性の占める割合が８１％ということです。１,３８２人なので、おおよそ３分の１は会計年度任用職員で賄われているという状況になると思いますが、その３分の１の方がどこにどういう形で配置されているのかという、ちょっとイメージがつくように教えていただきたいのですが、自治体の業務の多くがこれで支えられているわけですよね。","respondent":"崎村人事課長","answer":"そういったことで、待遇の改善等は一定図られていると考えております。","id":"exchange-174"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区としては、その点をどう捉えているのかも伺いたいと思います。なぜ品川区は１年ごとに公募するやり方を取るのかということも伺います。働き続けたいと思って応募しても雇用されない方というのはいらっしゃるのか。その点についても伺います。２３区の中でもそういう区はあると伺っています。２３区の中で、定期昇給制度をつくっている区がどれぐらいあるのかについても教えてください。","respondent":"崎村人事課長","answer":"先ほど申し上げましたように、会計年度ごとに職の必要性を精査した上で実施するということ。国からの通知の中では、基本的には公募で実施するのが望ましいというお話をいただいておりますので、区としては、毎年度公募で実施しています。","id":"exchange-175"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だけど、賃金が変わらないわけです。私は、これは改善が必要なのではないかなと思いますが、その点はいかがでしょうか。具体的なところでは、厚生委員会の中で、例えば健康推進部では、４２人が会計年度任用職員で、多くが先ほど言った専門職なのです。福祉部で会計年度任用職員が何人ぐらいいるかというのも、分かったら教えていただきたいと思います。その点も伺いたいと思います。","respondent":"崎村人事課長","answer":"繰り返しになりますが、賃金が変わらないというところに問題意識はあるのかですが、報酬額の設定の考え方については先ほどお話させていただいたところです。福祉部の会計年度任用職員につきましては、８０名ほど配属されております。","id":"exchange-176"},{"speaker":"大倉委員","kind":"質問・要望","question":"お願いします。１９１ページ、人事管理費、１９５ページ、町会ホームページ運営支援等、２０７ページ、歴史館運営費、２１３ページ、ふるさと納税事業、２０９ページ、しながわシティラン、２１６ページ、選挙費、順不同で伺いたいと思います。確認ですが、改めて伺います。経費削減の観点からということではないということだけ確認させてください。ふるさと納税ですが、まず確認です。","respondent":"鈴木選挙管理委員会事務局長、三井スポーツ推進課長、宮澤地域活動課長、篠田文化観光課長、提坂税務課長","answer":"以前、品川区の投票済証は、ただの白い紙に投票所名と日にち、投票所の管理者の公印を押したもの、通常のものを渡していたのですが。ご提案のあった、地域の顔なじみの方が消防団に関わることで、安心感とか円滑に進むのではないかというご提案の中で。町会ホームページの開設支援というのを区が実施しておりまして、それによって２８町会がホームページを開設しております。今回、全体をリニューアルしまして、展示物も一新しておりますので、今後、中身を変えながらという形で。ふるさと納税に関するご質問です。","id":"exchange-177"},{"speaker":"大倉委員","kind":"質問","question":"しながわシティランについて、分かりました。よろしくお願いします。よろしくお願いします。投票済証については分かりました。これは、投票率の向上というところから、効果もあるのかなと思って伺ったのですが、投票済証があるから行くかというとそうでもないけれども、行ったら投票済証があるのでもらってみたいというので、ＳＮＳなどでも大分取り上げられて載っていたという意識があります。","respondent":"田口人材育成担当課長、鈴木選挙管理委員会事務局長、提坂税務課長","answer":"今現在はコロナが５類になったということで、研修につきまして、特に対面ですとかグループワークなど。やはり施設の確保の問題、また、選挙で使う間、本来の目的の利用ができなくなるという課題がありますので。その辺については、しながわ観光協会や諸団体のご協力を得て、これこそ品川のお土産だというのが分かるような返礼品ということで。","id":"exchange-178"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、１８３ページ、全国自治体との連携事業、１８５ページ市町村交流事業、１９９ページ、地域センター等管理運営費について伺います。現在計画されている駅は、品川区を出発いたしまして西へ６駅。この駅のことが公表された後に、飯田市は観光協会を中心に始発駅品川を冠する品川区との交流を進めてきたと思いますが、総務課もしくは文化観光課において、飯田市との交流の状況について教えてください。","respondent":"勝亦総務課長","answer":"リニアつながりで申し上げますと、リニアの停車駅になる予定の自治体が、リニアの山梨の実験場において共同でＰＲするイベントが以前ございまして、そちらに、品川、飯田、その他一緒に出展して、リニアの開通に向けた共同ＰＲをしたところです。","id":"exchange-179"},{"speaker":"あくつ委員","kind":"質問","question":"温厚な気候で暮らしやすく、面積の８割は森林。リニアという新たな大動脈の誕生を控え、経済や防災について、品川とともにという思いがあることも伺っております。数年後には、通勤・通学圏とも言える４０分で結ばれる飯田市との間で、例えば防災や文化、観光等の交流を含む協議を具体的に始める機会を逃してはならないと思いますが、品川区のお考えを伺いたいと思います。","respondent":"勝亦総務課長","answer":"そういった中で、今後、先ほど委員がおっしゃったように、地道な顔の見える関係づくり、地道な交流を続けていく中で、お互いに協力して、どう相乗効果が出せるかということをともに考えながら、交流・連携等を考えていきたいと思います。","id":"exchange-180"},{"speaker":"あくつ委員","kind":"質問・要望","question":"地域センターについて伺います。恐らく建築から４０年以上たっていると。車椅子対応の誰でもトイレというのが１階にしかなくて、２階にも集会室があるものですから、非常に不便をしているというお話もありました。地域センターの戸籍等の証明書発行機能については、コンビニ交付で大分減ってきているというお話も伺っております。建て替えも含めて、ぜひ検討していただきたいと思いますが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"品川第二地域センターは、現在のところは建て替え等の計画等はございませんが、平成１９年にエレベーターの増築や令和３年に外壁工事も行っておりますので、今後の経年状況等も見ながら、他のセンターもそうですが、建て替え等については検討していくところです。","id":"exchange-181"},{"speaker":"あくつ委員","kind":"質問","question":"地元からの強いお声ですので、どうぞよろしくお願いします。時間がないので質問はしませんが、昨年の決算特別委員会でウクライナの方の支援、１８７ページのウクライナ避難民生活支援経費ということで、２年間、もう３年目に入りましたが、そこについて、支援メニューの拡充をお願いしました。そのときにお約束いただきまして、現在、その当時と比べると１人増えて７人の方がいらっしゃるのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-182"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。１７５ページ、ＳＤＧｓ推進経費についてお尋ねしたいと思います。区は、これまでもＳＤＧｓの推進に向けて、いろいろ関連する事業を展開しております。初めにＳＤＧｓ推進事業補助金について、４点お尋ねしたいと思います。事業対象、実施時期、通常の助成事業との違い、類似事業の実施自治体があれば、どういった取組をしているのか教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"実施の時期につきましては、５月から６月に実行委員会を設置させていただきまして、この後ウェルビーイング、ＳＤＧｓに資する地域課題の解決に向けた事業を実施する企業等を募集いたしまして、８月に最初の助成決定ができればというスケジュールで考えております。","id":"exchange-183"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それぞれありがとうございました。理解しました。企業の支援を通じて、地域のこれからの課題解決を推進していくということで私は理解をしております。次に、ＳｕｓＨｉ Ｔｅｃｈ Ｔｏｋｙｏ ２０２４とはどういったものでしょうか。これは都が主催する事業と認識しておりますが、品川区の関わり方について教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"品川区といたしましては、展示スペースでエコルとごしの取組の紹介や、ブース出展におきましては、区内でサステナブルフードを扱っているお店に出ていただいたり、外に開設されるステージで、区内団体にパフォーマンスを披露いただいたりといったところを検討しております。","id":"exchange-184"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明どうもありがとうございました。品川区の取組、ＳＤＧｓを推進する区の資源を広くＰＲする機会と捉えて、この大きな事業をうまく活用していただきたいと思います。次に、ゼロカーボンシティしながわ推進経費についてお伺いいたします。ゼロカーボンシティしながわ推進経費に１,３００万円の予算がついていますが、これはどのようなことをされるのでしょうか。お尋ねしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらの予算につきましては、コンサルへの委託経費ですが、ゼロカーボンの実現に向けた区の特性の分析や、企業へのヒアリングやアンケート、外部環境の偏向を捉えた、実効性の高い独自の政策検討、また、子ども向けワークショップなどを実施する予定です。","id":"exchange-185"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。今、課長からも、子ども向けのワークショップというお話がありました。昨年１０月に国連を支える世界こども未来会議inＳＨＩＮＡＧＡＷＡがありました。来年度も実施されるということですが、住み続けられる未来の品川区について、子どもたちから意見・アイデアをもらう未来志向の事業だと思いますが、実施してみての成果と感想をお知らせいただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"大人も子どもも一緒に未来の品川を考えることの重要性。子どもならではの斬新なアイデアが出てくるということがまさに認知されたこともございまして、次年度におきましても、改良を加えながら実施していきたいと考えています。","id":"exchange-186"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。とてもいい事業だと思いますので、ぜひ来年度もよろしくお願いいたします。このイベントによって、知っていただく工夫などもしながら進めてもらいたいと思います。未来の品川区そして社会を考えていく上で、子どもたちの意見を聞くということは非常に大切だと考えています。これは最後に要望とさせていただいて、質問を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/359306?Template=document&Id=6689#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":132344,"voices":430}},{"id":"r06-20240308-3","meetingId":"r06-c-budget","date":"2024年3月8日","dateIso":"2024-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"本日もよろしくお願いいたします。不登校や非行などの引き金になることも考えられるため、児童の気持ちに寄り添うとともに、保護者のサポートをすることは、不登校や孤立・孤独感の解決、非行を防ぐことへつながるのではないでしょうか。１クール６回となっていますが、昨年までに実施した中での保護者の声や施設側からの反響など、もしお聞きになっていることがありましたら教えてください。","respondent":"松山障害者支援課長","answer":"」あと、「夫に参加してほしいです」というような声があるということです。それから、施設側の反響ですけれども、もともとペアレントトレーニングは応用行動分析の理論を基に子どもの対応を学び、良好な親子関係の維持・改善を目指す保護者向けのプログラムとなっております。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"様々な皆さん受けてよかったというような印象の回答が多かったと思うので、本当に素晴らしいと思います。ちょっと聞きそびれてしまったのですが、申込みのあった人数なども教えていただければと思います。","respondent":"松山障害者支援課長","answer":"申込人数についてですが、今ちょっと手元に詳細な数字がないのですが、定員６人を上回るということで報告を受けており、人気の講座となっております。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"需要がたくさんあったというか申込みがたくさんあったということで、受講できていない方も多くいらっしゃるようですので、ぜひ次年度も継続をしていただきたいなということとともに、もう一講座、例えば１年に１回だけだったと思うのですが、前期・後期と分けて２回に分けたりとか、そういうような方法も検討していただければと思います。","respondent":"松山障害者支援課長","answer":"悩みを多く抱える保護者がいらっしゃるとは聞いております。対象者を含めまして、ご提案の内容につきましては、今実施している事業者、それから講師の方の声を聞きながら、発達障害児の支援の中で充実してまいります。","id":"exchange-003"},{"speaker":"澤田委員","kind":"意見","question":"ペアレントトレーニングのように、こちらも講座を行えるとよいと思うのですが、専門知識を有する心理職の継続したカウンセリングを行うことが効果的とされていますので、まずはこのような治療法があるということを広く知っていただくためにも、専門家による講演会などを開催することがまずは大事かと考えますが、区の見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"委員ご提案の講演会についてです。現在も思春期サポート事業で様々な講演会を行わせていただきますので、講演会の内容につきましてはまた事業所と相談しながら決定していければと考えています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問","question":"発達障害児に限ったことではありませんが、障害のある児童を育てている保護者はそのサポートに注力し、余裕がない状態であることがままあると伺います。きょうだい児が相談しやすい環境、そして相談できる窓口やツールなどが必要であると思いますが、そのような機関は現在ありますでしょうか。それらの必要性について、区としてはどのようにお考えでしょうか、お知らせください。","respondent":"松山障害者支援課長","answer":"きょうだい児の相談や支援についてです。現在日常の支援の中できょうだい児がいるご家庭について、きょうだい児に負担がかからないように、例えば福祉サービスを導入するなど、相談員と連携して対応しております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、２２５ページ高齢者安否確認事業の救急代理通報システム、２３５ページ在宅生活支援事業の救急代理通報システム、福祉タクシー・自動車燃料費助成についてお伺いします。そこで、まず現在の区内の救急代理通報システムの累積申請登録者数の数、例年の申請者数、今後見込んでいる申請者数、また障害者対象要件の拡大の内容について教えていただければと思います。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"令和４年度から比べますと、４０台ほど増えてきているというような状況です。今後につきましては、利用者負担の無償化により拡大を図っていきたい、予算上では約１,５００台の計上をしています。現在の人数と累積者数は一緒ですけれども、令和５年１２月末で６６人の方がご利用されています。今後の見込みについては、３０人増を見込みまして、令和６年度予算で９９人ということで予算を計上させていただいているところです。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"対象要件についても、難病、人工呼吸手当のある方を確認できました。そこで、救急代理通報については東京消防庁が１１９番通報を受け付けるため、東京消防庁が広報も行っていますが、申請窓口は各自治体であり、区民の安心・安全を提供する上では、今回の無償化対象拡大を機に、より一層認知度を上げるための広報をしていくべきと考えますが、区の見解をお聞きしましたいと思います。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"今後ですが、利用者負担の無償化を周知するために、区のホームページのほか、支え愛・ほっとステーション、在宅介護支援センター、それからＳＮＳなども使った周知を考えていきたいと考えています。無償拡大についての広報です。障害の部分につきましても、広報しながわ、ホームページ、障害者福祉のしおり、それから相談事業所を含め、全障害福祉サービス事業所へ周知を行いまして、救急代理通報システムの認知度を高めてまいります。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"救急代理通報システムと特殊詐欺対策の自動録音通話機の併用についてお聞きします。当時の福祉部長からは、今後も両システムの併用により安全・安心な生活を送っていただけますように、新規機種の調達について事業者に働きかけてまいりますと答弁がありましたが、現在の状況、また現在までに併用を希望された方がいたのか、もしいればその方への対応をどうされてきたのか、お聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"区のほうに直接問合せ等はなかったということなのですけれども、事業者のほうに確認したところ数件問合せがあって、そちらにつきましては既に新機種への交換を行ったと聞いてあります。詳しい台数までは確認できていませんが数件あり、既に対応済みということで聞いてあります。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"古いものを使っている場合、新しいものへの対応、取組を確認させていただきました。現在区内で自動通話録音機は６,０００台弱の貸出総数になっています。命を守ること、また財産を守ること、安心・安全の提供ではどちらも大事な取組であるだけに、課をまたぐことではありますが、両システムの併用を希望する方が漏れなく利用できるように改めて要望いたしますが、最後に区の見解をお聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"委員からのご要望につきましては、事業者を通して、併用できるような形のものをつけていただきたいということで要望していきたいと思います。新機種につきましては現在不具合がないと聞いておりますので、新機種の導入につきましても併せて進めていきたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"時間がないので、次に２３３ページの福祉タクシー自動車燃料費助成についてお伺いいたします。今回、次年度当初予算案で、タクシー自動車燃料５００円の……失礼しました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"本日もどうぞよろしくお願いいたします。私からは、２６７ページの子どもの未来応援事業、２５３ページの子育て支援情報発信アプリ運用等、２４７ページのデジタル活用による高齢者社会参加促進事業について伺います。２６７ページの子どもの未来応援事業について伺います。足元、そして令和６年度の取組をお教えください。","respondent":"飛田子育て応援課長","answer":"令和２年度より目標額を５００万円としていたところですが、来年度には目標額を７００万円としまして、また民間企業からの支援も併せて引き続き取り組んでまいりたいと考えております。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"理解をいたしました。先日、ひとり親支援を受けた地域の方からお話を伺ったのですが、食品配送と一緒にいただいたクーポンを使って、武蔵小山パルム商店街にあるお好み焼き屋で、本当に久しぶりに親子２人でゆっくり楽しく外食することができ、子どもも私も感動したと言っていました。このような外食クーポンの拡充を区が後押しし、支援の輪を広げることはいかがでしょうか、区のお考えを伺います。","respondent":"飛田子育て応援課長","answer":"先ほど言われたとおり、６店舗のところで２３４食が提供されたと企業より報告がありました。こちらの取組は利用者からもとても好評だったので、次年度も引き続き協力を願っているところです。さらにこのような支援が広がっていくように取り組んでいきたいと考えております。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"ぜひよろしくお願いいたします。さらに調べてみますと、デジタルでこれを取り組んでいる事例がありました。子どもの「食」応援クーポンという名前で、３７店舗の協力加盟店において、スマホのアプリを使って登録したひとり親世帯にデジタルクーポンを配布するというものです。品川区でもデジタルでの外食クーポンの支援をしてはいかがでしょうか。区のご見解を伺います。","respondent":"飛田子育て応援課長","answer":"デジタルでの外食クーポンについてです。今後様々な手法が考えられると思います。このような先駆的な取組や他区の状況、またそのようなところを注視していきたいと考えております。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"デジタルを活用し、より効果的な子どもの食の支援の検討を要望し、次の質問に移ります。続きまして、２５３ページの子育て支援情報発信アプリについて伺います。子育て支援情報発信アプリは、昨年１０月２０日からリニューアルをしたアプリ「しながわこどもぽけっと」、略して「しなぽけ」の配信を開始していますが、ダウンロード数などの利用状況、利用者の感想についてお教えください。","respondent":"藤村子ども育成課長","answer":"私からは、しなぽけの状況についてお話をしたいと思います。ダウンロード数ですけれども、現在リリースから４か月程度経過した状態ですが、２月末時点で２,５００ダウンロードというところになっております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"理解をいたしました。前回のアプリ「しながわパパママ応援アプリ」に比べて見た目もかわいいですし、プッシュ型配信機能がつくなど、保護者にとって使いやすくなっているという印象です。前回のアプリのダウンロード数はどの程度だったのでしょうか。今回の具体的な目標数値はあるのでしょうか。お教えください。","respondent":"藤村子ども育成課長","answer":"今回のアプリの目標値といたしましては、当面の目標としては前回のこの２万３,０００ダウンロードというのを早期に達成するというところは目指していきたいと考えています。","id":"exchange-015"},{"speaker":"山本委員","kind":"意見","question":"理解をいたしました。アプリの初期設定と関係していると思いますが、子どもと親のデータを分類できないというのは、分析するには少し不都合だと感じました。現時点では就学前の子どもを持つ保護者の利用数が多いということで理解をいたしました。小学生や中高生の子どもたちも対象に加えているので、今後はもう少し利用率を高めたいですね。開始したばかりですが、課題があればお教えください。","respondent":"藤村子ども育成課長","answer":"例えば児童センターのイベントのご案内というのは行っているので、そちらのほうは子ども向けというところではあるのですけれども、それ以外に少し小中高生ですとか。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"おっしゃるとおり、アプリ内のトップページにあるお知らせ欄に掲載されている情報は大人向けとなっており、子ども向けの情報や機能が少ないと感じました。小学生や中・高生のために使いたいと思うコンテンツづくりが大事であると考えます。有効な情報を効果的に提供するためには、関係部署による区役所内での横断的な連携が重要であると考えますが、どのようにされておりますでしょうか。","respondent":"藤村子ども育成課長","answer":"アプリのほうからの情報のつなげ方というところですが、ＵＲＬの掲載というところが今は電話番号のみでできてないところとかがありますので、ＵＲＬですとか、あとラインにそこからダイレクトでアクセスできるですとか。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ、より利用者目線に立って、各々のコンテンツに関して協議をするなど連携を進めていただきたいと思います。使ってみると、もっとこういう情報を載せてほしい、もっと使いやすく変更してほしいといった要望が出てくるように感じます。いかがでしょうか。要望してくれた人に何らかのインセンティブを付与し、対価を設定するのはいかがでしょうか。区のお考えをお聞かせください。","respondent":"藤村子ども育成課長","answer":"インセンティブとしてどういったものができるかというところは、これはまた検討しなければいけないところなのですけれども、まずダウンロード数のみならず、このアプリをダウンロードしただけでなくて、アクティブに活用していただけるユーザーを増やすというのを目標に。","id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"子どもたちのタブレットへのアプリの追加はとてもいいと思います。それぞれ検討を前に進めていただければと思います。続きまして、２４７ページのデジタル活用による高齢者社会参加促進事業の中で、はじめてのスマホ体験教室・スマホよろず相談について伺います。令和５年度の取組内容と令和６年度の計画について、簡単に教えてください。","respondent":"川原高齢者地域支援課長","answer":"スマホよろず相談におきましては実施回数１６０回、延べ７６３名の高齢者の方にご参加をいただきました。令和６年度については、教室の会場を４会場から５会場へ増やし、年間で４０コースの開催を予定しております。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"引き続き稼働率が高いこと、また１会場増やし、また講座の新設を図っていただくなど充実を図っていただくことと理解をいたしました。昨年の決算特別委員会での質問でご説明した内容のとおり、引き続き大幅なペースアップを要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"２８２ページ生活保護費について伺いたいと思います。昨日の新聞等で、生活保護の申請が最多２５万件との報道がありましたが、品川区での申請状況はどうでしょうか。２０２３年に入ってからの申請件数について伺います。経年的な傾向はどうでしょうか。増加しているのか、減ってきたのか伺います。","respondent":"豊嶋生活福祉課長","answer":"数字をご報告いたします。令和元年度の申請数は、これはコロナ前です。申請数４２８世帯。令和２年度、申請数４５７世帯。令和３年度、４５７世帯。令和４年度、４２８世帯。そして今年度ですが、１月までの数字で申請数３９７世帯となっております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"安倍首相に対し、生活保護はあなたの権利だと政府が国会に向けて広報するときだとの質問を受け、安倍首相は、当時の田村議員がおっしゃるように、文化的な生活を送るという権利があるわけですから、ぜひためらわず申請していただきたいと思いますし、我々も様々な手段を活用して国民の皆様に働きかけを行っていきたいと明言しました。ぜひアップしていただけるよう求めますけれども、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"今後、今ちょうどこの生活保護のしおりの改訂の議論を課内で始めているところですので、その辺りの文言は、もう既にその国民の権利です等々という文言は入れたチラシも作っておりますので、こうした文言を入れる方向で今後議論を進めてまいりたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"よろしくお願いします。次なのですが、これまで共産党も何度も取り上げてきました、申請をためらわせる扶養照会の件なのですけれども、先ほど件数をいただいたのですが、今年度扶養照会を行ったのが何件あって、そして援助が得られることになったのは何件だったのか。どの部分を聞き取るのかというのはあるのですが、直近のところで教えていただければと思います。","respondent":"豊嶋生活福祉課長","answer":"大変失礼しました。援助につながった件数は、１２２世帯を照会したうち、金銭的支援が行われた件数が２世帯、それから引取りをしてくださった世帯が２世帯、精神的な援助をしてくださった世帯が５世帯となっております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"とは言ってもかなり行われていますよね。長期入院患者、主たる生計維持者ではない非稼働者、未成年者、おおむね７０歳以上の高齢者。つまり、これは窓口相談の中で、本人との相談の中で著しい関係不良だとみなされれば、扶養照会そのものをやらないというふうに解釈できるわけですが、この事務連絡なのですけれども、実際に窓口でどのように運用されているのでしょうか、伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"この令和３年２月２６日の事務連絡の運用についてのご質問です。この事務連絡は、ケースワーカー、それから相談員を含め、生活福祉課内の職員に広く周知をして徹底しているものですので、このとおりやるように、今も厳しく指導というか話をしています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"このとおりやっていて、かなりの世帯が扶養照会になっているというとちょっと理解できないし、実際やられているということも、鈴木議員のほうからありましたけれども、そうなのです。私は事務連絡をもっと生かして、窓口で相談者には大丈夫ですよと、関係が断絶しているようなところには扶養照会しませんよとしっかり伝えることを徹底していただきたいのですけれども、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"生活保護では、扶養義務者の扶養は保護に優先して行われるものということが生活保護法の第４条にも書かれておりますので、扶養照会を全てゼロにするということではなく、しなくていい方については面接を広く行って丁寧な聞き取りをした上で、行わないということで、今。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。努力した人が報われる社会、貧困の連鎖を断ち切るため、保護を利用しながらの大学進学を原則認めたいと、行政等のこの対応を見直すよう国に求めていただきたいのですが、いかがでしょうかというのが１つです。２つ目は、同時に区としても、横須賀市のように特別な事情がある場合には、独自の支援制度を早急に具体化していただきたいのですけれども、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"世帯人数が減ったことによって減額される分については、奨学金で賄うことも可能ですので、その辺りで、今、お話をして対応しています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"よろしくお願いします。私からは、２２５ページ高齢者安否確認事業、２４７ページ認知症高齢者支援事業に関連して質問します。やはりその体制の充実・工夫ということが行政評価シートにも書かれておりますけれども、やはりこれは民間企業との連携をさらに強化していくということでよろしいのでしょうか。お知らせください。","respondent":"東野福祉計画課長","answer":"見守りの仕組みというものが、先ほど別の委員からもございましたとおり、高齢者の救急代理通報システム、安否確認システムなど、それから企業と連携したネットワークの取組、そういったものと併せもって地域の見守りについては取り組んでまいりたいと考えています。","id":"exchange-027"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。行政評価シートでは、利用世帯が８００件ほど、横ばいになっているのですけれども、今おっしゃられたとおり、救急代理通報システムをやはりどんどん増やしていきたいという理由があって、今回無償化することによって利用者増を図るという、そうしたお考えがあってのことなのかどうか。その点をお知らせください。","respondent":"東野福祉計画課長","answer":"高齢者の見守りにつきましては、区としては拡大をしていきたいと考えているところです。救急代理通報システム利用者の高齢者の方は、まだ８７０件前後というところになりますので、これを拡大することによりまして、見守りを強化していきたい。これが区の考え方です。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"この救急代理通報システムなのですけれど、要件が、対象となる方、６５歳以上のひとり暮らし、または６５歳以上のご家族のみの世帯の方とされておりますけれども、日中夜間だけひとり暮らしまたは６５歳以上の方のみになる世帯も含みますということで、そして対象を拡大していただくのは非常にありがたいのですけれども、この日中夜間だけひとり暮らしになる。","respondent":"東野福祉計画課長","answer":"あくまでも申請時に聞き取りをいたしまして、お困りの状態であるということが確認された場合に適用するというふうにしています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"提案","question":"当然私も自分がそういう状況だったら、きちんと連絡が取れるのかなと不安になるかと思うのですけれども、提案として、区にあらかじめ、もちろんその当事者の同意を得て区に連絡先を事前登録して、区が管理して、万が一のことがあったらいろいろな連絡先に通報していくということが必要かなと考えておりますけれども、この救急代理通報システムの利用申請時に緊急連絡先の記入が必要ということがありますので。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"これがまず１つ、連絡をする手段と捉えております。民生委員のほうにご協力をいただいて、高齢者実態調査というものを３年に一度行っております。私からは、品川くるみ見守りアイテムについてのご質問にお答えしたいと思います。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川くるみ高齢者見守りアイテム、これは私も非常によいと思うのですけれども、パンフレットに要件として外出に不安がある６５歳以上の方と書いてありまして、これは認知症ではなくてもよいというようなことを課長から伺いましたけれども、認知症の方でないといけないのかなと思ってしまうので、その辺りの広報の工夫というのを、ぜひもっと区民に対して分かりやすくよろしくお願いします。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"せらく委員","kind":"確認","question":"２６９ページの認可外保育施設等保育料助成、２７１ページの保育園運営費から幾つか質問します。保育園運営費から、業務支援ツールのコドモンの導入について伺いたいと思います。お便りについては、外出先ですぐにアプリから確認できて助かります。身体測定も紙で保護者に共有されています。園の職員の事務作業、こちらの負担感としては、ＩＣＴ活用により変化や課題がありますでしょうか。お願いします。","respondent":"立木保育課長","answer":"写真等に関しましても、セキュリティの関係で、直接写真を撮った業者がコドモンのほうに、今私どもの使っているシステムの中に取り込むことができないというところがありますので、現行の写真の販売システムをそのまま引き継いでいるようなところです。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"そこで、具体的な質問なのですけれども、前回のお話の中で、プライベートゾーンのお話をトイレやお着替えの場面で伝えるということがあるというふうにおっしゃっていましたが、お着替えでは男女を分けるなどの習慣はあるか伺います。普段のお着替えと、水遊び、水着に着替える時で違いがあれば教えてください。","respondent":"立木保育課長","answer":"夏のプールの時期で水着等に着替えるときにはカーテンを引いたりとか、あと男女分けたりとか、施設の中で工夫をしながらやっているところです。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"認可外保育施設の保育料助成について、利用者支援策の拡充についての内容を事前に伺いました。認証、認可外の助成制度を統合して、第１子は月４万円、第２子以降は月６万７,０００円を、認可保育園の不承諾通知がなくても助成を受けられるということで間違いないでしょうか。そして、先日償還払いという話も出てきましたが、これまでどおり申請して助成を受け取る形になりますでしょうか。","respondent":"石井保育支援課長","answer":"こちらの申請方式に関しては、現在のところ償還払い方式を予定しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"少し私の体験から、例としてお話しします。以前、認証保育所に通っておりまして、月８万円お支払いして、差額のほうを助成していただいていました。この認可外保育所へ通う子ども・ご家庭への支援を充実していただくにあたり、適正な保育所の運営のために、改めて指導検査についてお伺いしたいと思います。認証保育所と認可外保育施設への指導検査の頻度を教えてください。","respondent":"立木保育課長","answer":"指導検査の回数、頻度のほうですけれども、認証保育所、認可外保育施設、東京都のほうが児童福祉法でやっている部分と、あと区のほうが現在、子ども・子育て支援法に基づいてやっている部分がありますが、区のほうで年に１回必ず実施をしています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"安全確認・助言等を行うための巡回支援指導員が保育施設を訪問する巡回支援が、年間３００回ということが行政評価シートに記載されていました。各園年に２回程度回られているというところでしょうか。その際に、指導検査により指摘された部分についての確認もされていますでしょうか。","respondent":"立木保育課長","answer":"検査の後の巡回指導等、検査の合間の巡回指導ですが、改善事項等があった場合には３０日以内に改善を出していただきまして、その辺の確認もしながら巡回の支援ということで助言指導をしているということで、この場でも改めてその検査内容等の共有といいますか。","id":"exchange-036"},{"speaker":"こしば委員","kind":"質問","question":"２４７ページ、デジタル活用による高齢者社会参加促進事業について伺います。その影響、恩恵と表現したほうがいいかもしれませんが、全ての人間に与えられた１日２４時間という限られた時間の中で、いかに合理的にその時間を節約していくのか。その思いで質問いたします。そういう中で、高齢者の方が認知症になるのを防ぐために、行政が高齢者と向き合っていく姿勢、考えについて教えてください。","respondent":"川原高齢者地域支援課長","answer":"デジタルディバイドの方への対応ということでは、スマホ教室の場所を拡大して実施するというところと、また、今年度高齢者の方のアンケートを実施して、その意見を取り入れて新たな講座というのを、基本アプリ講座という形で開催をする予定です。","id":"exchange-037"},{"speaker":"こしば委員","kind":"質問","question":"まさに今課長がおっしゃいました様々な施策の展開が、この認知症予防につながっていくことと信じております。上達の早い人がそうでない方に教えることによって、そこでまた交流が生まれてきた、そういったことなどをお聞きしました。先ほど課長の答弁の中で、ｅスポーツコースを新たに新設されたということでございましたけれども、その経緯について教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"男女にとらわれずに、高齢者の方の全ての方へのよりよい社会参加につながればよいと考えています。","id":"exchange-038"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ男性・女性の参加率の向上に向けて取り組んでもらいたいと思います。それとあともう一つ、アプリゲームを通じたそのスマホ体験のほうも新たに始まっていくですけれども、こちらのほうの年間の回数だとか、あと地域、どういった地域で行われていくのか教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"来年度新たに始めるものですので、最初の前半についてはテキストなどの構成ですとか中身のものなどを協議した上で、実際に始めるのは１０月、秋ぐらいを予定しているのですけれども、月に２回開催することで。","id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうなりますとどうしても、例えば大井第二地域でやられる場合はつまり年間で１回、２０人の参加となります。そうすると、若干その町会に入っている方々、高齢者クラブに入っている以外の方にもやはりこれが浸透していくことにやはり意味があると思いますので、その辺り、人数のほうも増やすことも検討していただきたいと思いますけれども、お考えを教えてください。","respondent":"川原高齢者地域支援課長","answer":"今後、中身のテキストであるとか教室の運営の仕組みを考えていく中で、人数、例えば２０名以上幅広く参加していただく中でも効果的に実施できるのかというところは、運営いただく事業者などとも協議をしながら今後検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"こしば委員","kind":"意見","question":"先ほどのお話に戻ってしまうのですけれども、このデジタル活用の進化というのはデジタルが得意な人だけでなく、デジタルに不得手な人、むしろその不得手な人の声をどんどん聞き取っていただいて、そこからまた気づくことがたくさんあると思います。それをまた次年度の事業にも置き換えていただくようお願いを申し上げまして、私のほうは終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、２２７ページ孤独・孤立対策推進事業、２５７ページ品川区子ども計画策定、２６７ページ養育費相談支援事業についてお伺いいたします。１点目に養育費相談支援事業についてお伺いいたします。養育費相談支援事業の現状と、面会交流支援に関する国や他自治体の最新の動向、また今後の見通しについても区のご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"こちらの親子交流支援についてですけれども、基本的に法務省のホームページにある面会交流支援団体の支援を基本としまして、こちらの団体を利用して支援を受けた経費を補助するということで、想定としましては、１年間の利用で上限を１５万円と考えているところです。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"今後親子交流を希望する区民の方々に対して、どのような周知を行っていくのでしょうか。国の動向ですとか都ですとか、あとほかの区の動向等も注視していただきながら、ひとり親家庭のしおりに安心・安全に親子交流を行っていくための情報を掲載するなど、必要な方々に最新の情報提供をお願いしたいと思いますが、いかがでしょうか。２点目に、品川区子ども計画策定についてお伺いいたします。","respondent":"飛田子育て応援課長、藤村子ども育成課長","answer":"ひとり親家庭のしおりについてですが、委員おっしゃるとおり、こちらのほうにつきましても積極的に周知を図ってまいりたいと思います。予算面のところですが、平成３０年度および平成３１年度の子ども子育て支援事業計画につきましては、こちらは２か年で策定していますので、予算ベースでいくと２か年で１,８８０万円程度というところ。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"子ども若者子育て支援の現場からは、過去に制度に苦しんだけれども、人に救われましたというようなお声もお聞きしております。３点目に、地域福祉推進費についてお伺いいたします。地域福祉計画策定のために実施した区民アンケートの結果、２０代、３０代の孤独・孤立感が顕著に表れていますが、ほかの調査を含めて、性別による結果の分析などありますでしょうか。","respondent":"東野福祉計画課長","answer":"区が令和４年度に行いましたアンケート調査の項目ですが、性別の問いは設けておりませんでした。よって性別の違いによる分析というものは、全体としても行っておりません。ちなみに令和４年度、同時期に内閣官房の孤独・孤立対策担当室で同様の調査を行ってあります。","id":"exchange-044"},{"speaker":"横山委員","kind":"意見","question":"誰もが困ったときに気軽に声を上げることができ、生きやすい地域を広げていくために、さらなる啓発活動や相談体制の構築をお願いしたいと思っています。区では「おたがいさま運動」なども進めておりますが、孤独・孤立の解消に向けて、孤独・孤立対策シンポジウムの開催時などに啓発活動をお願いしたいと考えますが、区のご見解をお聞かせください。","respondent":"東野福祉計画課長","answer":"委員からご指摘のありました点、とても大切な視点だと思ってあります。区で取り組んでいる「おたがいさま運動」の趣旨からも、孤独・孤立対策シンポジウム開催の際は、そういった啓発活動、ご紹介などをしていきたいと考えています。","id":"exchange-045"},{"speaker":"新妻委員","kind":"提案","question":"高齢者のほうですが、令和４年度介護保険制度の運営状況から、高齢者の人数を確認いたしました。これまで公明党が、お亡くなりになった際の葬儀や納骨等のサポート、いわゆるエンディングサポート、横須賀市の事例や、また人生の総仕上げをどう迎えていくのかについて、終活について提案・要望させていただきましたが、高齢者の死後の準備の必要性など、区の認識をお伺いしたいと思います。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"死後事務関係におきましては、社会福祉協議会におきましてターミナルサポート事業というものを行っております。そういったところの区民への周知を今後も行っていきたいと考えています。今後につきましては、やはり団塊の世代が２０２５年に７５歳以上になるというところと、その先、７５歳以上の人口が増えていくというところを鑑みますと。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"来年度の調査で、また具体的な調査をぜひお願いをしたいと思います。そして、次に若者支援というところで伺ってまいります。今般、児童センターで予算がつけられまして、南品川児童センターが児童センターの利用者層の年齢を上げて、今、改築を進めていくということです。品川区の若者の心と体の健康についてどのように認識をされているか、お伺いをいたします。","respondent":"藤村子ども育成課長","answer":"子ども・若者の心と体の健康という観点ですけれども、なかなかいろいろこういったご相談をする場というのが児童センターですとか、子ども若者応援フリースペースですとか、いろいろ用意はしているところなのですけれども。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問・要望","question":"性教育や食育、肥満、やせなど、自身の体に関する様々な健康教育の充実について、より積極的な取組が求められていると報告がされました。とかく１人で悩みを抱えやすい、また家族にも相談できない、そしてインターネット上の偏った、また不確かな情報に頼ってしまう。そのような若者が、気軽に医師や、またカウンセラーなどの専門家に相談できる場所が必要ではないかと考えますが、区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"こちらは対面ですとか、メール相談ですとか、電話相談というのを受けているという形なのですけれども、区におきましてもどのような形で、知見を有するような団体にこういったことを委託したり、思春期特有の様々な悩みですとか。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区とも関係があるかもしれませんが、例えばそういうような団体にもまたアドバイスを求めながら、ご協力をいただきながら、ぜひ品川区での若者の心と体の相談体制の構築をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、２３９ページ超短時間雇用促進事業と、２４５ページ品川区介護職員居住支援手当についてお伺いします。そこで質問です。事業内容としては、専任のコーディネーターを配置し、企業とのマッチングを行うということですが、コーディネーターの配置は何人ぐらいを予定していて、どういった企業を予定しているのでしょうか。就労先として、品川区のこの区のお仕事というのは、想定はないのでしょうか。","respondent":"松山障害者支援課長、崎村人事課長","answer":"来年度はもう本格的に実施するということで、今年度も企業に障害者支援課の職員とともにアプローチをもう開始していますが、具体的にはコーディネーターが企業開拓をしてマッチングをするということで。品川区では令和４年度から、障害を持つ方を会計年度任用職員として採用いたしまして、各課で行っている例えば大量の印刷物ですとか封入ですとか、委員からお話がありました例えばデータ入力ですとか。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ぜひ引き続きよろしくお願いします。ぜひよろしくお願いします。今後の超高齢化社会を見据えて介護職員の確保と労働環境改善のために、介護の専門職の登録と紹介を品川区で行うということはできないのでしょうか。これを応用する形で、介護職員、介護専門職の方にも登録してもらい、区内で不足している事業所に紹介するシステムを品川区で作れないものでしょうか。ご見解をお聞きします。","respondent":"菅野高齢者福祉課長","answer":"ここにおいて、今後そういった介護職とか資格を持った方たちの登録制度については、今後介護学校でどのように展開しているかというのは進めていきたいと思っているところです。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"２５７ページ品川区子ども計画策定における子ども若者の意見表明、２８１ページ私立幼稚園支援について伺ってまいります。子ども若者の意見表明についてですが、アンケートの進め方について伺いたいと思います。どのようなプロセスをお考えでしょうか。世田谷区は質問を具体化して、「なんでやねんすごろく」を実施していると伺いました。区の考えと検討していることがあればお聞かせください。","respondent":"藤村子ども育成課長","answer":"こちらのメンバーに関して、もちろん固定のメンバーで行って、１回目と２回目で経過観察というか同様の方に意見をお伺いできれば一番いいのですけれども、なかなかそこは人員の面でうまくできるかというところはありますので。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問","question":"ワークショップを様々な場所でというのはすごく面白いよい取組だと思います。アンケートやワークショップを通じて子どもたちの声やアイデアを聞いていただきまして、それを実現するために応援金を出すチャレンジアクションみたいなものをやれないかなと思っています。品川区でも、子ども若者の「やりたい」を実現するために応援していくような取組はできないでしょうか、伺います。","respondent":"藤村子ども育成課長","answer":"お子様というか児童・生徒の声をいただいて、例えばこういったことがやりたいとか、こういったことができないかとか、区のほうにお声をいただいたりしたという形であれば、例えばその青少年主体でやっていただくとか、区のほう主体でやるというところ。","id":"exchange-053"},{"speaker":"西村委員","kind":"提案","question":"まさに小学生は児童センター内での取組などはどうかと思っていたのですけれども、同じくこの若者支援に力を入れている尼崎市ですので、実際に伺いましたところ、地域の課題や魅力を学び、その解決に向けた取組を企画するワークショップを市が開催しまして審査をし、選ばれると、それを実践するための応援金が上限５万円で交付されると。","respondent":"藤村子ども育成課長","answer":"こちらにつきましては、子ども基本法の中にそのこども大綱というところと、あと子ども計画が規定されているところですが、そちらのほうの理念として誰一人取り残さないですとか、子どもの意見表明というところ、数点ほかにも記載されているところなのですけれども。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問・要望","question":"私立幼稚園の在り方について、以前にも質問していますが、区の中でも取組が進んでいることがありますので、伺ってまいりたいと思います。区の担当課の職員の皆様から出てくる自由なアイデアが柔軟に実現される環境下で、保護者のニーズをつかみ、求められる具体的な施策は何か。品川区ならではの取組を実践していただきたいと思いますが、ご答弁をお願いいたします。","respondent":"石井保育支援課長","answer":"今後、私立幼稚園が新制度移行に向かうにあたっても、区の職員が丁寧に説明をしながら支援をしてまいっておりますし、おかげさまで令和６年度にも１園、そして現在令和７年度に新制度移行したいという相談も１園受け付けているところです。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"２４５ページの介護職員居住支援手当および障害者福祉の職員も一緒に伺いたいと思います。続いて２４３ページの特別養護老人ホーム運営費についても伺いたいと思います。それならば、品川区としてはそもそも誰をどこまでを対象者にしたいと区としては考えているのかを伺いたいと思います。本会議の答弁では直接処遇をする人との説明がありましたが、それでは区は事務職の方は対象とは捉えていないのかどうか。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"国の介護報酬の対象者や、あとは東京都の特別支援手当の対象者、その辺りのところの状況も鑑みながら、今後、対象者についてはさらに検討していきたいと考えています。障害分野における居住支援手当につきましても高齢者と同様、直接処遇に係る障害福祉サービスの従事者ということにしています。介護職員と同様、今後、国や都の動向を見ながら、詳細には詰めていきたいと考えております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"提案","question":"介護と障害者と基本的に同じ考えみたいなので、とりあえず介護のほうに伺いますけれども、先ほど伺ったのは、直接処遇の方というのは既に答弁は出ているのですけれども、私は事務職までしっかり対象にしていただきたいとご提案をさせていただきました。ぜひ事務職も含めて、この新たな居住支援手当の対象にしていただきたいと思いますが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"それを取り巻く、それを支える事務職など、そこの事業所に勤める方たちを対象にするかなどにつきましては、今後事業者や関係者機関と協議をしながら、詳しいところは詰めていきたいと考えています。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"それだけに、同じ職場で働いている事務職の方を対象にしないというのはあまりにも、やはりどのような仕事もチームワークで動いていますので、ぜひ事務職を対象にしていただきたいと思いますが、その関係機関との調整とありますが、区としてはどう考えているのか、改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"現状の仕組みにおいてこれ以上の報酬のベースアップが難しいというところで、区内事業者において、直接処遇に係る介護サービス従事者に対して区独自の手当を支給することとなっております。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"ですから、事務職は対象にしないというのが区の考えなのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"恐らく事務職だけではなくて、介護事業所にはほかのいろいろな職種の方もいらっしゃると思います。そのことも含めて検討しなくてはいけないと思っているところです。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、例えば特別養護老人ホームにしろ、グループホームにしろ、障害者福祉の施設も含めて、そこで働いている方々全員を対象にしていただきたいと強く要望したいと思います。次に、特別養護老人ホームについて伺います。区長の施政方針では、「介護・医療ニーズのさらなる増加が想定」と施政方針で述べられましたが、増加するニーズに特別養護老人ホームはあるのかないのか伺いたいと思います。","respondent":"東野福祉計画課長","answer":"これまでも在宅支援を重視しつつ、在宅での生活が難しくなったときのセーフティネットとして、高齢者グループホーム、小規模多機能型居宅介護も含めた様々な整備を進めることで、区民の選択肢を広げてまいりました。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、総合的に検討するとの答弁がありました。この中に、特別養護老人ホームの増設は入っているのかと伺いました。お答えください。区長の施政方針で、介護・医療ニーズのさらなる増加と述べているのです。この今後増加するニーズの中に、特別養護老人ホームはあるのかないのかお答えいただきたいと思います。","respondent":"東野福祉計画課長","answer":"特別養護老人ホームのニーズにつきましては、特別養護老人ホームにまだ入居待ちの方もいらっしゃるという事実がありますので、あるというふうに認識しております。それを踏まえた上で、区としてできることをやっていきたいと考えています。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"ニーズは今あるとはおっしゃいましたけれども、今後、東大井、八潮南、小山台の３か所に造ることは表明されておりますけれども、その先の計画がないということなのです。これがなぜなのかと伺いたいと思います。私は３か所目以降のさらなる特別養護老人ホームの考えを持ち、計画を具体化することが必要だと思いますが、いかがでしょうか。","respondent":"東野福祉計画課長","answer":"特別養護老人ホームにつきましては、繰り返しになりますが、区として所有している土地、それから民間が所有している土地、そういったものも含めましてできることをやっていくつもりです。現在のところ計画がない実態はありますが、今後区として総合的に検討してまいります。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"できることをやっていく、総合的に検討する、結局３か所目以降の特別養護老人ホームの方向性は何も示されていないのですね。ぜひ森澤区長にあたっては区民の実態に目を向けて、さらなる特別養護老人ホームの増設の考えを持っていただき、具体化していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"一般質問でも、医療的ケア児等コーディネーターを活用し、さらなる体制の整備、そして行政においても各部署にとどまらず、横断的な整備を行うことを求めました。そこで、事務事業評価を確認しました。目標は年３回となっております。は医療的ケア児等支援関係機関連絡会の今年度の実績、また、これとは別にあるコーディネーター連絡会というのはどういったものなのか、改めて確認をさせてください。","respondent":"松山障害者支援課長","answer":"現在、本年度もコーディネーターが集まり、打合せや他区の施設などを視察し、情報共有を図って、次年度からの相談の流れについて意見交換を行ってまいりました。次年度につきましては連絡会と位置づけまして、研修や事例検討を含め、定期的に実施する予定です。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現状はなくて、今７名いらっしゃるのですけれども、それぞれが情報を持っていて、そこで合わせて情報共有をしているという形になっていると思うのですけれども、どこか一つ窓口があって、そこにコーディネーターが１人いて、そこが皆様に情報共有をしたりとか研修を組立てたりとか連絡会の調整というものをすると、この目標の３回にも届きますし。","respondent":"松山障害者支援課長","answer":"ただし、総合窓口というよりは、現在は現実的に障害者支援課が中心になりましてコーディネートし、あるいは研修、連絡調整も含めて行っていくことを想定しております。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現在取り組んでいただいている支援について把握はしましたが、ぜひ柔軟に考えていただき、困っているご家族の負担がさらに軽減をすることを求めまして、次の質問に移ります。次は避難行動要支援者個別計画作成について伺います。はこちらの近年の実績、また進捗についてお聞かせください。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"令和３年度から実施しておりまして、令和３年度については、モデル実施として４４人作成済みです。令和４年度につきましては４０３人が作成済み。そして今年度につきましては、直近で８０人の方を作成しております。作成にあたっては、平時において支援を行うケアマネジャーに作成を委託し、実施しております。令和２年度のモデル実施から始めまして、令和６年１月現在で累計約８,０００件の原案を作成いたしました。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"高齢者支援課のほうについては、対象１万人ぐらいというところに対して原案が８,０００件を超えているということで、８割ほどは原案の作成ができているのかと認識をしておりますが、この対象者の選定とかその優先順位というのはどのように決めて作成しているのかというところも、簡単で大丈夫なので教えてください。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"障害の方の場合は同意を得ながら本計画に策定するということで、きちんと１人ずつ個別に対応しているのが現状でして、お待たせしている方には申し訳ないと考えています。高齢者の部門につきましては、まずこの作成の順番と優先順位の考え方についてなのですけれど、本来なら避難行動要支援者は要介護度１から５の認定を受けている方なのですが、区では要支援者１。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"このテーマを今回取り上げたのは、実は防災学校といって地域の町会の防災の催しに参加させていただいたときにこのお話が出まして、以前だったらもう少し町会とか民生委員とかでいろいろ見ていたのだけれども、今その計画とかが全然共有がなされていないのではないかというところで、その計画を立てるだけではなくて、実際の行動に移っていくためにはやはり地域の力というのが必要なのかなと思いまして。","respondent":"菅野高齢者福祉課長","answer":"ただし、防災課と令和４年度モデル事業を実施させていただきまして、実施した町会からのご感想を聞くと、やはり福祉的な対応などが分からないことがたくさんあるとか、当事者の動きが見えてくると効果的ではないかなどの意見とかいろいろ出まして。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"確認","question":"ちょっと時間が限られていますので、最後にひとり親家庭支援事業について、午前中にも質疑がありました親子交流、面会交流の支援についてお伺いをいたします。この点は質問がかぶらないように質問させていただきたくて、私の中では１点だけ確認をさせていただければと思っています。この事業に子どもの権利が守られているのかというところだけ、１点確認させていただければと思います。","respondent":"飛田子育て応援課長","answer":"離れて暮らす親も、子どもにとっても親であることに変わりはないということなので、やはり自分を見てくれる存在が実際いること、またそういうところで成長を見守っていることを実感していくことが、子どもの福祉向上につながっていくのではないかと考えております。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、子どもの気持ちというところを第一に考えた制度になるとよいと思っています。品川区としてこれに取り組んでくださっていることは、私たちもすごくよいことだと思っているので、その親子にとってよりよいものになるよう求めまして、私からの質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問","question":"２６０ページ児童相談所費、２５５ページ多世代交流支援事業、２４６ページ高齢者地域支援費、２２７ページ孤独・孤立対策推進事業、２５７ページすまいるスクール運営費について伺っていきたいと思います。児童相談所ですが、昨日の質疑でしながわ見守りホットラインの無料化については見解を伺いました。","respondent":"長谷川児童相談所開設準備課長","answer":"児童虐待の通告先になりますけれども、令和６年１０月１日児童相談所開設後は、品川児童相談所から引き継ぎまして、区児童相談所が受け付けることになります。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問","question":"しながわ見守りホットラインについては、児童相談所が受け付けるということと、あと国のほうである１８９ですね。これはどちらにつながるのか、そこを教えてください。","respondent":"長谷川児童相談所開設準備課長","answer":"今のお話ですけれども、児童相談所開設後は、同様に区児童相談所のほうに通告が走ることになります。その方の一義的には発信地を特定してつながっていきますけれども、その後の振り分けで区児童相談所のほうにつながる仕組みとなっております。","id":"exchange-072"},{"speaker":"つる委員","kind":"提案","question":"２年前ぐらいに文教委員会で質疑させていただいたときは、まだそこの段階では国や東京都との確認作業というところで明確ではなかったわけでありますけれども、今後は昨日のしながわ見守りホットラインの周知、半年ぐらいをかけてということでありましたけれども、ここについてもしっかりと区民の方がまず身近に地域の課題をしっかりと捉えていただいている方々が、通告先。","respondent":"川原高齢者地域支援課長","answer":"高齢者を中心とした多世代交流、ｅスポーツを通じた交流についてのご回答です。２月に実施した平塚橋ゆうゆうプラザにおいては私も視察をさせていただいたところです。","id":"exchange-073"},{"speaker":"つる委員","kind":"提案","question":"続きまして高齢者地域支援ということで、これはちょっと今から提案する、また確認する案件としては、品川区のこうした予算特別委員会のルールの中では産業経済費にかかってくる部分もありますので、民生費のところの部分で可能な範囲で品川区の現状を伺いたいと思ってありますが、いわゆる地域共生社会、一生懸命全国で各自治体がそれぞれ推進をしているという中で、いろいろな国、都、区と事業を展開して。","respondent":"川原高齢者地域支援課長","answer":"シニア向けのボランティアコーディネートサイトというものも社会福祉法人が実施をしていますので、そういった動向を注視しながらまた情報収集に努めていって、品川区においてもどういったことができるかというのは、今後研究してまいりたいと考えています。","id":"exchange-074"},{"speaker":"つる委員","kind":"質問・要望","question":"今度は産業経済費のところでも伺っていきたいと思いますけれども、１つの事例として千葉県の柏市などは、こうしたワンストップで例えば生涯現役窓口というところで、どちらかというと就労のほうに重きがあるのかなと思うのですけれども、そうした地域の貢献のことも含めてまずは相談の窓口ということでやっていたりとか、そういうところもありますので、ぜひいろいろな自治体の取組も含めて。","respondent":"東野福祉計画課長","answer":"孤独・孤立とオーバードーズの関係ですが、昨年秋ぐらいにトー横キッズ問題などでオーバードーズの報道が取り上げられていたというふうに認識しています。","id":"exchange-075"},{"speaker":"つる委員","kind":"質問","question":"学校のほうでは薬育というところで、区内の薬剤師の皆様にご協力をいただいて、かなり前から薬物のこととか、それから近年はそのオーバードーズのことについても若干触れていただいている学校もあるというふうにも伺っておりますので、広く区民の皆様への周知というところでは、今ご答弁いただいたことも含めてぜひ推進をお願いしたいと思います。時間をかけて伺っていきたいと思います。","respondent":"藤村子ども育成課長","answer":"すまいるスクールのほうは、放課後の全児童対策事業として実施しているというところですので、基本放課後というところで、委託の職員というのが９時半に出勤している状況になっているというところなので、なかなか朝開くというところが少し難しいかなというところなのですが。","id":"exchange-076"},{"speaker":"つる委員","kind":"意見","question":"ゆうゆうｅスポーツ交流会についてもご答弁いただければよかったのですけれども、時間がなかったので慌てて答えていただいたかと思いますが、この朝の対応については教育委員会含めて、引き続き様々な観点で品川区として検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"提案","question":"お願いします。先ほど、おぎの委員が質問されていた介護専門職の登録紹介という制度の提案、これは同じ厚生委員の我々２人でいろいろ同じような話をしていまして、それの続きになるのですけれども、先ほどのお話で、紹介会社を使うと８９万円ぐらい平均でかかってしまうと。これについて区としてどうお考えなのか、率直なご意見をお聞かせいただけますか。","respondent":"菅野高齢者福祉課長","answer":"そういったところも含めて、区のほうでは事業者たちが不当にそういった手数料が取られることがないようにというところで、情報提供等をしていきたいと考えています。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"制度があるという、優良認定制度みたいなものができたというのは存じ上げているのですけれども、ぜひその辺は頭の隅に入れておいていただきたいということと、あと、先ほどのおぎの委員の最後の答弁ところで、介護人材の登録について、福祉専門学校のほうで進めていくというようなお話がちらっと最後あったと思うのですが、その辺もう少し詳しくお聞かせください。","respondent":"菅野高齢者福祉課長","answer":"そこで人材育成をして、そこで区内の事業者のほうにあっ旋というかマッチングをするということを行っているというのが背景にあります。その中で、登録の方法とか今後どうしていくかなどについては、効果的な方法等も考えながら検証していきたいと考えています。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"介護福祉専門学校は、多分令和５年度に卒業生が今２３名まで減ってしまっていたりとか、基本的に学費が免除になるのが、大きい社会福祉法人に就職しないといけない、３年間働かなくてはいけないということで、ぜひこれは枠を拡大してほしいというのと、あとそういったマッチングサービスとかサイトを作るのであれば、それこそ品川区に在住している福祉関係従事者の方。","respondent":"菅野高齢者福祉課長","answer":"介護人材の部分につきましては、手数料の部分が事業所をかなり経営的にも圧迫しているというところは踏まえておりまして、まずは今年度法人向け、施設の職員向けになのですけれども、介護職員についてもその優良職業紹介所を使った場合は。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひお願いします。次に行きます。デジタル活用のほうなのですけれども、初めてのスマホ教室とかスマホよろず相談とかをされているのですけれども、これというのはデジタルディバイド対策、いわゆるスマホとかＰＣが使いこなせない人と、そうでない人に差が生じるのを解消するためにということの事業の一環でよろしいでしょうか。","respondent":"川原高齢者地域支援課長","answer":"今委員がおっしゃっていただいたデジタルディバイドの解消ということに加えまして、高齢者の方の生きがいの創出ですとか、あと人と触れ合うことによる社会参加促進というところも、フレイル予防、認知症予防の点からも兼ねております。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実はこういったスマホのよろず相談とか体験教室みたいなのを無料でやっている方がいるのはご存じですか。それは介護従事者なのです。デイサービスに来て、高齢者が、これやり方が分からないから、どうやって使うのとか聞かれるのです。１人教えてしまうと皆がわあっと来てしまったりして仕事が回らなかったりするので断ってしまったりとか、結構それで険悪になったりする状況が実は生まれております。","respondent":"菅野高齢者福祉課長","answer":"高齢者のデジタルディバイドの関係だと思うのですけれども、その中で介護事業所の職員たちが、そのように縁の下の力持ちで支えてくださっているということに感謝したいと思います。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"多分知らなかったと思ったのですけれども、例えばスマホの相談ができる認定デイサービスとか、そのような感じで何か掲げさせていただいて、それで月１万円とか２万円でもインセンティブをいただいて仕事として受けるというような感じでやらせていただくと、対価をもらってやるので我々も仕事として対応できますし、デイサービスの中で、これは対応しては駄目だよとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"よろしくお願いします。私からは、プレス発表の８７ページ、ｅスポーツを通じた多世代交流、あとは同じページの液体ミルク自販機、２６７ページ養育費相談支援事業、時間があれば２５９ページの産後の家事育児支援についてお伺いをしたいと思います。ｅスポーツのお話は今のつる委員からいただきましたので、１点だけお伺いをしたいと思います。まさにこれが多世代交流なのだと思います。","respondent":"藤村子ども育成課長","answer":"ツールとして、ゲーム機を今後ｅスポーツの観点から活用するために、年４回程度、こういった形でゆうゆうプラザに限らず、ｅスポーツでの多世代交流というのをやっていこうということで児童センター内が取り決めしておりますので、まずはそういった形で活用してまいりまして。","id":"exchange-084"},{"speaker":"せりざわ委員","kind":"提案","question":"はやってみるということで、非常によい取組だったと思います。今回、いよいよその養育費をそもそも取り決めしていくというところにまで支援を拡充していくということでありますが、まずここの経緯をお聞かせいただきたいのと、あとは、この取り決めをしていくところの要は制度が、名前は一緒ですけれども制度が大きく拡充していくわけですから、これの周知をどのようにしていくのかお聞かせください。","respondent":"飛田子育て応援課長","answer":"今後、こちらのＰＲのほうに関しましては、またパンフレットなどを作成して、そのほかにも戸籍住民課とも連携していきまして、手続きに来た方にパンフレット等を配布したり、またホームページ上にＱＲコードなどをしまして、周知の工夫をしていきたいと考えています。","id":"exchange-085"},{"speaker":"せりざわ委員","kind":"質問","question":"この月５万円という額を考えると、もしくは年間６０万円程度というふうに考えると、ひとり親の家庭からすると、人生の選択肢が大きく変わっていくような非常に大きな仕組みだと思っています。ですから、なおさらこの周知にお金をかけて、しっかりと周知啓発をしていくということに大きな意味があると思うのですが、この遡及も含めてどういった周知をするのか、改めてお聞かせください。","respondent":"飛田子育て応援課長","answer":"周知のほうは、今回また予算のほうでパンフレット等も重ねて、そのほかに動画作成も考えておりまして、今回養育費のこの支援のところではいろいろ分かりにくい制度もありますので、そういうところも離婚前後というところも絡めながら、今後どういう手立てをすればいいか。","id":"exchange-086"},{"speaker":"せりざわ委員","kind":"提案","question":"当時、東京都の補助金がなくなるかもというお話を議会でもさせていただいて、時限的に延長になったと理解していますが、とはいえ令和７年ですか、一定程度でまた期限が来てしまう。例えば東京都の補助金がなくなってこれで終わりというわけにはなかなかいかないと思うのですが、補助金が仮に切れてしまった場合の区の方向性というのを改めてお聞かせください。","respondent":"飛田子育て応援課長","answer":"委員おっしゃるとおり、当初は都のほうでは令和４年度で補助が終わるというふうにおっしゃっていましたけれども、現在国が２分の１、都が４分の１、区が４分の１ということで継続することとなりました。","id":"exchange-087"},{"speaker":"せりざわ委員","kind":"質問","question":"かつてこの養育費の取り決めというのが、ほかの制度に比べたら非常に大きな支援ですよねというお話をさせていただいて、まさにそのとおりだと自分でも思っていますが、この毎月５万円ぐらいの経済支援というのは、ほかの補助制度では恐らくないものですから、これぐらいの支援で、当たり前ですけれども養育費はもらったほうが得なのではなくて、もらえるのが当たり前の世の中を作らないといけなくて。","respondent":"藤村子ども育成課長","answer":"こちらは職員提案制度という制度で、設置のほうを今検討していますが、防災の観点からと言いますと、児童センターのほうが災害時の補完避難所というような形になっておりますので、この液体ミルク等を災害時に無償で使えるような形でということで。","id":"exchange-088"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"は今回１か所でというふうな予算案かと思いますが、ぜひこれは様々なところにお広げいただきますように、これは要望で終わります。もう一点、産後うつについてお伺いをします。品川区も、今、産後うつ、いろいろな支援をやっておりますが、男性が受けられる、男性を対象としている産後うつ支援というのがあるのか、お聞かせください。","respondent":"染谷子ども家庭支援センター長","answer":"男性の産後うつに対する予防的なところの対応というお話ですけれども、現在産後ドゥーラのほうで産後の家事・育児支援を実施しておりますが、こちらの中で令和５年度から、母親のみを対象としていたところを。","id":"exchange-089"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、２５１ページの国民年金事務費についてと、２５０ページからの児童福祉費の中だと思うのですが、少子化対策全般についてお伺いします。よろしくお願いします。","respondent":"菅野高齢者福祉課長","answer":"今後、そういった介護事業者が日々高齢者のためにやっていただいている介護保険以外のプラスのサービスについては、どのようなことを提案していただけるのかというところも、区全体の事業も含めて検証していきたいと思います。","id":"exchange-090"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ、いい取組だと思うので検討いただければと思います。私の質問に入ります。国民年金についてですが、その前に少子化対策を先に行きます。この少子化対策、区としてどのように考えているのか。そして、この少子化というのがどのような原因で起こっていると思っているのか。そして、国や都からのどのような少子化対策支援というのが補助金等で行われているのか教えてください。","respondent":"佐藤企画課長、藤村子ども育成課長","answer":"少子化対策に関するご質問です。少子化の原因ですが、育児に関わるコストや仕事との両立の負担、また育児への不安、未婚・晩婚化等々と言われていると認識しております。少子化対策に係る特定財源というところですけれども、そちらのほうは、今区のほうで受けている補助金の中では、その少子化対策ということで中心にいただいているというものはないかと認識しております。","id":"exchange-091"},{"speaker":"石田（し）委員","kind":"質問","question":"区としてもいろいろと取り組んでいて、これは区だけではどうしても解決できない大きな問題だと思っています。なので、私はこの少子化対策というのは、１つはやはり若者の所得増、もう一つはいわゆる２人目以降の多子世帯の支援。婚外子一つとってもそうだと思う。そしてもう一つ、そのまま国民年金のほうに行きますが、国民年金の給付額というのはどのように算定されて給付されているのか教えてください。","respondent":"佐藤企画課長、池田国保医療年金課長","answer":"多子世帯に関しましては、区のほうでも様々な制度のバックアップ等をしているところでございまして、賃金と婚外子というところに関しましては、賃金に関しましては国のほうで様々対応しているというのも把握しているところで。年金についてですけれども、年金につきましては国のほうで毎年、翌年の年金満期額というのが示されまして、４８０月納めた方についてはその満額を支給する形になりますけれども。違いますか。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"すみません。私の聞き方が間違っていました。いわゆる年金の額を決定する方法というのは、どのような方法でこの年の金額というのは決まっているのか教えてください。給付額です。","respondent":"池田国保医療年金課長","answer":"給付額とは年金の額ということだと思います。物価連動のスライド制を使ってやっているところです。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"意見","question":"すみません、その答えが欲しかったのです。いわゆるマクロ経済スライド方式でやられていると思うのですが、これは物価の高騰もそうなのですけれども、実は現役世代の給料もこれは算定の一つですね。お答えください。","respondent":"池田国保医療年金課長","answer":"こちらの年金については物価スライド制ということで、国のほうで来年度は幾らにするかという数字が来て決まっていますので、あと、私どもで計算するのは、あくまでも年金をかけた月数、それと実際に支払っていない月数で決めていくというだけですので。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ずっとこれが３０年間。ならば、私はもうそろそろ公務員の方たちが勇気を振り絞って、自分たちの給料をまず上げていくのだ、それで民間の企業を底上げしていこうというぐらい私はやっていきたいと思うので、ここは私は応援するし、多分多くの方たちが応援してくれると思うので、ぜひここは森澤区長のリーダーシップの下、もちろん２３区のいろいろな事情もあるし、そこはぜひ頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、２２９ページの戸越地区児童発達支援センター等整備、それから、２５５ページの児童センター学習用Ｗｉ－Ｆｉ設置・運用、時間があれば２４７ページの高齢者社会参加支援について伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"児童センターの学習用Ｗｉ－Ｆｉのご質問ですが、こちら設置予定の館としては、東中延児童センター、冨士見台児童センター、東大井児童センターの３館を予定しているところです。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"今理由もお聞きしましたけれども、今後残りの館についても拡大という方向であるのかどうか、そこだけご答弁お願いします。","respondent":"藤村子ども育成課長","answer":"今回、Ｗｉ－Ｆｉの運用にあたって、児童センター全体でやはりこちらについてもＷｉ－Ｆｉの運用ルールというのを定めてやっていく形になりますので、学習用という形なので、学習用以外にもどういった活用があるかですとか。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。次に、戸越地区児童発達支援センター等整備ですけれども、この第１回定例会で、大原児童発達支援センターの条例が議案上程をされまして、厚生委員会のほうで議論があったと。全会一致でこれは賛成、成立と伺っております。一括して指定管理方式で今後運営をということで考えていると聞いております。","respondent":"川崎障害者施策推進課長","answer":"戸越地区児童発達支援センター等整備ということで、大原児童センター内に区内２か所目となる大原児童発達支援センター整備を行うもの、これが地域における療育環境の充実を目指すものということで、こちらの整備を進めているものです。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"品川区として今回初めてみたいな、比較的珍しいものになるのかどうか。そういったところについての認識をお伺いしたいのと、また、今後児童センターは品川区にまだたくさん二十数か所あるわけですけれども、こういった児童発達支援等の兼ね合いをしていく、このインクルージョンの考え方で施策展開していくような考え、これについてはいかがでしょうか、お聞かせください。","respondent":"藤村子ども育成課長","answer":"今後のインクルージョンというところですけれども、他の児童センターとこういった形で複合施設になるかというところですと、児童発達支援センターの複合施設というのは、今予定しているところはないですけれども、やはり障害のある方もない方も児童センターをご利用いただいて。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"そういったところについても最後にお伺いしたいと思います。","respondent":"藤村子ども育成課長","answer":"こういった形のケースはなかなか珍しいと思いますので、対応できる事業者がいるかどうかというところではありますが、例えば単独でこれに対応できる事業者というのがいなければ、共同事業体というような考え方も区の方針の中で使えないということではございませんので。","id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は２２５ページ高齢者のグループホームのことについて、お伺いをいたします。これが大体６０坪も必要なわけです。そのとき家賃もかかる。その前に、民間でもそういうところがあったら、そういう大家がいて、建て替えるときにこういうことができますよというようなことをしていかないと、なかなか前へ行かないと思っていて、そこら辺のところをどう考えていらっしゃるか教えていただけますか。","respondent":"東野福祉計画課長","answer":"来年度なのですけれども、区のほうといたしましてはセミナーの開催ですとか、それから今後の予定についてのすり合わせ、こういうものを高齢者の部門と一丸となって取り組んでまいりたいと考えているところです。","id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"質問","question":"なかなか質問がかみ合っていないような気がしますが、そのマッチングはできると思っている。その事業者がもらえる金額は決まっているのだから、だからそれでグループホームの今もらえるお金では、結局何かをどうにかして組み合わせていかないと、無理だと。この点のことを、そういうことも考えていかないと、こういうことは前にいかないのではないですかというのを、もう一度そこを聞きたかったわけです。","respondent":"菅野高齢者福祉課長、今井福祉部長","answer":"認知症高齢者グループホーム、区では家賃助成事業というのは実施しております。ここの部分の充実につきまして、施設整備だけではなく、運営費に関しても総合的に検討する必要があるということのご指摘というふうに受け止めております。","id":"exchange-102"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうですね。それで改修をして、それはその支援もたくさんあったから、広さもあったからやれる。それをどういう感覚で捉えていくのだ。敷地も大変だけれども、そういうのがあっても運営のところでぶつかってきてしまうので、だからこれはぜひ、これからそこの部分についてもやっていっていただければ、品川第１地区でも品川第２地区でも必ず何軒かできると考えていますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"せお委員","kind":"質問・要望","question":"よろしくお願いします。２６７ページ子ども食堂開設・運営支援、２７３ページ就学前教育推進費についてお伺いします。初めに子ども食堂です。私としても整理したくまず質問させていただきたいのですが、改めて子ども食堂の意義と目的を教えていただけますでしょうか。","respondent":"飛田子育て応援課長","answer":"ですので、我々としましては食の支援を含む子どもの格差を改善するということで、地域や子ども食堂に任せきりになるのではなく、区としても子育て応援課が実施しているこのしあわせ食卓事業や学習支援事業などを含めて。","id":"exchange-104"},{"speaker":"せお委員","kind":"質問・要望","question":"子ども食堂の利用者の安心につながることもまた大切だと思っているので、保健所などとも連携した、これから申請しようとする団体などの思いとかを知るようなことができるような仕組みの構築を要望いたします。そういった助成金とかの認定については、国や都からの要件などがあるのでしょうか。都からの補助金もありますし、ちょっとここの詳細を私が分からないので、教えてください。","respondent":"飛田子育て応援課長","answer":"都のほうのところですが、特にそういう決まりというのはありません。","id":"exchange-105"},{"speaker":"せお委員","kind":"質問・要望","question":"何か運営側の地域の皆さんが気になったことなどを、次につなげる仕組みというのはあるのでしょうか。そういったことの課題などをどう捉えているか、区の見解を伺います。","respondent":"飛田子育て応援課長","answer":"子ども食堂の成り立ちは先ほど説明させていただきましたけれども、区が押付けに近い形でこのような条件をやってほしいとか、一律何か委託のようなことで制限するのではなく、やはり子ども食堂の成り立ちを尊重しまして、ボランティア精神のある方が子ども食堂を手伝いたい。","id":"exchange-106"},{"speaker":"せお委員","kind":"質問","question":"就学前教育推進費に移ります。こちらはちょっと広くお伺いします。現在区立園では、ありがたいことに障害児の受入れを積極的に進めていただいていたので、受入れ困難になることは少ないですが、私立園ではいかがでしょうか。研修に関して言えば、のびしなプロフェッショナルスクールですが、対象を区立・私立関係なく、そして介助員・支援員の方とかも含めてという形はできるのでしょうか。","respondent":"石井保育支援課長、立木保育課長","answer":"従前から申し上げておりますとおり、私立保育園などで加配をした場合の加算措置などもしていますけれども、そういった方々が私立保育園の中で健やかに過ごしていただけるために、研修体制等も含めて支援をしてまいりたいと考えています。のびしなプロフェッショナルスクールに関しましては、今年度から会計年度任用職員も対象とするようにいたしました。私立の職員の方も受けられる研修というのは用意しています。","id":"exchange-107"},{"speaker":"せお委員","kind":"質問・要望","question":"よろしくお願いします。先ほど澤田委員がお話ししたペアレントトレーニング、さらには来年度予算の子ども家庭支援センターでの子育て支援専門プログラム、ともにとても大切な取組でより充実していっていただきたいのですが、こういった講演会やプログラムなどに参加されない、でも支援が必要な保護者に対してはどのようにアプローチしますでしょうか。そういったことの見解をお聞かせいただければと思います。","respondent":"立木保育課長","answer":"１日保育士体験はコロナで休止していたのですが、今年度再開いたしまして、今年度は１,１００人以上の方がもう既に受けていらっしゃっています。そういったところをしっかり子育てのほうにつなげていきたいと考えています。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"私は２４３ページ特別養護老人ホーム運営費に関して、続いて国保会計の４６７ページデータヘルス事業について。時間がありましたら、２３１ページの東京２０２５デフリンピック周知啓発についてお伺いします。区立の特別養護老人ホームと、いわゆる民間の特別養護老人ホームとの違いについて、簡潔にお聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"民設については、それぞれの運営事業者がご自分で土地とかを購入して、そこに建てて運営していると認識しております。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"工事現場でのその職員の処遇の状況、休みをきちんととれているかどうかとか、現場の安全性が保てているか。今のようなことは特定のところだけなのかもしれませんけれども、私は決算特別委員会でも言いましたが、ぜひ介護現場をもっと見てほしいというのはそういうところが現実にありますので、そこはしっかり見ていただきたいと思いますが、現在の認識についてお聞かせをいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そこに、やはり例えばＩＣＴの機器を入れるなどの、区の施設ですのでそういった補助をするなどして、少しでも働いている方の業務が軽くなるようにというような部分の支援等はさせていただいているのですけれども、今の委員のご指摘の状況等は。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ現場を踏まえて、区立を名のる以上は介護本来の質ももちろんですが、そこに勤めているその要は指定管理者の中の話かもしれませんけれども、ぜひチェックというか見ていただきたいと思います。なぜそういう学生さんが敬遠するのかという原因についても、そこは介護福祉専門学校のＯＢ・ＯＧの方も含め先生方にもぜひ聞いていただいた上で、現状を理解いただいた上で対応をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"松永委員","kind":"質問","question":"私からは、２３１ページの東京２０２５デフリンピック周知啓発について、２４７ページ、認知症高齢者支援事業について、同じくデジタル活用による高齢者社会参加支援について、２５９ページのヤングケアラー支援事業について伺いたいと思います。初めに、２５９ページのヤングケアラー支援事業について伺いたいと思います。本区としてこの回答率についてどのように捉えられているのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"無回答というところにつきましても、内容において、回答を進めていくに当たってどんどん気持ち的につらくなってくるようなことも想定されるというのが、作成しているときの考えでございましたので、ご本人向けにご案内を発送する中にも。","id":"exchange-112"},{"speaker":"松永委員","kind":"質問・要望","question":"このアンケート結果から、ヤングケアラーと言われている方はどのくらいおられるのでしょうか。小学、中学、高校それぞれ伺いたいと思います。どの程度の期間ケアしていただけるのかどうか。例えば利用時間については何時から何時までとか、１日で何時間とか、そうしたところを教えていただきたいと思います。そしてまた、土日・祝日も可能なのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"基本の時間帯としては８時半から１８時ぐらいの間でというところで、今、事業者とは調整をしているところではあるのですけれども、ただ、通学の付添いなどという話になってくると、その時間帯では補えない部分もありますので、そこは柔軟に対応するようにしたいと考えております。","id":"exchange-113"},{"speaker":"松永委員","kind":"質問","question":"先ほどお答えがなかったのですが、１日にどのくらいの時間数と、例えば午前と午後で分けることができるのかどうか。午前中に１時間、午後に２時間とか、３時間ともう存じておるのですが、その辺、分けられるかどうかだけ教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"失礼いたしました。時間としては、３時間というのを上限とさせていただいておりまして、今、規定している中では、１日当たり１回ということになっておりますので、その３時間を分けて利用するということは想定してございません。","id":"exchange-114"},{"speaker":"松永委員","kind":"質問","question":"そこで、相談体制について伺いますが、相談しにくいと答えた方については、もし相談した場合に、児童相談所に行かないといけない、親から叱責されると言われております。そうした課題も含めて、区としてどのような相談体制を取られているのでしょうか。そして、親への手伝いを逆に苦として思われていない方については、どのように対応されるのでしょうか、伺います。","respondent":"染谷子ども家庭支援センター長","answer":"相談をなかなかしづらいというところのお話は、まさに委員のおっしゃるとおりかと思いまして、そういった意味でもＳＮＳの活用というところで事業を開始したところですが、ＳＮＳ自体を利用できないお子さんも中にはいらっしゃるかと思います。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"そこで、周知啓発についてですけれども、今回、東京オリンピック・パラリンピックのときは、応援競技として３競技挙げられて、マスコットも作られて、いろいろと周知啓発がされていたと思うのですが、今回の予算を拝見しますと、少しそうしたところがないのかなと思うのですが、区としてどのような形で周知啓発されていくのでしょうか、お知らせください。","respondent":"松山障害者支援課長","answer":"次年度におきましても、スポーツ推進課と連携しながら積極的にＰＲをしていきたいと考えております。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ区を挙げて、例えばポスターを独自で作ったりしていただけたらと思います。昨年の７月２９日に天王洲公園のサッカー場で、デフサッカーの日本代表候補トレーニングマッチの交流会が開催されました。そうした中で、ぜひ東京オリンピック・パラリンピックと同じように応援競技として取り入れていただきたいと思いますが、区としてこのデフリンピックに向けての意気込みを最後に伺いたいと思います。","respondent":"松山障害者支援課長","answer":"デフリンピックの応援競技ですが、そちらはスポーツ推進課が所管しておりますので、私どもは周知啓発ということで、当事者団体と手話の理解・普及啓発とともに進めていきたいと考えています。","id":"exchange-117"},{"speaker":"西本委員","kind":"確認","question":"３つ、先に聞きます。プレス発表の２０ページに未就園児定期預かり事業があります。なぜならば、誰でも通園制度ですから、誰でもいいわけですよ。国はどうしてこんなことを考えているのかなと私は非常に憤りを感じるのですが、そのやり方、考え方を教えてください。先ほどそれの確認が取れなかったので、連携の仕方、誰が中心に、どういうふうにこれをまとめていくのかということをお答えください。","respondent":"石井保育支援課長、松山障害者支援課長、藤村子ども育成課長","answer":"逆に、そこの検討会に出席された委員の中では、いやいや、それ以前の人のほうが虐待防止にいいのだと主張される委員もいらっしゃったり、逆に。区の横断的な連携ということで、全体的な会議ですね、保健分野、福祉分野、それから保育・教育分野、横串を通して、何かその中で課題があったのか。児童センターの職員は、ご存じのとおりベテランと若手ということで二極化が進んでいるところはあるのですが。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、その子その子の特徴もありますから、それが今まで品川区のノウハウでもあるわけですから、しっかり取り組んでください。医療的ケア児支援法を見ると、ゼロから１８歳以上という形での字句が書いてあって、そこでのそれぞれのステージによって横串をやりましょうねとなっているので、令和６年度はこれだけやられているのですから、しっかり横串を取るようにしていただきたいと思います。お願いします。","respondent":"今井保育教育運営担当課長","answer":"今回、あり方基本方針の中では、区立保育園のあり方を明確化して役割を明確化した上で、区立保育園が中心となりまして、区内の保育施設全般の質の向上に取り組んでまいりたいと、このように考えているところです。","id":"exchange-119"},{"speaker":"若林委員","kind":"提案","question":"もう一つ、私、会派から、助成制度の提案当初から、全国的に効果検証の仕組みが整えられていないことを指摘し続けてまいりました。補聴器が生活の質の向上、また社会参加や認知症の予防にしっかりと役に立つために、品川区においてはこの点についても助成の拡大とともに引き続き取り組んでほしいということで、再度のお願いですので、今年度等の取組についてお聞かせいただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"それにプラス、新たに来年度からは、認知症の地域支援検討会議という形で、認知症本人、家族の視点を盛り込むというところでは、今年度１月に施行しました認知症基本法に基づきながら、そこの実施に基づいていかに区で認知症施策を推進していけるかというところとともに。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問","question":"認知機能チェックのほうは、大変丁寧な説明、また効果もありがとうあります。要するに軽度認知障害、ＭＣＩですか、ここに近づいているのか、横ばいなのか、遠ざかっているのかというのを定期的に、毎年なのか半年に１回なのか、経年で見ていくことが、定期的に見ていくことが重要ですよということも併せてご提言をしているので、そこについての認識、また考えられていることがあれば教えてください。","respondent":"川原高齢者地域支援課長","answer":"そのような形で約１,０００人を対象に、どのような実施方法が一番よろしいかというのは、すみません、今後検討して、しっかりと前向きに考えていきたいと考えています。そして、２点目、８００人を対象にした予算を超えた場合にはどのような対応をするかというご質問です。","id":"exchange-121"},{"speaker":"えのした委員","kind":"提案","question":"私からは、２５９ページ、ヤングケアラー支援事業、時間があれば２３１ページ、手話理解促進、東京２０２５デフリンピック周知啓発、こちらは先ほど松永委員からもご質問がございましたが、違った視点からお伺いいたします。令和５年度予算特別委員会でも要望等、提案をさせていただきましたが、まずはヤングケアラー支援としてコーディネーターが配置されました。","respondent":"染谷子ども家庭支援センター長","answer":"登録者の１５０人につきましては、当事者だけでなく、その支援者と言われる方たちも登録をいただいておりまして、実際に現時点で相談をお受けしている、メッセージのやり取りをさせていただいている方が継続的に３０人ぐらいいらっしゃるのですが。","id":"exchange-122"},{"speaker":"えのした委員","kind":"確認","question":"幅広い年代と、相談内容も確認が取れました。人材の確保をよろしくお願いいたします。主な取組として、しながわケアラーズ喫茶が昨年の年末から始まりましたが、こちらはピアサポートだと思いますが、内容や参加者人数、今後の方向性をお知らせください。","respondent":"染谷子ども家庭支援センター長","answer":"しながわケアラーズ喫茶ですけれども、こちらは、まずオンライン、ユーチューブでのライブ配信からスタートをいたしまして、その後、大崎ブックカフェを会場として、２月の１２日に１回目の対面での開催をさせていただいておりまして。","id":"exchange-123"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当にコーディネーターの方も一緒ということで、支援のつながり先が重要だと考えますので、引き続き実施の拡充を要望いたします。先ほどもヤングケアラー調査を実施されたということで、調査方法や内容、先ほど答弁がなかった範囲でお知らせいただけますでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"アンケートの結果を確認している中で、年齢層によって、例えば周りの大人にしてほしいことを聞いたものについては、全ての年齢において、自分の話を聞いてほしいという回答はやはり上位に来てはいるのですけれども、年齢が上がるにつれて学習面ですとか、あと進路など。","id":"exchange-124"},{"speaker":"えのした委員","kind":"意見","question":"今、進路などのお話がございましたが、先月２月１７日に、品川区後援の品川総合福祉センター主催「ヤングケアラーのためにできること」、フリーアナウンサーで元ヤングケアラーの町亞聖さん特別講演「全てのケアラーに光を」、一般社団法人彩の国子ども・若者支援ネットワーク理事の土屋匠宇三さんによる「ヤングケアラーの実態とその支援」を広聴してまいりました。","respondent":"染谷子ども家庭支援センター長","answer":"先ほど家事援助の訪問支援についてお話をさせていただきましたが、そのほか、今、委員がおっしゃられた学習支援ですとか、それから、ご家庭への配食支援、お弁当を届けるですとかそういったもの、それからあと。","id":"exchange-125"},{"speaker":"えのした委員","kind":"質問・要望","question":"ヤングケアラーとどうつながるかも重要だと考えます。昨年の１２月に荏原第一地域センターで開催されたケアラー支援研修に参加してきましたが、ヤングケアラーだけでなく若者ケアラー、中年層のケアラーも増えていると感じております。先ほども対象者、ＬＩＮＥの相談者が２５歳以上もいらっしゃるということでしたが、相談者の中にどのくらい１８歳以上のケアラーが存在しているのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"１８歳以上のケアラーにつきましては、現在は、先ほどのオンラインの部分についてはおおむね半々ぐらいの割合ではあるのですが、実際にコーディネーターが対応させていただいている方につきましては。","id":"exchange-126"},{"speaker":"えのした委員","kind":"質問・要望","question":"ケアラーへの理解の促進、または支援の推進を強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。２２５ページの福祉計画費の中の高齢者福祉施設整備費、それから、２５３ページの児童センター運営費の中の事業費についてお尋ねします。先に高齢者福祉施設整備費です。予算編成過程が区のホームページに出ていて、随分前から要望させていただいて、令和２年から公表されて５年になっています。それで、７億８,０００万円のマイナスということになっています。","respondent":"東野福祉計画課長","answer":"こちらですが、確定成立前につきまして、取得費計上分が見送りとなったものです。諦めたわけではございません。今後も引き続き高齢者施設の整備に向け、用地取得に努めてまいりたいと考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"分かりました。高齢者施設の中でもグループホームの取得について動いていると。ただ、取得の現実的な対応の中で、６年度はそこまでの動きではなくて交渉中で、そちらに向けて現在進めていっていただけるということで、安心しました。最初にお聞きしますが、年度末も近いので、この９,９００円の穴埋めはどのような財政の処理をするのかお伺いします。","respondent":"藤村子ども育成課長","answer":"この件については、９,９００円が公金紛失だというところは以前、この決算委員会でも別にお知らせしたとおりですが、こちらの現金紛失につきましては、今後どういった形で対応を取っていくかというのは検討してまいりたいと思っているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"一方、６年度の歳出予算の見積書によると、全体の総務費が３,０９１万円、そのうち指導員等謝礼、これはボランティアも入るのでしょうか、１,０００万円であります。内訳を見ると、４２万円掛ける２５館という表現です。令和４年度は７２０人ということで、１館当たり延べにすると２８人。単価のお話と、それから、有償ボランティアという方々への児童センターとしての評価はどのようなものでしょうか。","respondent":"藤村子ども育成課長","answer":"ボランティアの単価というところですが、今、１,３００円とご案内しているのが今年度までの形なのですが、来年度から１,５００円という形で、すまいるスクールのボランティアが既に１,５００円なのですけれども。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話ししたように雇用関係や、それから、さらに保険についてなど、どのような形になっているのでしょうか。それで、結局２５館共通のマニュアルがあって、そういうお手伝いで非常に貢献していただいている方々を、雇用するというと大げさになるのでしょうか、お手伝いいただく形でマニュアル等があるのか、そちらも伺います。","respondent":"藤村子ども育成課長","answer":"その採用は、最終的には課長の判断にはなってくると思うのですけれども、お支払いの段階、事業の実施の段階で、課長が判断する形になっていると解釈しております。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"事務事業評価でもＣということで、これから増やすという方向で評価されていますので、ぜひ今回の事件を機に、ボランティア一体の管理システムについて、本庁のほうで考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"松本委員","kind":"質問","question":"私からは２３５ページ、中等度難聴児発達支援事業、２４７ページ、補聴器購入費助成事業、２６１ページ、児童相談所運営費、一時保護所運営費について伺います。","respondent":"川原高齢者地域支援課長","answer":"高齢者を対象とした補聴器購入助成のまず趣旨についてのご説明です。","id":"exchange-133"},{"speaker":"松本委員","kind":"意見","question":"この中等度の難聴に関しては、子ども向けにも中等度難聴児発達支援事業がありますが、これも中度の難聴ということで、こちらの制度趣旨、そして今回、予算案では所得制限をこちらもなくすということになっているかと思います。こちらの趣旨と、所得制限をなくす理由もお願いいたします。","respondent":"松山障害者支援課長","answer":"所得制限の考え方ですけれども、こちらは子育て支援の観点からということで、次年度から難聴児の発達支援事業の所得制限を撤廃するものです。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"一方で、１８歳以上で６４歳までの方たちについては、現状、何か補聴器の助成制度があるのか、お伺いいたします。","respondent":"松山障害者支援課長","answer":"１８歳から６４歳までの手帳のない中等度の方への今のところご支援はございません。","id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"そこなのです。そうすると、例えば生活保護を受給されている方であっても、あるいは、学生の方であっても、これはやはり全くないと伺ってよろしいでしょうか。","respondent":"豊嶋生活福祉課長","answer":"治療材料費ということで支給することが可能です。","id":"exchange-136"},{"speaker":"松本委員","kind":"意見","question":"そうすると、これ、各制度の趣旨というのは理解できるのですけれども、やはり公平性という観点からすると、一部の者については所得制限がなく受けられる、同じ中等度の難聴について、一部は所得制限がなく支援を受けられる、でも一部の人は受けられないというのは、公平性の観点からはどう考えたらいいのかということを思うのですけれども、その点についてご見解があればお願いいたします。","respondent":"松山障害者支援課長","answer":"障害者支援課では、１８歳から６４歳で難聴の方につきましては、手帳の取得により支給することができます。１８歳から６４歳までの手帳のない難聴のある方に対しては、支援につきましては全国的にまだ少なく、各自治体での事例もありますので、研究してまいります。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問・要望","question":"これは、むしろ議員側の私の問題かなと思って、昨年７月に高齢者の方たちの支援がスタートしたときに、これに気づかなくて、本当に自分自身、不明だったな、駄目だったなと思うのですけれども、やはり１８歳から６４歳で中等度の方は、生活保護は先ほど確認できましたけれども、やはり支援がないというのは、特に高齢者の方については認知症というお話もあったのですが、ただ。","respondent":"松山障害者支援課長","answer":"今後、１８歳から６４歳までの方をどう考えるかということにつきましては、研究課題とします。","id":"exchange-138"},{"speaker":"松本委員","kind":"意見","question":"もう１問ほかのところ考えていましたが、時間がなくなってしまいました。いずれにせよ、やはりこれは難しい問題だと思いますが、ぜひここは公平性というところ、自分は支援を受けられないのだということがスティグマになってしまいかねませんので、ここはぜひともどうかよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問","question":"今日は民生費です。新井副区長、来年度の予算編成、副区長は初めての参加だと思うのですけれども、この民生費において特徴、そして、何に力を入れたか、それと、子育て・高齢者のバランス、この辺を含めて教えていただけますか。","respondent":"新井副区長","answer":"とりわけ、例えばですけれども決算特別委員会、私も９月に同席させていただきましたけれども、その中で皆さんからお話があった介護職員の処遇改善に関しては、まさにこれは区長の予算査定の大胆な判断だと思いますけれども、５億円という金額をつけて。","id":"exchange-140"},{"speaker":"藤原委員","kind":"確認","question":"次、２４５ページの福祉人材確保・定着事業についてお伺いします。高齢者については、まず品川区の人口構成を伺いたいと思うのですが、私がこの構成のグラフをもう一度見ますと、品川区は、２５歳以上、５歳刻みのグラフを見ると、国と違って理想的な構成比率になっていると思うのです、きれいなピラミッドを描いていて。この辺については、確認ですが、いかがでしょうか。","respondent":"佐藤企画課長","answer":"品川区の場合は、年少人口が同じで大体１１％、生産年齢人口が１０％大きく約６８％、老年人口は逆に１０％低く約２０％で、委員ご紹介のとおり２５歳から大体６４歳ぐらいまでの生産年齢人口が非常に多いです。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問","question":"それを基本にお伺いします。区長、しながわふれあいメッセージの発表会に区長自ら行ってくださったと伺ったのですが、ぜひそのときの感想を伺いたいのですけれども、よろしいでしょうか。","respondent":"森澤区長","answer":"ふれあいメッセージの表彰式で私、表彰を実際にさせていただいたのですが、本当にそれぞれの事業者と、あと、それを出してくださった利用者が、それぞれお言葉をそこで述べられたのですが、私、感極まってしまって。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問・要望","question":"このメッセージ、いいですよね。本当にいいと思います。もう読むのをやめようと思ったのですけれども、この間、公明党の方が、２５年政治の世界にいて、私の基本はこういう思いでやっているのですと。どういうことですか、国は。でも、品川区でどうすることということではない。来年は何色かと楽しみにしておりますので、続けていただきたいことを含め、訪問介護について少し答弁していただけますか。","respondent":"菅野高齢者福祉課長","answer":"ふれあいメッセージのご紹介、ありがとうあります。赤いほうは令和４年度バージョンで、青いほうが令和５年度バージョンというところで、読んでいただきましてありがとうあります。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"処遇改善をいろいろしてくださって、今回も予算に出てきてありがとうあります。だから、この事務的な作業が増えることによってというのが一つ私も懸念があるので、ここに関しては、役所といいますか、行政でバックアップしていっていただきたいのです。よろしくお願いします。その辺について答弁をお願いします。","respondent":"菅野高齢者福祉課長","answer":"高齢者福祉課では、一応どういった内容が変わるのかというところを、今、担当者がいろいろと読み砕いておりまして、研修をウェブ会議でやらせていただこうかなと思っておりまして、それを１回きりではなくて、アーカイブにしてホームページ等でアップさせていただいて。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問・要望","question":"次が２４９ページ、高齢者の住宅あっせん事業ですけれども、これは本当に好評ですね。窓口をつくっていただいて独立をしているわけですけれども、予算でも、たしか決算で伺ったときに、事業が３００％ぐらい上がっているという形で予算取りしますとお約束してくれて、とても好評な事業なので、続けていただきたいし、大きくしていただきたいという思いがあるのです。この答弁をお願いします。","respondent":"川原高齢者地域支援課長、菅野高齢者福祉課長","answer":"それに伴いまして、今後もやはり関係各課と協力して、住宅の助成というのは実施する必要があるということを見込みまして、来年度に関しては現在の予算額の約３倍を予定して、助成も実施をして、拡大してまいりたいと考えています。昨年度までは３階の入り口のフロアのほうに相談窓口があったのですが、やはり戸籍に行かれる方とかお客さんの往来が多いところですので、プライバシーの部分でなかなか難しいというところで、レイアウト変更もしまして。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"バランスを取って、子育てで１つだけお伺いしたいと思うのですけれども、２６９ページ、一本橋保育園改築ですけれども、きれいにできましたね。うちから３０秒ぐらいのところなのですが、ピンクの外壁というのですか。それで、あそこが４月１日からオープンで、民間で新しく保育園ができたということで、その特徴とか、どういう形でやっていくかという説明をしていただけますか。","respondent":"今井保育教育運営担当課長","answer":"一本橋保育園の園舎の改築事業および民営化の内容についてのお問合せにお答えします。こちら一本橋保育園につきましては、荏原第四中学校の跡地を使いまして、令和４年度、５年度ということで２か年かけまして改築工事を実施し、新園舎を整備したところです。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"２８２ページの生活保護費を最後、伺いたいのですけれども、生活福祉という意味で、いつも対面で大変ですよね。どこの職場も大変なのですけれども、福祉系は特にと私は個人的に思っております。でも、できませんと言えないですよね、やれませんと。毎回激しいところでやられていると思うのですけれども、その辺について、もう本当の気持ちを今日お伺いさせていただけますか。","respondent":"豊嶋生活福祉課長","answer":"大変なミッションを任せていただいてありがたいと考えていますが、なかなかやはり……。でも頑張ります。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問","question":"そうですよね。頑張る。ただ、やはり人間ですから、頑張り過ぎてしまうというのもいろいろ個人差があると思いますが、ただ、どこかの職員を含めて、幹部職員も含めて、やはりそういうところで、「少しきついのだけど」と言えるような役所のシステムにしていかないといけないと、私は思っています。でも、いつもそういう思いがあったので、こういう形で質問させていただきました。どうもすみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、５１３ページからの介護保険、それから、２４１ページの入院中の紙おむつ代助成事業、それから、介護や障害者の人材不足問題について伺いたいと思います。それから、少し中身に入らせていただきます。それなので、高齢者の３分の１しかこの制度を受けられないという状況になっています。予算でも６４９万円ですから、ぜひこれも所得制限撤廃をしていただきたいと思うのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"お尋ねの入院時の紙おむつ代の助成についてです。こちらの事業については、事業の目的として、入院時に一時的に治療費等の負担が増す中で、さらに紙おむつ代の負担が加わることから、低所得者の方の経済的負担軽減対策として実施しているというところが理由となっております。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"大体ひとり暮らしですと１５５万円、６万円の方はもう課税になってしまうわけですから、ぎりぎり生活している方もこれから外れるということで、今回こういうふうに方針が今までよりもずっと大きく前進しましたので、その考え方で、ぜひとも所得制限の撤廃を強く要望しておきたいと思います。２つ目に、介護や障害者福祉の現場での深刻な人手不足について伺いたいと思います。異常な状況ですよね。","respondent":"菅野高齢者福祉課長","answer":"区としても、実態調査をしないからといって介護職場の実態が分からないというわけではなくて、日々事業者と意見交換等もさせていただきながら、法人とも聞きながら、少しでもどんな支援ができるかというところで今回考えさせていただいたのが、居住支援手当とか。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は、本当に私たちが聞いただけでも大変な実態、行くところ行くところそういう感じですから、大変な実態というのはもちろんつかまれていると思うのですが、それをデータにするというところまでぜひしていただいて、そして、根拠のあるものとしてぜひ言っていっていただきたいなという希望です。改めてこれは検討していただきたいと思いますが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"第９期介護保険事業計画においても、この在宅介護支援システムを採用した仕組みづくりは、継続して行ってまいりたいと思っているところです。","id":"exchange-151"},{"speaker":"大倉委員","kind":"質問","question":"２４５ページ、福祉人材確保・定着事業と品川介護福祉専門学校、あと、２７３ページの保幼小ジョイント事業、保幼小の連携というところで伺います。学校の先生や保育園の先生側の視点、小一プロブレムの解消を目指して行っているというところでは、実際そこへの解消の視点ではどういうふうに行われてきたのか、どうなっているのか、またほかに異なる視点があったら教えていただければと思います。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"保幼小のジョイント事業、今、名称がそうなっておりますが、開始当初は保幼小交流事業ということで、平成１９年からスタートしております。内容としましては、介護福祉士資格を持つ介護職員１人当たりの紹介手数料が平均８９万円という調査結果が報道されたこと、そして、区内においても、人材確保のため高い手数料を支払わざるを得ない状況だという声を聞いていたこと。","id":"exchange-152"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば保育園側で見ると、希望する保育園がしっかりとそういった連携がきちんと取れているのかどうかというところを教えてください。コロナのところは３年間休止をされていたということで、少し伺おうかなと思っていたのですが、休止をされていたところではどんな影響があったかとか、その３年間の部分について少し教えてください。福祉人材ですが、５０万円で１０人分ということで分かりました。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"ジョイント事業に関しましては、小学校・義務教育学校の前期課程全校で一応実施という形を取っていただいておりますで、そこに対して区立保育園４０園、それから、区立幼稚園９園、全部です。区内の施設や介護サービス事業所で３年間の勤務実績により貸付金の返済が免除される奨学金制度を創設して、地域で活躍する福祉人材の養成に努めてまいりました。","id":"exchange-153"},{"speaker":"大倉委員","kind":"確認","question":"それで、先ほど伺うのを忘れたのですが、紹介料の補助のところで、少し前に転職のニュースとかでも出ていたのですが、国のほうでも転職ビジネスのお祝い金というのが問題になったりして、それはそれで問題になったりしたのですが、この事業の継続性というところで、これを使った人たちがどの程度継続していくとかという、その後追いというか、しっかりと継続をしているかどうか。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"こちらの事業はやはり大切な事業だと思いますので、今後も小学校・義務教育学校と連携をしっかり取りながら、事業としては進めてまいりたいと思います。そういった意味でも、適正な有料職業紹介所の認定制度等を国が設けているわけですけれども、そういった中では、区としても、一時的なここに頼らざるを得ないという状況をまずは緊急的に措置するというところで。","id":"exchange-154"},{"speaker":"大倉委員","kind":"確認","question":"保幼小のほうは、これは教育費でもやろうかなと思っているのですが、保育園側としては、しっかりと連携を取りながら、受け入れてもらいながら進めていきたいということが確認できましたので、ありがとうあります。福祉人材確保のところでは、継続性をしっかり確認をしながら進めていっていただければと思いますので、よろしくお願いします。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２７１ページ、保育入園調整事務費、２４９ページ、高齢者住宅対策事業、時間があれば２６７ページ、ひとり親家庭自立等支援でＡＤＲについて聞いてまいります。昨年の決算特別委員会で多胎児の子どもの命、ご家庭を守る観点から、保育園入園選考時の調整指数について加点を求めました。一番気になるところですが、申請をされた多胎児の皆さんが無事に入園できたのかどうか、お知らせください。","respondent":"立木保育課長","answer":"その内訳、例えば双子の方、三つ子の方、兄弟児の方というのは統計的に今取っておりませんので、お答えすることができません。そのうち内定が出ておりますのが、一次が、９９人中８４人が内定となっております。不承諾が１５人ということになっております。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その際、もう１点要望しておったのですが、保育園のご案内、これは８０ページ近くになって、非常にびっしりと大切な情報が入っているのですが、パソコンやスマホで見たときに、写真データで、知りたい情報が検索できないと。それについて検索できるようにというお願いをして、これもたしかすぐにやっていただいたと思うのですけれども、これはいつから文字検索ができるようになったのか教えてください。","respondent":"立木保育課長","answer":"こちらもご要望をいただいた中で、実際、画像から、一から文字起こしをいたしまして改めて作り直したことで少し時間がかかってしまいまして、ご案内を掲載してから、１月にはもう検索できるような形にしています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これも保活の団体からかなり前から上がっていった要望なのですけれども、対応いただいてありがとうございました。次に、高齢者住宅対策事業について伺ってまいります。先週は、９０代の女性で大家から立ち退きを言われているという結構むちゃな話も、ご相談に伺いました。不動産屋にも確認したのですけれども。入居促進事業の窓口である高齢者地域支援課ではどのように認識をされているか、伺います。","respondent":"川原高齢者地域支援課長","answer":"こういった住宅課と連携した助成事業が拡大するに伴って、やはり窓口の件数、高齢者のいらっしゃる方の件数も非常に増えておりますので、それに伴って、高齢者の方を対象とでき得る不動産会社、先ほど委員にもご意見をいただきましたとおり。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"不動産事業者にも伺ったのですが、レインズというパソコンをたたきますよね、みんな不動産屋に行くと。でも、あまり時間ないかな。これは、やはり品川区として高齢者の住まいについてしっかりとお考えをいただいて、拡大をしている。これはどうですかと聞こうと思ったのですが、もう多分答弁の時間がないので、これは一応総括でもうちの会派でやりますので、今日はこれでおしまいにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。２３１ページ、東京２０２５デフリンピック周知啓発、同じページの手話理解促進、２３７ページ、心身障害者福祉会館運営費についてお伺いをいたします。２０２５のデフリンピックの周知啓発というのは会派としても要望をさせていただいている中で、本区では競技はございませんけれども、近隣の大田区ではビーチバレーがふるさとの浜辺公園で開催されると聞いております。","respondent":"松山障害者支援課長","answer":"デフリンピックの周知啓発に関する、前年度から４万円ほど減になっているものでしょうか。これは啓発グッズの内容の違いによるものです。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません。その内容というのは、どういうものからどういうふうに変わったか、種類というのですか、教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"今年度はボールペンを作ったのですけれども、それで、いろいろデフリンピックのイベントで配らせていただいたのですけれども、来年度は少しまだ精査はしているのですけれども、ほとんど、４万円程度なので、同じぐらいのものを考えているところです。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。同程度のものということで認識をしておきますので、よろしくお願いします。それと、同じページなのですけれども、手話理解促進事業についても、本年度当初予算と比較して半減しているのですけれども、本年度が１１５万円余、来年度は５３万円余なのですけれども、この理由もどうなのか、教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"内容ですけれども、今年度も実施していました区職員向けとか区民向け、子ども向け、事業者向けの手話講座があります。障害者支援課の窓口で手話通訳者の配置を３日間行っていたのですが、来年度から、３日から５日に増やすという費用があります。","id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ありがとうございました。確認をさせてもらいました。この認知度向上を含めて、款は違うのですけれども、来年度１１月ですか、今年の１１月ですよね。周知啓発の１年前記念イベントがあると思うのですけれども、障害者支援課としても啓発ブースを考えておられると思うのですが、来年度なので、現時点でどういうふうにやっていこうかという何かあれば、教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"デフリンピックの周知啓発ですけれども、今年度と同様にスポーツ推進課と連携しながらイベントは行うのですが、例えばさらに考えられる工夫といたしましては、ちょうど１１月に開催されるので、その前に、９月ぐらいに、例年ですと福祉まつりを行っております。","id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いをしたいと思います。要望としてよろしくお願いいたします。それと、２３７ページ、心身障害者福祉会館運営費についてお尋ねをします。心身障害者福祉会館の運営に当たって、利用者から指定管理者に多数意見が寄せられていると思います。いろいろな利用者がいるので相当数だと思いますけれども、区はこれをどのように把握して対応しているのか、教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館指定管理者に寄せられた声の把握と対応についてです。定期的に毎月１回、心身障害者福祉会館の指定管理者と、障害者支援課と打合せを行っております。","id":"exchange-164"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これに関してまた３月４日ですか、最近、ケーブルテレビでもこれから３回、１回放送されているのかな、４回放送されるというところで、東京都福祉保健局のホームページによると、高次脳機能障害は失語、注意障害、記憶障害などの症状があると思いますけれども、私のこの認識でよろしいのかどうか、失語症があるというのも含めてお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"高次脳機能障害のうちの障害で現れる症状の一つとして、失語症は委員のご認識どおり、あります。","id":"exchange-165"},{"speaker":"高橋（伸）委員","kind":"確認","question":"本当にこの高次脳機能障害自体が、当然、これは見えない障害と言われております。それと、ホームページも確認したのですけれども、失語症の方向けの意思疎通支援者養成講習会があると思いますので、ぜひこれも周知徹底をよろしくお願いいたします。ありがとうございました。","respondent":"松山障害者支援課長","answer":"失語症に対する講習会についても、ホームページで掲載をしています。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/359306?Template=document&Id=6691#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":131239,"voices":388}}]);
